app/globals.css:
@import "tailwindcss";

:root {
  --navy: #203a55;
  --navy-deep: #132c43;
  --teal: #227d91;
  --teal-dark: #17677a;
  --ink: #172b3a;
  --muted: #5f707c;
  --cream: #f6f5f1;
  --paper: #ffffff;
  --line: #dbe4e8;
  --mist: #e7ecef;
  --success: #166b55;
  --danger: #a63c37;
  --radius: 22px;
  --shadow: 0 22px 60px rgba(25, 51, 70, 0.12);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; background: var(--cream); color: var(--ink); font-family: Arial, Helvetica, sans-serif; line-height: 1.6; }
a { color: inherit; text-decoration: none; }
button, input, textarea, select { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
:focus-visible { outline: 3px solid #4fb4c8; outline-offset: 3px; }
/* Suppress browser click outlines only when its keyboard-focus heuristic is
   inactive. The visible-focus rules above/below remain the keyboard fallback. */
:focus:not(:focus-visible) { outline: none; }
::selection { color: white; background: var(--teal); }

.shell { width: min(1180px, calc(100% - 40px)); margin-inline: auto; }
.site-header { position: sticky; top: 0; z-index: 50; background: color-mix(in srgb, var(--cream) 92%, transparent); border-bottom: 1px solid rgba(32,58,85,.09); backdrop-filter: blur(16px); }
.header-inner { min-height: 78px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.brand { display: inline-flex; align-items: center; gap: 12px; font-size: .84rem; font-weight: 800; letter-spacing: .11em; color: var(--navy); }
.brand .brand-logo { width: 52px; height: 52px; border-radius: 8px; }
/* Preserve the supplied 500px PNG. Only empty alpha padding falls outside the
   frame: artwork bounds are (63,108)–(437,433); at 125% every painted pixel fits. */
.brand-logo { position: relative; display: inline-block; flex-shrink: 0; overflow: hidden; vertical-align: middle; background: #e9e5dd; }
.brand-logo > img { position: absolute; width: 125%; height: 125%; max-width: none; left: -12.5%; top: -17.625%; object-fit: contain; border: 0; border-radius: 0; padding: 0; background: transparent; }
.nav { display: flex; align-items: center; gap: 26px; font-size: .92rem; font-weight: 700; color: #405563; }
.nav a:hover { color: var(--teal-dark); }
.nav .button { color: white; }
.menu-button { display: none; border: 0; background: transparent; color: var(--navy); padding: 8px; }
.button { display: inline-flex; min-height: 48px; align-items: center; justify-content: center; gap: 9px; padding: 0 20px; border-radius: 999px; border: 1px solid transparent; background: var(--navy); color: white; font-weight: 800; cursor: pointer; transition: transform .2s ease, background .2s ease; }
.button:hover { transform: translateY(-2px); background: var(--navy-deep); }
.button-secondary { background: transparent; border-color: #9eb2bc; color: var(--navy); }
.button-secondary:hover { background: white; }
.button-small { min-height: 40px; padding-inline: 16px; font-size: .88rem; }
.button:disabled { opacity: .55; cursor: not-allowed; transform: none; }

.eyebrow { margin: 0 0 14px; color: var(--teal-dark); font-size: .75rem; font-weight: 900; letter-spacing: .17em; text-transform: uppercase; }
.display { margin: 0; color: var(--navy-deep); font-family: Georgia, 'Times New Roman', serif; font-size: clamp(3.2rem, 7vw, 6.7rem); font-weight: 500; letter-spacing: -.055em; line-height: .92; }
.display em { color: var(--teal); font-style: normal; }
.lede { max-width: 620px; margin: 24px 0 0; color: var(--muted); font-size: clamp(1rem, 2vw, 1.18rem); }
.hero { position: relative; min-height: 760px; overflow: clip; border-bottom: 1px solid var(--line); background: radial-gradient(circle at 78% 35%, #e1eff0 0, transparent 30%), var(--cream); }
.hero-grid { position: relative; z-index: 2; display: grid; grid-template-columns: .9fr 1.1fr; min-height: 690px; align-items: center; }
.hero-copy { position: relative; z-index: 3; padding: 80px 0 120px; }
.hero-copy .display { font-size: clamp(3.4rem, 6.3vw, 6.1rem); }
.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 32px; }
.hero-note { display: flex; align-items: center; gap: 10px; margin-top: 25px; color: #667985; font-size: .82rem; }
.hero-note::before { content: ''; width: 24px; height: 1px; background: var(--teal); }
.scene-wrap { position: absolute; inset: 72px max(0px, calc((100vw - 1240px) / 2)) 0 43%; z-index: 4; min-height: 620px; pointer-events: none; }
.scene-controls { position: absolute; right: 22px; top: 20px; z-index: 5; pointer-events: auto; }
.motion-toggle { display: inline-flex; gap: 8px; align-items: center; border: 1px solid rgba(32,58,85,.15); border-radius: 999px; background: rgba(255,255,255,.82); padding: 8px 12px; color: var(--navy); font-size: .75rem; font-weight: 800; box-shadow: 0 8px 28px rgba(22,50,70,.08); }
.scene-fallback { height: 100%; min-height: 560px; display: grid; place-items: center; }
.fallback-art { position: relative; width: min(620px, 90%); aspect-ratio: 1.35; border-radius: 45% 45% 14% 14%; background: linear-gradient(#e0eff1 0 58%, #cad5da 58% 63%, #70818b 63% 74%, #dfe6e7 74%); overflow: hidden; }
.fallback-truck { position: absolute; left: 18%; bottom: 24%; width: 57%; height: 26%; border-radius: 10px 18px 7px 7px; background: var(--navy); box-shadow: inset -28px 0 var(--teal); }
.fallback-truck::before { content:''; position:absolute; left:-22%; bottom:0; width:28%; height:76%; background:var(--teal); border-radius:24px 4px 5px 5px; }
.fallback-truck::after { content:''; position:absolute; left:-13%; bottom:-18px; width:34px; height:34px; border:8px solid #26333a; border-radius:50%; background:#8ea0a9; box-shadow:205px 0 0 -8px #8ea0a9, 205px 0 0 0 #26333a; }

.section { padding: 112px 0; }
.section-compact { padding: 76px 0; }
.section-white { background: white; }
.section-navy { background: var(--navy-deep); color: white; }
.section-head { display: flex; align-items: end; justify-content: space-between; gap: 30px; margin-bottom: 46px; }
.section-head h2, .page-hero h1 { margin: 0; color: var(--navy-deep); font-family: Georgia, 'Times New Roman', serif; font-size: clamp(2.4rem, 5vw, 4.4rem); font-weight: 500; letter-spacing: -.04em; line-height: 1; }
.section-head p { max-width: 500px; margin: 0; color: var(--muted); }
.cards { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.card { position: relative; padding: 36px; border: 1px solid var(--line); border-radius: var(--radius); background: white; box-shadow: 0 12px 35px rgba(26,54,74,.06); }
.card-dark { min-height: 370px; overflow: hidden; background: var(--navy); color: white; border-color: transparent; }
.card-dark:nth-child(2) { background: var(--teal-dark); }
.card h3 { margin: 22px 0 10px; color: inherit; font-family: Georgia, 'Times New Roman', serif; font-size: 2rem; font-weight: 500; }
.card p { margin: 0 0 24px; color: inherit; opacity: .78; }
.card-icon { display: grid; width: 50px; height: 50px; place-items: center; border: 1px solid currentColor; border-radius: 50%; opacity: .8; }
.text-link { display: inline-flex; align-items: center; gap: 7px; font-weight: 800; }
.card-orbit { position: absolute; width: 260px; height: 260px; right: -80px; bottom: -100px; border: 1px solid rgba(255,255,255,.2); border-radius: 50%; }
.card-orbit::before, .card-orbit::after { content:''; position:absolute; inset:30px; border:1px solid rgba(255,255,255,.15); border-radius:50%; }
.card-orbit::after { inset:70px; }
.steps { display: grid; grid-template-columns: repeat(4,1fr); border-top: 1px solid var(--line); }
.step { padding: 32px 26px 10px 0; }
.step-number { display: block; margin-bottom: 40px; color: var(--teal); font-size: .75rem; font-weight: 900; }
.step h3 { margin: 0 0 8px; color: var(--navy); font-size: 1rem; }
.step p { margin: 0; color: var(--muted); font-size: .92rem; }
.quote-band { display: grid; grid-template-columns: 1.2fr .8fr; align-items: center; gap: 30px; padding: 70px; border-radius: 32px; background: var(--navy-deep); color: white; }
.quote-band h2 { margin: 0; max-width: 700px; font-family: Georgia, serif; font-size: clamp(2.3rem, 5vw, 4rem); font-weight: 500; line-height: 1; }
.quote-band p { color: #c7d5dc; }
.quote-band .band-action { justify-self: end; }
.quote-band .button { background: #57b4c5; color: var(--navy-deep); }

.page-hero { padding: 100px 0 76px; border-bottom: 1px solid var(--line); background: radial-gradient(circle at 78% 20%, #ddecf0, transparent 30%); }
.page-hero h1 { max-width: 900px; }
.page-hero .lede { max-width: 720px; }
.content-grid { display: grid; grid-template-columns: .75fr 1.25fr; gap: 70px; }
.content-grid aside { color: var(--teal-dark); font-size: .78rem; font-weight: 900; letter-spacing: .13em; text-transform: uppercase; }
.prose h2 { margin: 0 0 18px; color: var(--navy); font-family: Georgia, serif; font-size: 2.1rem; font-weight: 500; }
.prose h3 { color: var(--navy); }
.prose p, .prose li { color: var(--muted); }
.prose section + section { margin-top: 54px; padding-top: 44px; border-top: 1px solid var(--line); }

.form-shell { display: grid; grid-template-columns: .7fr 1.3fr; gap: 60px; align-items: start; }
.form-panel { padding: 40px; border: 1px solid var(--line); border-radius: 26px; background: white; box-shadow: var(--shadow); }
.form-section { margin: 0 0 34px; padding: 0 0 30px; border: 0; border-bottom: 1px solid var(--line); }
.form-section:last-of-type { border-bottom: 0; }
.form-section legend { width: 100%; margin-bottom: 20px; color: var(--navy); font-family: Georgia, serif; font-size: 1.45rem; }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.field { display: flex; flex-direction: column; gap: 7px; }
.field-full { grid-column: 1 / -1; }
.field label { color: #354b5a; font-size: .84rem; font-weight: 800; }
.field input, .field textarea, .field select { width: 100%; min-height: 50px; padding: 12px 14px; border: 1px solid #b9c8cf; border-radius: 10px; background: #fbfcfc; color: var(--ink); }
.field textarea { min-height: 118px; resize: vertical; }
.field small { color: var(--muted); }
.field-error { color: var(--danger) !important; font-size: .78rem; }
.form-status { margin: 20px 0; padding: 16px; border-radius: 10px; background: #e7f3ee; color: var(--success); }
.form-status.error { background: #f8eaea; color: var(--danger); }
.honeypot { position: absolute; left: -10000px; width: 1px; height: 1px; overflow: hidden; }
.side-note { position: sticky; top: 120px; }
.side-note h2 { margin: 0 0 15px; color: var(--navy); font-family: Georgia, serif; font-size: 2.2rem; font-weight: 500; }
.side-note p { color: var(--muted); }
.notice { padding: 18px 20px; border: 1px solid #bdd1d8; border-left: 4px solid var(--teal); border-radius: 10px; background: #edf5f6; color: #34515f; }

.faq-list { border-top: 1px solid var(--line); }
.faq-item { border-bottom: 1px solid var(--line); }
.faq-item summary { display: flex; justify-content: space-between; gap: 20px; padding: 25px 0; color: var(--navy); font-weight: 800; cursor: pointer; list-style: none; }
.faq-item summary::after { content:'+'; color:var(--teal); font-size:1.4rem; }
.faq-item[open] summary::after { content:'−'; }
.faq-item p { margin: -7px 0 28px; max-width: 780px; color: var(--muted); }

.site-footer { padding: 70px 0 28px; background: #10283c; color: white; }
.footer-grid { display: grid; grid-template-columns: 1.5fr repeat(2, .75fr); gap: 60px; }
.footer-brand p { max-width: 450px; color: #aebfc9; }
.footer-col h3 { margin-top: 0; font-size: .78rem; letter-spacing: .12em; text-transform: uppercase; color: #81c4cf; }
.footer-col a { display: block; margin: 9px 0; color: #d1dce1; font-size: .9rem; }
.footer-bottom { display: flex; justify-content: space-between; gap: 20px; margin-top: 58px; padding-top: 22px; border-top: 1px solid rgba(255,255,255,.12); color: #92a7b3; font-size: .78rem; }

.admin-body { background: #edf1f3; }
.admin-shell { display: grid; grid-template-columns: 250px 1fr; min-height: 100vh; }
.admin-nav { position: sticky; top: 0; height: 100vh; padding: 28px 22px; background: var(--navy-deep); color: white; }
.admin-nav .brand { color: white; }
.admin-links { display: grid; gap: 4px; margin-top: 38px; }
.admin-links a { padding: 10px 12px; border-radius: 8px; color: #bfd0d8; font-size: .9rem; }
.admin-links a:hover { background: rgba(255,255,255,.08); color: white; }
.admin-main { min-width: 0; padding: 42px; }
.admin-head { display:flex; justify-content:space-between; align-items:end; margin-bottom:28px; }
.admin-head h1 { margin:0; color:var(--navy); font-family:Georgia,serif; font-size:2.3rem; font-weight:500; }
.stat-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:16px; }
.stat { padding:24px; border:1px solid var(--line); border-radius:16px; background:white; }
.stat strong { display:block; color:var(--navy); font-size:2rem; }
.stat span { color:var(--muted); font-size:.82rem; }
.data-card { margin-top:22px; padding:24px; border:1px solid var(--line); border-radius:16px; background:white; overflow:auto; }
.data-card h2 { margin-top:0; color:var(--navy); font-size:1.1rem; }
.data-table { width:100%; border-collapse:collapse; font-size:.86rem; }
.data-table th { padding:12px; text-align:left; color:var(--muted); border-bottom:1px solid var(--line); }
.data-table td { padding:14px 12px; border-bottom:1px solid #edf1f3; white-space:nowrap; }
.pill { display:inline-block; padding:4px 9px; border-radius:999px; background:#e5f2f3; color:var(--teal-dark); font-size:.72rem; font-weight:800; text-transform:capitalize; }
.empty { padding:45px 20px; text-align:center; color:var(--muted); }
.setup-card { max-width:680px; padding:30px; border:1px solid #d7cba7; border-radius:16px; background:#fff9e7; }
.login-wrap { min-height:100vh; display:grid; place-items:center; padding:24px; background:var(--navy-deep); }
.login-card { width:min(440px,100%); padding:40px; border-radius:22px; background:white; box-shadow:var(--shadow); }
.login-card h1 { margin-top:0; color:var(--navy); font-family:Georgia,serif; font-weight:500; }

@media (max-width: 900px) {
  .menu-button { display: inline-flex; }
  .nav { position: fixed; inset: 79px 0 auto; display: none; padding: 24px 20px 30px; flex-direction: column; align-items: stretch; background: var(--cream); border-bottom: 1px solid var(--line); }
  .nav.open { display: flex; }
  .hero { min-height: 850px; }
  .hero-grid { display:block; min-height: 800px; }
  .hero-copy { width: 68%; padding-top:70px; }
  .scene-wrap { inset: 420px -80px 0 25%; opacity:.86; min-height:430px; }
  .steps { grid-template-columns: repeat(2,1fr); }
  .content-grid, .form-shell { grid-template-columns:1fr; gap:35px; }
  .side-note { position:static; }
  .admin-shell { grid-template-columns:1fr; }
  .admin-nav { position:static; width:100%; height:auto; }
  .admin-links { grid-template-columns:repeat(4,1fr); }
  .admin-main { padding:26px; }
  .stat-grid { grid-template-columns:repeat(2,1fr); }
}

@media (max-width: 640px) {
  .shell { width:min(100% - 28px,1180px); }
  .header-inner { min-height:68px; }
  .brand { font-size:.72rem; }
  .nav { top:69px; }
  .hero { min-height:950px; }
  .hero-grid { min-height:910px; }
  .hero-copy { width:100%; padding:58px 0 0; }
  .hero-copy .display { font-size:clamp(3.15rem,16vw,4.5rem); }
  .hero-copy .lede { max-width:92%; font-size:.96rem; }
  .scene-wrap { inset:610px -100px -40px -90px; opacity:.82; min-height:330px; }
  .scene-controls { right:auto; left:104px; }
  .motion-toggle span { display:none; }
  .section { padding:76px 0; }
  .section-head { display:block; }
  .section-head p { margin-top:18px; }
  .cards, .steps, .footer-grid, .quote-band { grid-template-columns:1fr; }
  .card { padding:26px; }
  .card-dark { min-height:310px; }
  .quote-band { padding:36px 26px; }
  .quote-band .band-action { justify-self:start; }
  .form-panel { padding:24px 18px; }
  .form-grid { grid-template-columns:1fr; }
  .field-full { grid-column:auto; }
  .footer-grid { gap:30px; }
  .footer-bottom { flex-direction:column; }
  .admin-links { display:flex; overflow-x:auto; }
  .admin-main { padding:20px 14px; }
  .stat-grid { grid-template-columns:1fr 1fr; gap:10px; }
  .stat { padding:18px; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior:auto; }
  *, *::before, *::after { animation-duration:.01ms !important; animation-iteration-count:1 !important; transition-duration:.01ms !important; }
}

/* Immersive courier system */
:root {
  --scene-line: rgba(67, 187, 205, .34);
  --scene-glow: rgba(55, 177, 197, .18);
  --deep-shadow: 0 28px 80px rgba(8, 31, 48, .17), 0 4px 12px rgba(8, 31, 48, .08);
}

body { background: #f3f2ed; background-image: linear-gradient(rgba(32,58,85,.026) 1px, transparent 1px), linear-gradient(90deg, rgba(32,58,85,.026) 1px, transparent 1px); background-size: 42px 42px; }
.site-header { top: 10px; width: min(1240px, calc(100% - 24px)); margin: 10px auto 0; border: 1px solid rgba(255,255,255,.7); border-radius: 18px; background: rgba(247,246,241,.85); box-shadow: 0 16px 50px rgba(14,42,60,.1); }
.header-inner { min-height: 70px; padding-inline: 12px 14px; }
.brand .brand-logo { width: 48px; height: 48px; padding: 3px; border: 1px solid rgba(32,58,85,.13); border-radius: 10px; background: #e9e5dd; box-shadow: 0 7px 18px rgba(14,42,60,.14); object-fit: cover; }
.nav { gap: 20px; }
.nav > a:not(.button) { position: relative; padding-block: 10px; }
.nav > a:not(.button)::after { content: ""; position: absolute; left: 0; right: 100%; bottom: 5px; height: 2px; background: var(--teal); transition: right .24s ease; }
.nav > a:hover::after, .nav > a:focus-visible::after { right: 0; }
.nav .motion-toggle { margin-left: -6px; }
.header-inner > .motion-toggle { order: 2; }
.header-inner > .nav { order: 1; margin-left: auto; }
.header-inner > .menu-button { order: 3; }
.motion-toggle { cursor: pointer; transition: transform .2s ease, border-color .2s ease, background .2s ease; }
.motion-toggle:hover { transform: translateY(-2px); border-color: rgba(34,125,145,.5); }
.route-transition { position: fixed; z-index: 90; top: 0; left: 0; width: 100%; height: 3px; pointer-events: none; overflow: hidden; }
.route-transition span { display: block; width: 42%; height: 100%; border-radius: 99px; background: linear-gradient(90deg, transparent, var(--teal), #64d2df, transparent); animation: route-enter .72s cubic-bezier(.2,.8,.2,1) both; }
@keyframes route-enter { from { transform: translateX(-110%); } to { transform: translateX(350%); } }

.hero { min-height: 720px; margin-top: -90px; padding-top: 90px; isolation: isolate; background: radial-gradient(circle at 83% 32%, rgba(72,183,200,.19), transparent 31%), radial-gradient(circle at 64% 70%, rgba(255,255,255,.9), transparent 35%), #f2f1ec; }
.hero::before { content: ""; position: absolute; z-index: 0; inset: 18% -6% -25% 44%; border: 1px solid var(--scene-line); border-radius: 50%; transform: rotate(-11deg); box-shadow: 0 0 0 38px rgba(34,125,145,.025), 0 0 0 78px rgba(34,125,145,.018); }
.hero-grid { min-height: 650px; grid-template-columns: .82fr 1.18fr; }
.hero-copy { max-width: 590px; padding: 112px 0 110px; }
.hero-copy .display { font-size: clamp(3.4rem, 6vw, 6.25rem); line-height: .91; }
.hero-support { margin: 22px 0 0; color: var(--navy); font-size: clamp(1.25rem, 2.2vw, 1.85rem); font-weight: 800; letter-spacing: -.025em; }
.hero-copy .lede { margin-top: 13px; max-width: 550px; }
.hero-scene { position: absolute; z-index: 1; top: 72px; right: max(-90px, calc((100vw - 1380px) / -2)); bottom: 18px; left: 42%; min-height: 600px; }

.scene-stage { position: relative; min-height: 480px; overflow: hidden; border: 1px solid rgba(255,255,255,.62); border-radius: 34px; background: radial-gradient(circle at 52% 25%, rgba(255,255,255,.92), rgba(215,233,233,.52) 44%, rgba(196,215,218,.6)); box-shadow: var(--deep-shadow); isolation: isolate; }
.scene-stage::after { content: ""; position: absolute; z-index: 3; inset: auto 8% 6% 8%; height: 20%; border-radius: 50%; background: rgba(20,50,70,.12); filter: blur(32px); pointer-events: none; }
.scene-stage canvas { position: relative; z-index: 2; width: 100% !important; height: 100% !important; min-height: inherit; }
.scene-stage-compact { min-height: 330px; border-radius: 26px; }
.scene-horizon { position: absolute; z-index: 1; left: 7%; right: 7%; bottom: 20%; height: 1px; background: linear-gradient(90deg, transparent, rgba(34,125,145,.3), transparent); }
.scene-caption { position: absolute; z-index: 5; right: 18px; bottom: 14px; color: rgba(20,48,65,.54); font-size: .64rem; font-weight: 800; letter-spacing: .11em; text-transform: uppercase; pointer-events: none; }
.page-hero-international .scene-stage, .site-footer .scene-stage, .login-wrap .scene-stage { border-color: rgba(88,190,207,.18); background: radial-gradient(circle at 58% 32%, #174967, #091d2e 64%, #061622); }
.page-hero-international { color: white; background: radial-gradient(circle at 78% 22%, rgba(43,150,173,.3), transparent 35%), #0b2539; }
.page-hero-international h1 { color: white; }
.page-hero-international .lede { color: #b8ccd5; }
.page-hero-international .eyebrow { color: #66cad9; }
.page-hero-international .scene-caption, .site-footer .scene-caption, .login-wrap .scene-caption { color: rgba(196,230,236,.48); }

.page-hero { min-height: 610px; margin-top: -90px; padding: 150px 0 64px; overflow: hidden; }
.page-hero-grid { display: grid; grid-template-columns: minmax(0, .9fr) minmax(420px, 1.1fr); gap: 56px; align-items: center; }
.page-hero-copy { position: relative; z-index: 4; }
.page-hero h1 { max-width: 650px; font-size: clamp(2.7rem, 5vw, 4.85rem); }
.page-hero .scene-stage { min-height: 390px; box-shadow: none; border-color: rgba(255,255,255,.38); background-color: transparent; }

.journey-section .scene-stage, .process-section .scene-stage { margin-bottom: 24px; }
.journey-section .cards { margin-top: -78px; position: relative; z-index: 5; padding: 0 24px; }
.dimensional-card { min-height: 350px; transform-style: preserve-3d; transition: transform .35s cubic-bezier(.2,.8,.2,1), box-shadow .35s ease; box-shadow: 0 30px 56px rgba(8,34,52,.2); }
.dimensional-card:hover, .dimensional-card:focus-visible { transform: perspective(1000px) rotateX(2deg) rotateY(-2deg) translateY(-8px); box-shadow: 0 40px 70px rgba(8,34,52,.3); }
.dimensional-card:nth-child(2):hover, .dimensional-card:nth-child(2):focus-visible { transform: perspective(1000px) rotateX(2deg) rotateY(2deg) translateY(-8px); }
.dimensional-card > * { position: relative; z-index: 2; }
.mini-road, .mini-globe { position: absolute; z-index: 1; right: 24px; top: 27px; width: 138px; height: 98px; opacity: .65; transform: translateZ(28px); pointer-events: none; }
.mini-road { border-bottom: 18px solid rgba(255,255,255,.25); border-radius: 0 0 55% 45%; transform: rotate(-8deg) translateZ(28px); }
.mini-road span { position: absolute; right: 18px; bottom: -9px; width: 48px; height: 24px; border-radius: 6px 10px 4px 4px; background: #66c4d2; box-shadow: inset -16px 0 rgba(255,255,255,.25); }
.mini-road i { position: absolute; right: 22px; bottom: -14px; width: 12px; height: 12px; border: 3px solid #0d2639; border-radius: 50%; box-shadow: 26px 0 0 -3px #68808a, 26px 0 0 0 #0d2639; }
.mini-globe { width: 94px; height: 94px; border: 1px solid rgba(255,255,255,.35); border-radius: 50%; background: repeating-radial-gradient(ellipse at 30% 35%, transparent 0 8px, rgba(255,255,255,.16) 9px 10px); box-shadow: inset -18px -10px 30px rgba(3,26,41,.3), 0 16px 28px rgba(3,20,31,.22); }
.mini-globe::before { content: ""; position: absolute; inset: 42% -24%; height: 1px; background: #8be1e9; transform: rotate(-17deg); box-shadow: 0 0 9px #5ed0dc; }
.mini-globe span { position: absolute; right: -21px; top: 14px; width: 36px; height: 6px; background: white; border-radius: 50% 90% 45% 50%; transform: rotate(-16deg); }
.steps { position: relative; margin-top: -60px; padding: 44px 22px 18px; border: 1px solid rgba(32,58,85,.1); border-radius: 26px; background: rgba(255,255,255,.83); box-shadow: 0 25px 60px rgba(18,48,68,.1); backdrop-filter: blur(16px); }
.step + .step { border-left: 1px solid var(--line); padding-left: 24px; }
.step svg { color: var(--teal); }

.side-note .scene-stage { min-height: 300px; margin: 26px 0; }
.form-panel { position: relative; border-color: rgba(32,58,85,.12); box-shadow: var(--deep-shadow); }
.form-panel::before { content: ""; position: absolute; top: -1px; left: 28px; width: 84px; height: 3px; border-radius: 5px; background: linear-gradient(90deg, var(--navy), var(--teal)); }
.field input:focus-visible, .field textarea:focus-visible, .field select:focus-visible { border-color: var(--teal); box-shadow: 0 0 0 4px rgba(34,125,145,.1); outline: 2px solid #188594; outline-offset: 3px; }
.faq-list { perspective: 1200px; }
.faq-item { position: relative; margin: 12px 0; padding: 0 24px; border: 1px solid rgba(32,58,85,.11); border-radius: 14px; background: white; box-shadow: 0 12px 34px rgba(20,49,67,.07); transform-origin: top; transition: transform .25s ease, box-shadow .25s ease; }
.faq-item::before { content: "VKC"; position: absolute; right: 66px; top: 21px; color: rgba(34,125,145,.28); font-size: .65rem; font-weight: 900; letter-spacing: .15em; }
.faq-item[open] { transform: translateZ(12px) translateX(4px); box-shadow: 0 20px 46px rgba(20,49,67,.12); }

.quote-band { position: relative; overflow: hidden; border: 1px solid rgba(100,207,221,.18); box-shadow: 0 34px 80px rgba(7,30,46,.27); }
.quote-band::after { content: ""; position: absolute; right: -90px; top: -150px; width: 390px; height: 390px; border: 1px solid rgba(88,200,216,.26); border-radius: 50%; box-shadow: 0 0 0 42px rgba(88,200,216,.04), 0 0 0 86px rgba(88,200,216,.025); }
.quote-band > * { position: relative; z-index: 2; }

.site-footer { position: relative; overflow: hidden; padding-top: 84px; background: #071d2d; }
.footer-grid { grid-template-columns: 1.55fr .7fr .7fr; }
.footer-brand .scene-stage { min-height: 210px; margin-top: 28px; border-radius: 20px; box-shadow: none; }
.footer-logo { color: white; }
.footer-logo .brand-logo { width: 66px; height: 66px; }

.admin-body { background: radial-gradient(circle at 85% 10%, rgba(60,177,196,.13), transparent 27%), #e9eef0; }
.admin-nav { margin: 12px; height: calc(100vh - 24px); border: 1px solid rgba(255,255,255,.08); border-radius: 20px; box-shadow: 18px 0 55px rgba(11,34,50,.14); background: linear-gradient(150deg, #173b56, #091f31 70%); }
.admin-brand .brand-logo { width: 48px; height: 48px; }
.admin-links a { border: 1px solid transparent; }
.admin-links a:hover, .admin-links a:focus-visible { border-color: rgba(106,201,214,.18); background: linear-gradient(90deg, rgba(85,190,206,.14), rgba(255,255,255,.03)); transform: translateX(3px); }
.admin-owner { position: absolute; bottom: 20px; max-width: 200px; color: #8da4af; font-size: 11px; overflow-wrap: anywhere; }
.stat, .data-card { border-color: rgba(32,58,85,.1); border-radius: 18px; box-shadow: 0 17px 42px rgba(20,49,67,.07); }
.stat { position: relative; overflow: hidden; }
.stat::after { content: ""; position: absolute; right: -30px; bottom: -45px; width: 100px; height: 100px; border: 1px solid rgba(34,125,145,.18); border-radius: 50%; }
.login-wrap { position: relative; grid-template-columns: minmax(460px, 1fr) minmax(380px, 520px); gap: 46px; padding: 54px max(28px, calc((100vw - 1280px)/2)); overflow: hidden; }
.login-scene { width: 100%; }
.login-scene .scene-stage { min-height: 620px; box-shadow: 0 38px 100px rgba(0,0,0,.28); }
.login-card { position: relative; z-index: 4; width: 100%; border: 1px solid rgba(255,255,255,.8); box-shadow: 0 35px 100px rgba(2,16,25,.3); }
.login-card h1 { font-size: clamp(2.3rem, 4vw, 3.5rem); line-height: 1; letter-spacing: -.035em; }
.login-logo { width: 88px; height: 88px; margin-bottom: 22px; padding: 5px; border: 1px solid var(--line); border-radius: 16px; box-shadow: 0 12px 30px rgba(19,49,67,.16); object-fit: cover; }

.scene-fallback { position: relative; min-height: inherit; overflow: hidden; background: radial-gradient(circle at 50% 34%, rgba(255,255,255,.95), rgba(201,220,222,.85)); }
.scene-fallback-international, .scene-fallback-footer, .scene-fallback-admin { background: radial-gradient(circle at 50% 34%, #1b5875, #081d2c); }
.fallback-route { position: absolute; left: 12%; right: 12%; bottom: 26%; height: 22%; border-top: 3px solid #4ab9ca; border-radius: 50%; transform: rotate(-6deg); }
.fallback-box { position: absolute; left: 53%; bottom: 28%; width: 72px; height: 62px; border-radius: 5px; background: #b7895f; box-shadow: inset 0 9px #dec49a, 0 20px 28px rgba(13,40,55,.18); transform: rotate(-5deg); }
.fallback-vehicle { position: absolute; left: 17%; bottom: 22%; width: 44%; height: 22%; border-radius: 14px 22px 8px 8px; background: linear-gradient(90deg, var(--teal) 0 25%, var(--navy) 25%); box-shadow: inset 0 -8px rgba(0,0,0,.1), 0 22px 35px rgba(10,34,49,.25); }
.fallback-vehicle::before { content: ""; position: absolute; left: 8%; top: 14%; width: 14%; height: 28%; border-radius: 4px; background: #a9d5dc; }
.fallback-vehicle::after { content: ""; position: absolute; left: 15%; bottom: -15px; width: 30px; height: 30px; border: 7px solid #18262d; border-radius: 50%; background: #91a4ab; box-shadow: 190px 0 0 -7px #91a4ab, 190px 0 0 0 #18262d; }

@media (max-width: 1050px) {
  .nav { gap: 13px; font-size: .82rem; }
  .nav .motion-toggle span { display: none; }
  .page-hero-grid { grid-template-columns: .88fr 1.12fr; gap: 28px; }
  .hero-scene { left: 40%; right: -120px; }
  .login-wrap { grid-template-columns: 1fr 440px; }
}

@media (max-width: 900px) {
  .site-header { top: 6px; margin-top: 6px; }
  .nav { inset: 88px 18px auto; padding: 22px; border: 1px solid rgba(32,58,85,.1); border-radius: 18px; background: rgba(247,246,241,.97); box-shadow: var(--deep-shadow); transform-origin: top; }
  .nav.open { display: flex; }
  .nav .motion-toggle { justify-content: center; margin: 4px 0 0; }
  .nav .motion-toggle span { display: inline; }
  .hero { min-height: 930px; }
  .hero-grid { min-height: 860px; }
  .hero-copy { width: 72%; padding-top: 95px; }
  .hero-scene { top: 430px; right: -100px; bottom: 16px; left: 8%; min-height: 470px; }
  .page-hero { padding-top: 132px; }
  .page-hero-grid { grid-template-columns: 1fr; }
  .page-hero-copy { max-width: 720px; }
  .page-hero .scene-stage { min-height: 370px; }
