import type { Metadata } from "next";
import { siteUrl } from "@/lib/config";
import "./globals.css";
import "@/styles/depth.css";
import { MotionProvider } from "@/components/motion/provider";
import { ImageFeedback } from "@/components/image-feedback";

export const metadata: Metadata = {
  metadataBase: siteUrl ? new URL(siteUrl) : undefined,
  title: { default: "VK AND COMPANY | Courier Services", template: "%s | VK AND COMPANY" },
  description: "Domestic and international courier enquiries and quotations from VK AND COMPANY.",
};

export default function RootLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return <html lang="en"><body><MotionProvider><ImageFeedback/>{children}</MotionProvider></body></html>;
}

app/robots.ts:
import type { MetadataRoute } from "next";
import { siteUrl } from "@/lib/config";
export const dynamic = "force-static";
export default function robots(): MetadataRoute.Robots {
  return { rules: { userAgent: "*", ...(siteUrl ? { allow: "/" } : { disallow: "/" }) }, ...(siteUrl ? { sitemap: `${siteUrl}/sitemap.xml` } : {}) };
}

app/sitemap.ts:
import type { MetadataRoute } from "next";
import { siteUrl } from "@/lib/config";
export const dynamic = "force-static";
export default function sitemap(): MetadataRoute.Sitemap {
  if (!siteUrl) return [];
  return ["", "/services/domestic", "/services/international", "/get-a-quote", "/about", "/contact", "/track", "/faq", "/privacy", "/terms"].map(path => ({ url: `${siteUrl}${path}`, changeFrequency: path === "" ? "weekly" : "monthly", priority: path === "" ? 1 : 0.7 }));
}

