  "sources": {
    "app/(site)/about/page.tsx": "import type { Metadata } from \"next\";\nimport { Photograph } from \"@/components/photograph\";\nimport { CalendarCheck, FileText, PackageCheck, Route } from \"lucide-react\";\nimport { PageHero } from \"@/components/page-hero\";\nimport { QuoteBand } from \"@/components/quote-band\";\n\nexport const metadata: Metadata = {\n  title: \"About\",\n  description: \"Learn about VK AND COMPANY's enquiry-led domestic and international courier service.\",\n};\n\nconst services = [\n  { label: \"Shipment Details\", Icon: FileText },\n  { label: \"Route Review\", Icon: Route },\n  { label: \"Booking Support\", Icon: CalendarCheck },\n  { label: \"Shipment Updates\", Icon: PackageCheck },\n];\n\nexport default function AboutPage() {\n  return <>\n    <PageHero variant=\"about\" eyebrow=\"About VK AND COMPANY\" title=\"Courier arrangements built around each shipment.\" description=\"VK AND COMPANY provides domestic and international courier services through a clear enquiry, quotation and booking process.\"/>\n    <section className=\"section section-white about-what-we-do\">\n      <div className=\"shell about-what-grid\">\n        <div className=\"about-what-visual\">\n          <p className=\"eyebrow\">What we do</p>\n          <p className=\"about-what-tagline\">Connecting People &amp; Possibilities</p>\n          <div className=\"about-network-image\" data-image-feedback=\"photo\" data-photo-frame=\"\">\n            <Photograph name=\"dispatch\" sizes=\"(max-width: 900px) 100vw, 40vw\" alt=\"Illustrative courier team loading parcels for dispatch\"/>\n          </div>\n          <ul className=\"about-service-strip\" aria-label=\"Service process\">\n            {services.map(({ label, Icon }) => <li key={label}><Icon aria-hidden=\"true\"/><span>{label}</span></li>)}\n          </ul>\n        </div>\n\n        <div className=\"about-what-content\">\n          <section className=\"about-what-row\">\n            <div className=\"about-thumbnail\" data-image-feedback=\"photo\" data-photo-frame=\"\">\n              <Photograph name=\"details\" sizes=\"277px\" alt=\"Illustrative parcel being weighed and measured\"/>\n            </div>\n            <div className=\"prose\"><h2>A straightforward customer journey.</h2><p>Customers share their shipment details, receive a reviewed offer, arrange a booking and follow genuine shipment updates. Support requests remain connected to the operational team when questions arise.</p></div>\n          </section>\n          <section className=\"about-what-row\">\n            <div className=\"about-thumbnail\" data-image-feedback=\"photo\" data-photo-frame=\"\">\n              <Photograph name=\"review\" sizes=\"277px\" alt=\"Illustrative courier and customer reviewing shipment details\"/>\n            </div>\n            <div className=\"prose\"><h2>Careful about what is confirmed.</h2><p>We do not publish invented coverage, courier partners, guarantees or rate cards. Service facts are confirmed for the route and shipment details provided.</p></div>\n          </section>\n          <section className=\"about-what-row\">\n            <div className=\"about-thumbnail\" data-image-feedback=\"photo\" data-photo-frame=\"\">\n              <Photograph name=\"support\" sizes=\"277px\" alt=\"Illustrative customer support representative wearing a headset\"/>\n            </div>\n            <div className=\"prose\"><h2>Prepared to connect.</h2><p>Shipment updates are maintained manually by the team. The application has a defined boundary for approved courier integrations when partners and credentials are supplied.</p></div>\n          </section>\n          <p className=\"about-purpose\"><span aria-hidden=\"true\"/>Delivered with Purpose</p>\n        </div>\n      </div>\n    </section>\n    <QuoteBand/>\n  </>;\n}\n",
    "app/(site)/contact/contact.module.css": ".page {\n  padding: 128px 0 46px;\n  background-color: #f6f5f1;\n  background-image: radial-gradient(ellipse at 80% 15%, #dcebefa8, transparent 47%), linear-gradient(#d9e0df33 1px, transparent 1px), linear-gradient(90deg, #d9e0df33 1px, transparent 1px);\n  background-size: auto, 42px 42px, 42px 42px;\n}\n.layout { width: min(1340px, calc(100% - 48px)); margin: auto; display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); }\n.introduction { position: relative; min-width: 0; padding-right: 28px; }\n.introduction h1 { font: 400 clamp(3.5rem, 5.4vw, 5.1rem)/.99 Georgia, serif; letter-spacing: -.045em; color: #0d304b; margin: 0 0 20px 28px; }\n.description { max-width: 460px; margin: 0 0 12px 28px; color: #596c7e; font-size: 17px; line-height: 1.65; }\n.tagline { position: absolute; top: 86px; right: 28px; margin: 0; width: fit-content; color: #123d5c; font: italic 24px/1.15 \"Bradley Hand\", \"Segoe Print\", cursive; transform: rotate(-8deg); }\n.tagline svg { display: block; width: 64px; height: 44px; margin-left: 40px; stroke-width: 1.3; }\n.artwork { margin-inline: -20px 0; }\n.channels { position: relative; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; padding: 25px 18px; list-style: none; margin: -1px 0 0; border-radius: 24px; background: #faf9f5; box-shadow: 0 14px 30px #1a344b0b; }\n.channels li { display: flex; align-items: center; gap: 9px; font-size: 13px; color: #102e49; line-height: 1.4; }\n.channels svg { width: 30px; height: 34px; stroke-width: 1.5; flex-shrink: 0; color: #08778e; }\n.closing { color: #123d5c; text-align: center; width: fit-content; margin: 25px auto 0; padding-bottom: 10px; border-bottom: 2px solid #12768c; font: italic 25px/1.25 \"Bradley Hand\", \"Segoe Print\", cursive; transform: rotate(-6deg); }\n.right { border-left: 1px solid #c7d9df; padding: 20px 0 0 clamp(26px, 4vw, 68px); min-width: 0; }\n.details { min-width: 0; padding: 0 28px 32px; }\n.details h2 { font: 400 clamp(2.1rem, 3vw, 2.8rem)/1.3 Georgia, serif; color: #0d304b; margin: 15px 0 24px; }\n.details p { margin: 10px 0; }\n.link { max-width: 100%; align-items: flex-start; color: var(--navy); font-size: 16px; }\n.icon { flex-shrink: 0; margin-top: .2em; color: var(--teal); }\n.value { min-width: 0; overflow-wrap: anywhere; }\n.formArea { position: relative; }\n.formArea::before { content: \"\"; position: absolute; z-index: 1; top: 0; left: 28px; width: 80px; height: 3px; background: linear-gradient(90deg, #103650, #078da0); }\n.formArea :global(.form-panel) { border-radius: 26px; padding: 34px 28px 28px; background: #ffffffee; box-shadow: 0 22px 40px #203a551a; }\n.formArea :global(.form-grid) { gap: 20px; }\n.formArea :global(.field) { gap: 7px; }\n.formArea :global(.field input), .formArea :global(.field select), .formArea :global(.field textarea) { background: transparent; border: 1px solid #b5c8d7; border-radius: 10px; }\n.formArea :global(.field textarea) { min-height: 112px; }\n.formArea :global(.button) { display: flex; margin: 18px 0 0 auto; min-width: 200px; justify-content: center; }\n.responseTime { text-align: center; font-size: 12px; color: #596c7e; margin: 18px 0 0; }\n@media (max-width: 1050px) {\n  .tagline { position: static; margin: 0 24px -8px auto; }\n  .channels { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .details { padding-inline: 8px; }\n  .introduction h1, .description { margin-left: 0; }\n}\n@media (max-width: 800px) {\n  .page { padding-top: 116px; }\n  .layout { width: calc(100% - 32px); grid-template-columns: minmax(0, 1fr); gap: 44px; }\n  .introduction { padding-right: 0; }\n  .artwork { margin-inline: 0; }\n  .right { padding: 32px 0 0; border-left: 0; border-top: 1px solid #c7d9df; }\n  .channels { gap: 20px; }\n  .formArea :global(.form-panel) { padding: 28px 20px 24px; }\n  .details { padding-bottom: 28px; }\n  .description { max-width: 480px; }\n}\n",
    "app/(site)/contact/page.tsx": "import type { Metadata } from \"next\";\nimport { Mail, Phone, Headphones, FileText, Package, Users, MoveDownLeft } from \"lucide-react\";\nimport { Photograph } from \"@/components/photograph\";\nimport { SupportForm } from \"@/components/forms/support-form\";\nimport { getPublicBusinessSettings } from \"@/lib/business-settings\";\nimport styles from \"./contact.module.css\";\n\nexport const metadata: Metadata = {\n  title: \"Contact\",\n  description: \"Send a courier or delivery support enquiry to VK AND COMPANY.\",\n};\n\nexport default async function ContactPage() {\n  const settings = await getPublicBusinessSettings();\n  const whatsappDigits = settings.whatsapp?.replace(/\\D/g, \"\");\n  return <section className={styles.page}>\n      <div className={styles.layout}>\n        <div className={styles.introduction}>\n          <h1>How can we <br/>help?</h1>\n          <p className={styles.description}>Send a general question or ask about a shipment. Your message will be saved for the team to review.</p>\n          <p className={styles.tagline}>Here to Keep <br/>You Moving<MoveDownLeft aria-hidden=\"true\"/></p>\n          <div className={styles.artwork}><div className=\"service-photo\" data-image-feedback=\"photo\" data-photo-frame=\"\"><Photograph name=\"support\" alt=\"Illustrative Indian courier customer support representative\" sizes=\"(max-width: 900px) calc(100vw - 32px), 50vw\" eager/></div></div>\n          <ul className={styles.channels} aria-label=\"Enquiry topics\">\n            <li><Headphones aria-hidden=\"true\"/><span>General <br/>Enquiries</span></li>\n            <li><FileText aria-hidden=\"true\"/><span>Quote <br/>Requests</span></li>\n            <li><Package aria-hidden=\"true\"/><span>Shipment <br/>Support</span></li>\n            <li><Users aria-hidden=\"true\"/><span>Partnerships <br/>&amp; Other</span></li>\n          </ul>\n          <p className={styles.closing}>From <br/>Your Place to the World</p>\n        </div>\n        <div className={styles.right}>\n        <aside className={styles.details} aria-label=\"Company contact details\">\n          <p className=\"eyebrow\">Contact channels</p>\n          <h2>Contact VK AND COMPANY.</h2>\n          <p><a className={`text-link ${styles.link}`} href=\"tel:+919317724056\"><Phone size={19} className={styles.icon} aria-hidden=\"true\"/><span className={styles.value}>+91 93177 24056</span></a></p>\n          <p><a className={`text-link ${styles.link}`} href=\"mailto:vkandcompanymohali@gmail.com\"><Mail size={19} className={styles.icon} aria-hidden=\"true\"/><span className={styles.value}>vkandcompanymohali@gmail.com</span></a></p>\n          {whatsappDigits && <p><a className=\"text-link\" href={`https://wa.me/${whatsappDigits}`} rel=\"noopener noreferrer\">WhatsApp</a></p>}\n          {settings.address && <p>{settings.mapUrl ? <a className=\"text-link\" href={settings.mapUrl} rel=\"noopener noreferrer\">{settings.address}</a> : settings.address}</p>}\n          {settings.operatingHours && <p>{settings.operatingHours}</p>}\n        </aside>\n        <div className={styles.formArea}><SupportForm/></div>\n        <p className={styles.responseTime}>We usually respond within one business day.</p>\n        </div>\n      </div>\n    </section>;\n}\n",
    "app/(site)/faq/page.tsx": "import type { Metadata } from \"next\";import { PageHero } from \"@/components/page-hero\";import { FaqList } from \"@/components/faq-list\";import { QuoteBand } from \"@/components/quote-band\";\nexport const metadata:Metadata={title:\"Frequently asked questions\",description:\"Answers about courier enquiries, quotations and booking with VK AND COMPANY.\"};\nexport default function FaqPage(){return <><PageHero variant=\"faq\" eyebrow=\"Frequently asked questions\" title=\"Answers before you send.\" description=\"Useful guidance about our enquiry-led courier workflow.\"/><section className=\"section section-white\"><div className=\"shell\"><FaqList/></div></section><QuoteBand/></>}\n",
    "app/(site)/get-a-quote/page.tsx": "import type { Metadata } from \"next\";\nimport { PageHero } from \"@/components/page-hero\";\nimport { EnquiryForm } from \"@/components/forms/enquiry-form\";\nexport const metadata:Metadata={title:\"Request a quote\",description:\"Share your route and parcel details with VK AND COMPANY for a reviewed courier quotation.\"};\nexport default function QuotePage(){return <><PageHero variant=\"quote\" eyebrow=\"Quotation request\" title=\"Tell us about your shipment.\" description=\"Share the route and parcel details below. Our team will review the information before confirming service and charges.\"/><section className=\"section\"><div className=\"shell form-shell\"><aside className=\"side-note\"><p className=\"eyebrow\">Before you begin</p><h2>Details make the difference.</h2><p>Approximate information is fine where requested. Accurate contents, weight and route details help the team assess the shipment.</p><p>Pickup requests are not currently enabled.</p></aside><EnquiryForm/></div></section></>}\n",
    "app/(site)/layout.tsx": "import { existsSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { SiteHeader } from \"@/components/site-header\";\nimport { SiteFooter } from \"@/components/site-footer\";\nimport { RouteTransition } from \"@/components/route-transition\";\n\nexport default function SiteLayout({ children }: { children: React.ReactNode }) {\n  const hasLogo = existsSync(join(process.cwd(), \"public/brand/vk-and-company-logo-transparent.png\"));\n  return <><RouteTransition/><SiteHeader hasLogo={hasLogo}/><main>{children}</main><SiteFooter/></>;\n}\n",
    "app/(site)/page.tsx": "import { Photograph } from \"@/components/photograph\";\nimport Link from \"next/link\";\nimport { ArrowRight, Box, CircleCheck, FileText, MapPin } from \"lucide-react\";\nimport { FaqList } from \"@/components/faq-list\";\nimport { ProcessPhoto } from \"@/components/process-photo\";\n\nexport default function HomePage() {\n  return <>\n    <section className=\"cinematic-hero\" data-image-feedback=\"background\">\n      <Photograph\n        className=\"cinematic-hero-background\"\n        name=\"selected-home-hero\"\n        sizes=\"100vw\"\n        alt=\"Illustrative navy and teal courier truck at an Indian delivery forecourt\"\n        eager\n      />\n      <div className=\"shell cinematic-hero-content\">\n        <div className=\"cinematic-copy\" data-image-feedback-foreground>\n          <p className=\"eyebrow\">Domestic & international courier services</p>\n          <h1>Across cities.<br/><em>Across borders.</em></h1>\n          <p className=\"cinematic-support\">We keep your parcels moving.</p>\n          <p className=\"lede\">Domestic and international courier services from VK AND COMPANY. Share your shipment details and let our team help arrange the next step.</p>\n          <div className=\"hero-actions\"><Link className=\"button button-teal\" href=\"/get-a-quote\">Get a quote <ArrowRight size={18}/></Link></div>\n        </div>\n      </div>\n    </section>\n\n    <section className=\"editorial-section section-white\" id=\"domestic-services\">\n      <div className=\"shell editorial-grid\">\n        <div className=\"editorial-image\" data-image-feedback=\"photo\" data-photo-frame=\"\"><Photograph name=\"selected-domestic\" sizes=\"(max-width: 800px) 100vw, 58vw\" alt=\"Illustrative delivery truck travelling on an intercity road\"/><span>Illustrative route imagery</span></div>\n        <div className=\"editorial-copy\"><p className=\"section-index\">01 / Domestic</p><p className=\"eyebrow\">Courier services between cities</p><h2>Planned around your actual route.</h2><p>Share the origin, destination and parcel details. We review availability and prepare an offer for the specific shipment—without making blanket coverage or timing claims.</p><Link href=\"/services/domestic\" className=\"text-link\">Explore domestic services <ArrowRight size={16}/></Link></div>\n      </div>\n    </section>\n\n    <section className=\"editorial-section international-feature\">\n      <div className=\"shell editorial-grid editorial-grid-reverse\">\n        {/* The complete aircraft and its frame move together. */}\n        <div className=\"editorial-image international-aircraft\" data-image-feedback=\"photo\" data-photo-frame=\"\"><Photograph name=\"existing-aircraft\" sizes=\"(max-width: 900px) 100vw, 41vw\" alt=\"Antonov An-124 cargo aircraft above Lviv airport, with nose, tail and both wingtips in frame\"/><span>Illustrative international logistics</span></div>\n        <div className=\"editorial-copy\"><p className=\"section-index\">02 / International</p><p className=\"eyebrow\">Across borders, details first</p><h2>Clear before it leaves the ground.</h2><p>Acceptance, documentation, availability and charges depend on the route and parcel. Our team confirms what applies before anything is arranged.</p><Link href=\"/services/international\" className=\"text-link\">Explore international services <ArrowRight size={16}/></Link></div>\n      </div>\n    </section>\n\n    <section className=\"process-flow\">\n      <div className=\"shell\"><div className=\"section-head\"><div><p className=\"eyebrow\">How shipping works</p><h2>Four steps.<br/>One clear process.</h2></div><p>Every status follows a real operational action. An enquiry is never presented as a confirmed booking or dispatch.</p></div>\n        <ol className=\"process-list\">\n          <li><ProcessPhoto action=\"details\" sizes=\"(max-width: 640px) 90vw, (max-width: 900px) 43vw, 21vw\"/><span>01</span><FileText/><h3>Share shipment details</h3><p>Tell us the route, contents, package count and approximate weight.</p></li>\n          <li><ProcessPhoto action=\"review\" sizes=\"(max-width: 640px) 90vw, (max-width: 900px) 43vw, 21vw\"/><span>02</span><CircleCheck/><h3>Receive a reviewed quote</h3><p>Service details, inclusions and exclusions are confirmed for the enquiry.</p></li>\n          <li><ProcessPhoto action=\"dispatch\" sizes=\"(max-width: 640px) 90vw, (max-width: 900px) 43vw, 21vw\"/><span>03</span><Box/><h3>Arrange dispatch</h3><p>An accepted quote becomes a booking ready for coordination.</p></li>\n          <li><ProcessPhoto action=\"scan\" sizes=\"(max-width: 640px) 90vw, (max-width: 900px) 43vw, 21vw\"/><span>04</span><MapPin/><h3>Follow verified updates</h3><p>Contact the team for customer-safe shipment updates.</p></li>\n        </ol>\n      </div>\n    </section>\n\n    <section className=\"action-entry section-white\">\n      <div className=\"shell action-entry-grid\">\n        <article><span className=\"action-number\">01</span><Box/><p className=\"eyebrow\">Start with the shipment</p><h2>Request a considered quote.</h2><p>Share the details once. Our team reviews each request before confirming service or charges.</p><Link href=\"/get-a-quote\" className=\"button\">Get a quote <ArrowRight size={17}/></Link></article>\n      </div>\n    </section>\n\n    <section className=\"editorial-section company-feature\">\n      <div className=\"shell editorial-grid\">\n        <div className=\"editorial-image\" data-image-feedback=\"photo\" data-photo-frame=\"\"><Photograph name=\"workspace\" sizes=\"(max-width: 800px) 100vw, 58vw\" alt=\"Illustrative modern parcel dispatch workspace\"/><span>Illustrative operations environment</span></div>\n        <div className=\"editorial-copy\"><p className=\"section-index\">03 / Company</p><p className=\"eyebrow\">About VK AND COMPANY</p><h2>Built around each shipment.</h2><p>Our customer journey is straightforward: share the details, receive a reviewed offer, arrange a booking and follow genuine updates.</p><Link href=\"/about\" className=\"text-link\">More about our process <ArrowRight size={16}/></Link></div>\n      </div>\n    </section>\n\n    <section className=\"homepage-faq section-white\"><div className=\"shell\"><div className=\"section-head\"><div><p className=\"eyebrow\">Common questions</p><h2>Useful answers,<br/>before you send.</h2></div><Link href=\"/faq\" className=\"text-link\">View all FAQs <ArrowRight size={16}/></Link></div><FaqList limit={4}/></div></section>\n\n    <section className=\"contact-finale\"><div className=\"shell contact-finale-inner\"><div><p className=\"eyebrow\">Contact & support</p><h2>Need help with the next step?</h2><p>Send a secure general or shipment-related enquiry for the team to review.</p></div><Link href=\"/contact\" className=\"button button-teal\">Contact the team <ArrowRight size={17}/></Link></div></section>\n  </>;\n}\n",
    "app/(site)/privacy/page.tsx": "import type { Metadata } from \"next\";import { PageHero } from \"@/components/page-hero\";\nexport const metadata:Metadata={title:\"Privacy information\",robots:{index:false,follow:false}};\nexport default function PrivacyPage(){return <><PageHero eyebrow=\"Owner review required\" title=\"Privacy content is not yet approved.\" description=\"This page is reserved for VK AND COMPANY's reviewed privacy information.\"/><section className=\"section\"><div className=\"shell prose\" style={{maxWidth:760}}><div className=\"notice\"><strong>Launch requirement:</strong> The business owner and an appropriate legal adviser must review and approve the final privacy notice before this page is published or indexed.</div><p>The application collects contact, route and shipment information when a person intentionally submits a quotation or support request. Final disclosures—including purposes, retention, rights, processors and contact details—depend on confirmed business practices and must not be invented.</p></div></section></>}\n",
    "app/(site)/services/domestic/page.tsx": "import type { Metadata } from \"next\";\nimport { PageHero } from \"@/components/page-hero\";\nimport { QuoteBand } from \"@/components/quote-band\";\nimport { ServiceProcess } from \"@/components/service-process\";\n\nexport const metadata: Metadata = { title: \"Domestic courier services\", description: \"Request a reviewed domestic courier quote from VK AND COMPANY.\" };\n\nexport default function DomesticPage() {\n  return <>\n    <PageHero variant=\"domestic\" eyebrow=\"Domestic courier enquiries\" title=\"A considered route from one city to the next.\" description=\"Tell us where your parcel is going and what it contains. Availability, service options, timing and charges are confirmed for the specific shipment.\"/>\n    <ServiceProcess kind=\"domestic\"/>\n    <QuoteBand/>\n  </>;\n}\n",
    "app/(site)/services/international/page.tsx": "import type { Metadata } from \"next\";\nimport { PageHero } from \"@/components/page-hero\";\nimport { ServiceProcess } from \"@/components/service-process\";\nimport { QuoteBand } from \"@/components/quote-band\";\n\nexport const metadata: Metadata = {\n  title: \"International courier services\",\n  description: \"Discuss international courier acceptance, documentation and charges with VK AND COMPANY.\",\n};\n\nexport default function InternationalPage() {\n  return <>\n    <PageHero\n      variant=\"international\"\n      eyebrow=\"International courier enquiries\"\n      title=\"Across borders, with the details checked first.\"\n      description=\"International shipment requirements vary by contents, origin and destination. We review each enquiry before confirming what can be arranged.\"\n    />\n    <ServiceProcess kind=\"international\"/>\n    <QuoteBand/>\n  </>;\n}\n",
    "app/(site)/terms/page.tsx": "import type { Metadata } from \"next\";import { PageHero } from \"@/components/page-hero\";\nexport const metadata:Metadata={title:\"Service terms\",robots:{index:false,follow:false}};\nexport default function TermsPage(){return <><PageHero eyebrow=\"Owner review required\" title=\"Service terms are not yet approved.\" description=\"This page is reserved for VK AND COMPANY's reviewed customer terms.\"/><section className=\"section\"><div className=\"shell prose\" style={{maxWidth:760}}><div className=\"notice\"><strong>Launch requirement:</strong> Approved terms must address the actual courier process, responsibilities, restrictions, charges, claims and applicable law before publication.</div><p>No unreviewed boilerplate is presented as company policy. Quotes include shipment-specific service details, estimates, inclusions, exclusions, currency and validity.</p></div></section></>}\n",
    "app/(site)/track/page.tsx": "import type { Metadata } from \"next\";\nimport Link from \"next/link\";\nimport { PageHero } from \"@/components/page-hero\";\nimport { Mail, Phone } from \"lucide-react\";\n\nexport const metadata: Metadata = { title: \"Shipment update enquiry\" };\n\nexport default function ShipmentUpdatePage() {\n  return <>\n    <PageHero eyebrow=\"Shipment support\" title=\"Shipment update enquiry\" description=\"Contact the company for an update on your shipment. Please include your shipment reference so the team can help.\"/>\n    <section className=\"section\"><div className=\"shell\"><div className=\"form-panel\">\n      <h2>Ask about your shipment.</h2>\n      <p className=\"lede\">Online shipment lookup is unavailable. Contact VK AND COMPANY by phone or email, or use the Contact form. Include your shipment reference in your message.</p>\n      <p><a className=\"text-link\" href=\"tel:+919317724056\"><Phone size={19} aria-hidden=\"true\"/> +91 93177 24056</a></p>\n      <p><a className=\"text-link\" style={{ overflowWrap: \"anywhere\" }} href=\"mailto:vkandcompanymohali@gmail.com\"><Mail size={19} aria-hidden=\"true\"/> vkandcompanymohali@gmail.com</a></p>\n      <Link className=\"button\" href=\"/contact\">Contact the team</Link>\n    </div></div></section>\n  </>;\n}\n",
    "app/globals.css": "@import \"tailwindcss\";\n\n:root {\n  --navy: #203a55;\n  --navy-deep: #132c43;\n  --teal: #227d91;\n  --teal-dark: #17677a;\n  --ink: #172b3a;\n  --muted: #5f707c;\n  --cream: #f6f5f1;\n  --paper: #ffffff;\n  --line: #dbe4e8;\n  --mist: #e7ecef;\n  --success: #166b55;\n  --danger: #a63c37;\n  --radius: 22px;\n  --shadow: 0 22px 60px rgba(25, 51, 70, 0.12);\n}\n\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody { margin: 0; background: var(--cream); color: var(--ink); font-family: Arial, Helvetica, sans-serif; line-height: 1.6; }\na { color: inherit; text-decoration: none; }\nbutton, input, textarea, select { font: inherit; }\nbutton, a { -webkit-tap-highlight-color: transparent; }\n:focus-visible { outline: 3px solid #4fb4c8; outline-offset: 3px; }\n::selection { color: white; background: var(--teal); }\n\n.shell { width: min(1180px, calc(100% - 40px)); margin-inline: auto; }\n.site-header { position: sticky; top: 0; z-index: 50; background: color-mix(in srgb, var(--cream) 92%, transparent); border-bottom: 1px solid rgba(32,58,85,.09); backdrop-filter: blur(16px); }\n.header-inner { min-height: 78px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }\n.brand { display: inline-flex; align-items: center; gap: 12px; font-size: .84rem; font-weight: 800; letter-spacing: .11em; color: var(--navy); }\n.brand .brand-logo { width: 52px; height: 52px; border-radius: 8px; }\n/* Preserve the supplied 500px PNG. Only empty alpha padding falls outside the\n   frame: artwork bounds are (63,108)–(437,433); at 125% every painted pixel fits. */\n.brand-logo { position: relative; display: inline-block; flex-shrink: 0; overflow: hidden; vertical-align: middle; background: #e9e5dd; }\n.brand-logo > img { position: absolute; width: 125%; height: 125%; max-width: none; left: -12.5%; top: -17.625%; object-fit: contain; border: 0; border-radius: 0; padding: 0; background: transparent; }\n.nav { display: flex; align-items: center; gap: 26px; font-size: .92rem; font-weight: 700; color: #405563; }\n.nav a:hover { color: var(--teal-dark); }\n.nav .button { color: white; }\n.menu-button { display: none; border: 0; background: transparent; color: var(--navy); padding: 8px; }\n.button { display: inline-flex; min-height: 48px; align-items: center; justify-content: center; gap: 9px; padding: 0 20px; border-radius: 999px; border: 1px solid transparent; background: var(--navy); color: white; font-weight: 800; cursor: pointer; transition: transform .2s ease, background .2s ease; }\n.button:hover { transform: translateY(-2px); background: var(--navy-deep); }\n.button-secondary { background: transparent; border-color: #9eb2bc; color: var(--navy); }\n.button-secondary:hover { background: white; }\n.button-small { min-height: 40px; padding-inline: 16px; font-size: .88rem; }\n.button:disabled { opacity: .55; cursor: not-allowed; transform: none; }\n\n.eyebrow { margin: 0 0 14px; color: var(--teal-dark); font-size: .75rem; font-weight: 900; letter-spacing: .17em; text-transform: uppercase; }\n.display { margin: 0; color: var(--navy-deep); font-family: Georgia, 'Times New Roman', serif; font-size: clamp(3.2rem, 7vw, 6.7rem); font-weight: 500; letter-spacing: -.055em; line-height: .92; }\n.display em { color: var(--teal); font-style: normal; }\n.lede { max-width: 620px; margin: 24px 0 0; color: var(--muted); font-size: clamp(1rem, 2vw, 1.18rem); }\n.hero { position: relative; min-height: 760px; overflow: clip; border-bottom: 1px solid var(--line); background: radial-gradient(circle at 78% 35%, #e1eff0 0, transparent 30%), var(--cream); }\n.hero-grid { position: relative; z-index: 2; display: grid; grid-template-columns: .9fr 1.1fr; min-height: 690px; align-items: center; }\n.hero-copy { position: relative; z-index: 3; padding: 80px 0 120px; }\n.hero-copy .display { font-size: clamp(3.4rem, 6.3vw, 6.1rem); }\n.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 32px; }\n.hero-note { display: flex; align-items: center; gap: 10px; margin-top: 25px; color: #667985; font-size: .82rem; }\n.hero-note::before { content: ''; width: 24px; height: 1px; background: var(--teal); }\n.scene-wrap { position: absolute; inset: 72px max(0px, calc((100vw - 1240px) / 2)) 0 43%; z-index: 4; min-height: 620px; pointer-events: none; }\n.scene-controls { position: absolute; right: 22px; top: 20px; z-index: 5; pointer-events: auto; }\n.motion-toggle { display: inline-flex; gap: 8px; align-items: center; border: 1px solid rgba(32,58,85,.15); border-radius: 999px; background: rgba(255,255,255,.82); padding: 8px 12px; color: var(--navy); font-size: .75rem; font-weight: 800; box-shadow: 0 8px 28px rgba(22,50,70,.08); }\n.scene-fallback { height: 100%; min-height: 560px; display: grid; place-items: center; }\n.fallback-art { position: relative; width: min(620px, 90%); aspect-ratio: 1.35; border-radius: 45% 45% 14% 14%; background: linear-gradient(#e0eff1 0 58%, #cad5da 58% 63%, #70818b 63% 74%, #dfe6e7 74%); overflow: hidden; }\n.fallback-truck { position: absolute; left: 18%; bottom: 24%; width: 57%; height: 26%; border-radius: 10px 18px 7px 7px; background: var(--navy); box-shadow: inset -28px 0 var(--teal); }\n.fallback-truck::before { content:''; position:absolute; left:-22%; bottom:0; width:28%; height:76%; background:var(--teal); border-radius:24px 4px 5px 5px; }\n.fallback-truck::after { content:''; position:absolute; left:-13%; bottom:-18px; width:34px; height:34px; border:8px solid #26333a; border-radius:50%; background:#8ea0a9; box-shadow:205px 0 0 -8px #8ea0a9, 205px 0 0 0 #26333a; }\n\n.section { padding: 112px 0; }\n.section-compact { padding: 76px 0; }\n.section-white { background: white; }\n.section-navy { background: var(--navy-deep); color: white; }\n.section-head { display: flex; align-items: end; justify-content: space-between; gap: 30px; margin-bottom: 46px; }\n.section-head h2, .page-hero h1 { margin: 0; color: var(--navy-deep); font-family: Georg