ticle > svg { margin: 70px 0 28px; color: var(--teal); }\n.action-entry article:first-child > svg { color: #70c1cd; }\n.action-number { position: absolute; right: 30px; top: 25px; color: rgba(72,131,146,.5); font-family: Georgia,serif; font-size: 4rem; }\n.action-entry article .button { margin-top: 26px; }\n.company-feature { background: #e4e9e8; }\n.homepage-faq { padding: clamp(90px,10vw,145px) 0; }\n.contact-finale { padding: 80px 0; color: white; background: #0b2639; }\n.contact-finale-inner { display: flex; align-items: center; justify-content: space-between; gap: 46px; }\n.contact-finale h2 { color: white; }\n.contact-finale p { max-width: 590px; color: #b9cbd2; }\n\n.page-hero { min-height: 570px; }\n.page-hero-grid { grid-template-columns: minmax(0,.9fr) minmax(420px,1.1fr); }\n.page-hero-image { position: relative; overflow: hidden; border-radius: 5px; box-shadow: 0 24px 60px rgba(12,39,55,.18); }\n.page-hero-image img { object-fit: cover; }\n.page-hero-image span { position: absolute; right: 12px; bottom: 10px; padding: 5px 8px; background: rgba(8,30,45,.72); color: white; font-size: .57rem; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }\n.page-hero-marker { position: relative; min-height: 330px; border-left: 1px solid rgba(34,125,145,.24); }\n.page-hero-marker::before { content: \"\"; position: absolute; inset: 20% 10%; border: 1px solid rgba(34,125,145,.26); border-radius: 50%; transform: rotate(-16deg); }\n.page-hero-marker span { position: absolute; left: 43%; top: 40%; display: grid; width: 84px; height: 84px; place-items: center; border: 1px solid rgba(34,125,145,.32); color: var(--navy); font-weight: 900; letter-spacing: .12em; transform: rotate(-7deg); }\n.page-hero-marker i { position: absolute; left: 28%; right: 20%; top: 56%; height: 2px; background: linear-gradient(90deg,transparent,var(--teal),transparent); transform: rotate(-16deg); }\n.page-hero-international .page-hero-image { border: 1px solid rgba(112,192,204,.24); box-shadow: none; }\n.footer-brand .scene-stage { display: none; }\n.login-wrap { grid-template-columns: minmax(0,1.15fr) minmax(390px,.85fr); }\n.login-backdrop { position: absolute; inset: 0 36% 0 0; }\n.login-backdrop::after { content: \"\"; position: absolute; inset: 0; background: linear-gradient(90deg,rgba(7,29,45,.2),rgba(7,29,45,.76)); }\n.login-backdrop img { object-fit: cover; }\n\n@media (max-width: 1050px) {\n  .cinematic-copy h1 { font-size: clamp(3.5rem,6vw,5rem); }\n}\n\n@media (max-width: 900px) {\n  .home-header .nav.open { color: var(--navy); background: rgba(247,246,241,.98); }\n  .home-header .nav.open a:not(.button) { color: var(--navy); }\n  .cinematic-hero-background { object-position: 62% center; }\n  .cinematic-hero::before { background: linear-gradient(180deg, rgba(6,24,37,.9) 0%, rgba(9,36,53,.84) 40%, rgba(9,36,53,.64) 70%, rgba(8,31,46,.3) 100%); }\n  .cinematic-copy { max-width: 580px; }\n  .cinematic-copy h1 { font-size: clamp(3.25rem,8vw,5rem); }\n  .editorial-grid, .editorial-grid-reverse { grid-template-columns: 1fr; }\n  .editorial-grid-reverse .editorial-image, .editorial-grid-reverse .editorial-copy { order: initial; }\n  .editorial-copy { max-width: 700px; }\n  .process-list { grid-template-columns: repeat(2,1fr); }\n  .process-list li:nth-child(3) { border-left-color: transparent; border-top: 1px solid #d0d9db; }\n  .process-list li:nth-child(4) { border-top: 1px solid #d0d9db; }\n  .page-hero-grid { grid-template-columns: 1fr; }\n  .page-hero-marker { min-height: 210px; border-left: 0; }\n  .login-wrap { grid-template-columns: 1fr; }\n  .login-backdrop { inset: 0; opacity: .5; }\n}\n\n@media (max-width: 640px) {\n  .cinematic-hero-content { width: calc(100% - 48px); align-items: flex-start; padding-block: 76px 64px; }\n  .cinematic-copy h1 { font-size: clamp(2.9rem,12.5vw,3.5rem); line-height: .98; }\n  .cinematic-support { margin-top: 20px; }\n  .cinematic-copy .lede { font-size: .96rem; }\n  .cinematic-copy .hero-actions { align-items: stretch; }\n  .cinematic-copy .hero-actions .button { flex: 1 1 9.5rem; padding-inline: 13px; }\n  .editorial-section { padding-block: 78px; }\n  .editorial-grid { gap: 38px; }\n  .section-index { margin-bottom: 26px; }\n  .editorial-copy h2, .action-entry h2, .contact-finale h2 { font-size: clamp(2.45rem,12vw,3.35rem); }\n  .process-list { grid-template-columns: 1fr; }\n  .process-list li { min-height: 0; padding: 27px 0; border-left: 0; }\n  .process-list li + li { padding-left: 0; border-left: 0; border-top: 1px solid #d0d9db; }\n  .process-list li > span { margin-bottom: 24px; }\n  .action-entry-grid { grid-template-columns: 1fr; }\n  .action-entry article { min-height: 410px; padding: 28px 24px; }\n  .action-entry article > svg { margin-top: 60px; }\n  .contact-finale-inner { align-items: flex-start; flex-direction: column; }\n  .login-backdrop { inset: 0; }\n}\n\n/* Shared header: rem-based container queries also respond to text enlargement. */\n.site-header { container-type: inline-size; }\n.site-header .header-inner { gap: 24px; }\n.site-header .brand { min-width: 0; }\n.site-header .brand .brand-logo { flex-shrink: 0; }\n.site-header .brand span { min-width: 0; white-space: normal; overflow-wrap: anywhere; }\n.site-header .menu-button { display: none; flex-shrink: 0; min-width: 44px; min-height: 44px; align-items: center; justify-content: center; order: 0; cursor: pointer; }\n.site-header .nav { position: static; inset: auto; display: flex; flex-direction: row; align-items: center; gap: 20px; margin-left: auto; padding: 0; border: 0; border-radius: 0; box-shadow: none; background: transparent; font-size: .92rem; }\n.site-header .nav a { white-space: normal; }\n.site-header .nav .button { padding-block: 8px; }\n\n@container (max-width: 64rem) {\n  .site-header .header-inner { width: 100%; gap: 12px; padding: 8px 12px; }\n  .site-header .brand { flex: 1; }\n  .site-header .menu-button { display: inline-flex; }\n  .site-header .nav { position: absolute; inset: calc(100% + 8px) 0 auto; display: none; flex-direction: column; align-items: stretch; gap: 6px; margin: 0; padding: 16px; border: 1px solid var(--line); border-radius: 14px; background: var(--cream); color: var(--navy); box-shadow: var(--shadow); max-height: calc(100dvh - var(--header-height, 100px) - 32px); overflow-y: auto; overscroll-behavior: contain; }\n  .site-header .nav.open { display: flex; }\n  .site-header .nav a { flex-shrink: 0; min-height: 44px; padding: 8px 12px; overflow-wrap: anywhere; }\n  .site-header .nav a:not(.button) { color: var(--navy); }\n  .site-header .nav .button { color: white; }\n}\n\n/* Preserve image frames while displaying standalone local photographs. */\n.photo-fill, .cinematic-hero-background { position: absolute; inset: 0; width: 100%; height: 100%; }\n.editorial-image .photo-contain, .page-hero-image .photo-contain { object-fit: contain; object-position: center; }\n.service-photo { position: relative; overflow: hidden; border-radius: inherit; background: #e8eded; }\n.service-photo img { display: block; width: 100%; height: auto; }\n.about-network-image, .about-thumbnail { background: #e8eded; }\n@media (max-width: 900px) {\n  .cinematic-hero-background { object-fit: contain; object-position: center bottom; }\n}\n\n/* Photograph-only frames follow native source ratios; logos and the stationary\n   homepage background have their own sizing rules. */\n[data-photo-frame] { position: relative; align-self: center; min-width: 0; min-height: 0; padding: 0; overflow: hidden; isolation: isolate; transition: transform 600ms cubic-bezier(.2,.7,.25,1); }\n[data-photo-frame] > img { position: static; display: block; width: 100%; height: auto; object-fit: contain; }\n[data-photo-frame]::after { content: \"\"; position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse at var(--photo-x,50%) var(--photo-y,50%),rgba(198,255,250,.32),transparent 62%); opacity: 0; transition: opacity 600ms; }\n[data-photo-hover]::after { opacity: 1; }\n.image-feedback-layer { position: absolute; z-index: 4; pointer-events: none; user-select: none; }\n.image-feedback-ripple { width: 116px; height: 116px; transform: translate(-50%,-50%); border-radius: 50%; border: 3px solid #42e0cf; background: radial-gradient(circle,rgba(63,213,197,.55),rgba(34,163,169,.25) 58%,transparent 70%); box-shadow: 0 0 0 2px rgba(239,255,255,.8); }\n/* Match the replaced orbital area's height so Quote text and form stay put. */\n.quote-media { position: relative; height: 330px; min-width: 0; display: grid; place-items: center; overflow: hidden; isolation: isolate; contain: layout paint; }\n.quote-photo { width: min(423px,calc(100% - 48px)); border-radius: 8px; box-shadow: 0 12px 28px #0c27372b; }\n.quote-bubble-canvas, .quote-bubble-fallback { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; z-index: 2; }\n.quote-bubble-fallback i { position: absolute; width: 40px; aspect-ratio: 1; border-radius: 50%; border: 1px solid #a7d4d4; background: radial-gradient(circle at 28% 24%,#ffffffed,#abd9d35e 32%,#267e8552 73%,#d6f4e2ab); box-shadow: inset -4px -5px 9px #194f5c26,0 5px 12px #194f5c14; }\n.quote-bubble-fallback i:nth-child(1) { left: 4%; top: 18%; }\n.quote-bubble-fallback i:nth-child(2) { right: 4%; top: 13%; width: 30px; }\n.quote-bubble-fallback i:nth-child(3) { left: 5%; bottom: 11%; width: 24px; }\n.quote-bubble-fallback i:nth-child(4) { right: 4%; bottom: 14%; width: 44px; }\n[data-bubbles=\"webgl\"] .quote-bubble-fallback { visibility: hidden; }\n@media (max-width: 900px) { .quote-media { height: 210px; } .quote-photo { width: min(243px,calc(100% - 48px)); } }\n@media (prefers-reduced-motion: reduce) {\n  [data-photo-frame] { transform: none !important; transition: none; }\n  [data-photo-frame]::after { transition: none; opacity: 0; }\n  .quote-bubble-canvas { visibility: hidden; }\n  [data-bubbles=\"webgl\"] .quote-bubble-fallback { visibility: visible; }\n}\n\n/* The shared 3:2 crop applies only to the four homepage process photographs. */\n.process-list .process-photo > img { width: 100%; height: 100%; object-fit: cover; object-position: center; }\n/* Keep the existing scanner at the left and its complete barcode visible. */\n.process-list .process-photo-scan > img { object-position: left center; }\n/* Preserve the deployed International hero's intentional contrast treatment. */\n.page-hero-international .page-hero-image img { filter: brightness(.82) saturate(.85); }\n",
    "app/layout.tsx": "import type { Metadata } from \"next\";\nimport { siteUrl } from \"@/lib/config\";\nimport \"./globals.css\";\nimport { ImageFeedback } from \"@/components/image-feedback\";\n\nexport const metadata: Metadata = {\n  metadataBase: siteUrl ? new URL(siteUrl) : undefined,\n  title: { default: \"VK AND COMPANY | Courier Services\", template: \"%s | VK AND COMPANY\" },\n  description: \"Domestic and international courier enquiries and quotations from VK AND COMPANY.\",\n};\n\nexport default function RootLayout({ children }: Readonly<{ children: React.ReactNode }>) {\n  return <html lang=\"en\"><body><ImageFeedback/>{children}</body></html>;\n}\n",
    "app/not-found.tsx": "import Link from\"next/link\";export default function NotFound(){return <main className=\"page-hero\" style={{minHeight:\"70vh\"}}><div className=\"shell\"><p className=\"eyebrow\">Not found</p><h1>This page is not available.</h1><p className=\"lede\">The link may be invalid, expired or no longer active.</p><Link href=\"/\" className=\"button\" style={{marginTop:28}}>Return home</Link></div></main>}\n",
    "app/robots.ts": "import type { MetadataRoute } from \"next\";\nimport { siteUrl } from \"@/lib/config\";\nexport const dynamic = \"force-static\";\nexport default function robots(): MetadataRoute.Robots {\n  return { rules: { userAgent: \"*\", ...(siteUrl ? { allow: \"/\" } : { disallow: \"/\" }) }, ...(siteUrl ? { sitemap: `${siteUrl}/sitemap.xml` } : {}) };\n}\n",
    "app/sitemap.ts": "import type { MetadataRoute } from \"next\";\nimport { siteUrl } from \"@/lib/config\";\nexport const dynamic = \"force-static\";\nexport default function sitemap(): MetadataRoute.Sitemap {\n  if (!siteUrl) return [];\n  return [\"\", \"/services/domestic\", \"/services/international\", \"/get-a-quote\", \"/about\", \"/contact\", \"/track\", \"/faq\", \"/privacy\", \"/terms\"].map(path => ({ url: `${siteUrl}${path}`, changeFrequency: path === \"\" ? \"weekly\" : \"monthly\", priority: path === \"\" ? 1 : 0.7 }));\n}\n",
    "components/company-logo.tsx": "import Image from \"next/image\";\nimport { businessConfig } from \"@/lib/config\";\n\nexport function CompanyLogo({ alt = \"VK AND COMPANY\", className = \"\", priority = false }: {\n  alt?: string;\n  className?: string;\n  priority?: boolean;\n}) {\n  return <span className={`brand-logo ${className}`} data-image-feedback=\"logo\">\n    <Image src={businessConfig.logoPath} width={500} height={500} alt={alt} preload={priority} unoptimized />\n  </span>;\n}\n",
    "components/faq-list.tsx": "export const faqs = [\n  [\"How do I request a courier quote?\", \"Share your contact, route and parcel details in the quotation form. The team will review your request and contact you with a confirmed offer.\"],\n  [\"Does submitting the form confirm my booking?\", \"No. It creates an enquiry only. A booking is created after a quote has been prepared and accepted.\"],\n  [\"Can all international parcels be accepted?\", \"Acceptance depends on the contents, documentation, route availability and applicable restrictions. These are confirmed for the specific shipment.\"],\n  [\"Is pickup automatically scheduled?\", \"No. Pickup requests are currently unavailable. When enabled, a requested date will still need staff confirmation.\"],\n];\n\nexport function FaqList({ limit }: { limit?: number }) {\n  return <div className=\"faq-list\">{faqs.slice(0, limit).map(([question, answer]) => <details className=\"faq-item\" key={question}><summary>{question}</summary><p>{answer}</p></details>)}</div>;\n}\n",
    "components/forms/enquiry-form.tsx": "\"use client\";\n\nimport { useRef, useState } from \"react\";\nimport { Send } from \"lucide-react\";\nimport { zodErrors } from \"@/lib/schemas\";\nimport { buildQuotePayload, quoteFormSchema, quoteOutcome, quoteOutcomeMessages, QUOTE_BODY_LIMIT, QUOTE_FORMSUBMIT_ENDPOINT, QUOTE_TIMEOUT_MS } from \"@/lib/quote-formsubmit\";\n\ntype Result = { ok: boolean; message: string; fields?: Record<string,string> };\n\nfunction FieldError({ name, errors }: { name: string; errors: Record<string,string> }) {\n  return errors[name] ? <span className=\"field-error\" id={`${name}-error`}>{errors[name]}</span> : null;\n}\n\nexport function EnquiryForm() {\n  const formRef = useRef<HTMLFormElement>(null);\n  const attempts = useRef<number[]>([]);\n  const submitting = useRef(false);\n  const [result, setResult] = useState<Result | null>(null);\n  const [pending, setPending] = useState(false);\n  async function submit(event: React.FormEvent<HTMLFormElement>) {\n    event.preventDefault();\n    if (submitting.current) return;\n    const form = event.currentTarget;\n    const parsed = quoteFormSchema.safeParse({ ...Object.fromEntries(new FormData(form)), pickupRequested: false });\n    if (!parsed.success) {\n      const fields = zodErrors(parsed.error);\n      setResult({ ok: false, message: fields.website ? \"We could not validate this form. Please reload and try again.\" : \"Please correct the highlighted fields.\", fields });\n      const firstInvalid = Array.from(form.elements).find(element =>\n        (element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement || element instanceof HTMLSelectElement)\n        && element.name !== \"website\" && fields[element.name]);\n      if (firstInvalid instanceof HTMLElement) firstInvalid.focus();\n      return;\n    }\n    const body = JSON.stringify(buildQuotePayload(parsed.data));\n    if (new TextEncoder().encode(body).byteLength > QUOTE_BODY_LIMIT) {\n      setResult({ ok: false, message: \"The request is too large. Please shorten your message.\" });\n      return;\n    }\n    const now = Date.now();\n    attempts.current = attempts.current.filter(time => time > now - 15 * 60_000);\n    if (attempts.current.length >= 8) {\n      setResult({ ok: false, message: \"Too many attempts. Please wait 15 minutes before trying again.\" });\n      return;\n    }\n    attempts.current.push(now);\n    submitting.current = true;\n    setPending(true); setResult(null);\n    const controller = new AbortController();\n    const timeout = setTimeout(() => controller.abort(), QUOTE_TIMEOUT_MS);\n    try {\n      const response = await fetch(QUOTE_FORMSUBMIT_ENDPOINT, { method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\", Accept: \"application/json\" }, body, signal: controller.signal });\n      const json: unknown = await response.json();\n      const outcome = quoteOutcome(response.status, json);\n      setResult({ ok: outcome === \"accepted\", message: quoteOutcomeMessages[outcome] });\n      if (outcome === \"accepted\") formRef.current?.reset();\n    } catch { setResult({ ok: false, message: quoteOutcomeMessages.uncertain }); }\n    finally { clearTimeout(timeout); submitting.current = false; setPending(false); }\n  }\n  const errors = result?.fields || {};\n  const fieldProps = (name: string) => ({ \"aria-invalid\": Boolean(errors[name]), \"aria-describedby\": errors[name] ? `${name}-error` : undefined });\n  return <form className=\"form-panel\" ref={formRef} onSubmit={submit} noValidate>\n    <div className=\"honeypot\" aria-hidden=\"true\"><label>Website<input name=\"website\" tabIndex={-1} autoComplete=\"off\" /></label></div>\n    <fieldset className=\"form-section\"><legend>Your details</legend><div className=\"form-grid\">\n      <div className=\"field\"><label htmlFor=\"name\">Name</label><input id=\"name\" name=\"name\" autoComplete=\"name\" required {...fieldProps(\"name\")}/><FieldError name=\"name\" errors={errors}/></div>\n      <div className=\"field\"><label htmlFor=\"phone\">Phone number</label><input id=\"phone\" name=\"phone\" type=\"tel\" autoComplete=\"tel\" placeholder=\"Include country code\" required {...fieldProps(\"phone\")}/><FieldError name=\"phone\" errors={errors}/></div>\n      <div className=\"field field-full\"><label htmlFor=\"email\">Email <small>(optional)</small></label><input id=\"email\" name=\"email\" type=\"email\" autoComplete=\"email\" {...fieldProps(\"email\")}/><FieldError name=\"email\" errors={errors}/></div>\n    </div></fieldset>\n    <fieldset className=\"form-section\"><legend>Route</legend><div className=\"form-grid\">\n      <div className=\"field\"><label htmlFor=\"originCountry\">Origin country</label><input id=\"originCountry\" name=\"originCountry\" autoComplete=\"country-name\" required {...fieldProps(\"originCountry\")}/><FieldError name=\"originCountry\" errors={errors}/></div>\n      <div className=\"field\"><label htmlFor=\"originCity\">Origin city</label><input id=\"originCity\" name=\"originCity\" autoComplete=\"address-level2\" required {...fieldProps(\"originCity\")}/><FieldError name=\"originCity\" errors={errors}/></div>\n      <div className=\"field field-full\"><label htmlFor=\"originPostalCode\">Origin postal code</label><input id=\"originPostalCode\" name=\"originPostalCode\" autoComplete=\"postal-code\" required {...fieldProps(\"originPostalCode\")}/><FieldError name=\"originPostalCode\" errors={errors}/></div>\n      <div className=\"field\"><label htmlFor=\"destinationCountry\">Destination country</label><input id=\"destinationCountry\" name=\"destinationCountry\" required {...fieldProps(\"destinationCountry\")}/><FieldError name=\"destinationCountry\" errors={errors}/></div>\n      <div className=\"field\"><label htmlFor=\"destinationCity\">Destination city</label><input id=\"destinationCity\" name=\"destinationCity\" required {...fieldProps(\"destinationCity\")}/><FieldError name=\"destinationCity\" errors={errors}/></div>\n      <div className=\"field field-full\"><label htmlFor=\"destinationPostalCode\">Destination postal code</label><input id=\"destinationPostalCode\" name=\"destinationPostalCode\" required {...fieldProps(\"destinationPostalCode\")}/><FieldError name=\"destinationPostalCode\" errors={errors}/></div>\n    </div></fieldset>\n    <fieldset className=\"form-section\"><legend>Shipment</legend><div className=\"form-grid\">\n      <div className=\"field field-full\"><label htmlFor=\"contentsDescription\">Contents description</label><textarea id=\"contentsDescription\" name=\"contentsDescription\" required {...fieldProps(\"contentsDescription\")}/><small>Be clear about the actual contents; acceptance is confirmed after review.</small><FieldError name=\"contentsDescription\" errors={errors}/></div>\n      <div className=\"field\"><label htmlFor=\"packageCount\">Number of packages</label><input id=\"packageCount\" name=\"packageCount\" type=\"number\" min=\"1\" defaultValue=\"1\" required {...fieldProps(\"packageCount\")}/><FieldError name=\"packageCount\" errors={errors}/></div>\n      <div className=\"field\"><label htmlFor=\"approximateWeight\">Approximate weight</label><div style={{display:\"grid\",gridTemplateColumns:\"1fr 85px\",gap:8}}><input id=\"approximateWeight\" name=\"approximateWeight\" type=\"number\" min=\"0.001\" step=\"0.001\" required {...fieldProps(\"approximateWeight\")}/><select name=\"weightUnit\" aria-label=\"Weight unit\"><option value=\"kg\">kg</option><option value=\"lb\">lb</option></select></div><FieldError name=\"approximateWeight\" errors={errors}/></div>\n      <div className=\"field\"><label htmlFor=\"dimensions\">Dimensions <small>(when known)</small></label><input id=\"dimensions\" name=\"dimensions\" placeholder=\"L × W × H\" {...fieldProps(\"dimensions\")}/><FieldError name=\"dimensions\" errors={errors}/></div>\n      <div className=\"field\"><label htmlFor=\"dimensionUnit\">Dimension unit</label><select id=\"dimensionUnit\" name=\"dimensionUnit\"><option value=\"cm\">centimetres</option><option value=\"in\">inches</option></select></div>\n      <div className=\"field field-full\"><label htmlFor=\"preferredDispatchDate\">Preferred dispatch date <small>(not guaranteed)</small></label><input id=\"preferredDispatchDate\" name=\"preferredDispatchDate\" type=\"date\" {...fieldProps(\"preferredDispatchDate\")}/><FieldError name=\"preferredDispatchDate\" errors={errors}/></div>\n      <div className=\"field field-full\"><label htmlFor=\"instructions\">Additional instructions</label><textarea id=\"instructions\" name=\"instructions\" {...fieldProps(\"instructions\")}/><FieldError name=\"instructions\" errors={errors}/></div>\n    </div></fieldset>\n    <p className=\"notice\">Submitting this form creates an enquiry. It does not confirm a quote, booking, pickup or dispatch.</p>\n    {result && <div className={`form-status ${result.ok ? \"\" : \"error\"}`} role=\"status\">{result.message}</div>}\n    <button className=\"button\" type=\"submit\" disabled={pending}>{pending ? \"Submitting…\" : <>Send quote request <Send size={17}/></>}</button>\n  </form>;\n}\n",
    "components/forms/support-form.tsx": "\"use client\";\n\nimport { useRef, useState } from \"react\";\nimport { ArrowRight } from \"lucide-react\";\nimport { contactFormSchema, zodErrors } from \"@/lib/schemas\";\n\nconst CONTACT_ENDPOINT = \"https://formsubmit.co/ajax/vkandcompanymohali@gmail.com\";\nconst CONTACT_SUBJECT = \"VK AND COMPANY — New Contact Enquiry\";\nconst UNCONFIRMED = \"We could not confirm your submission. It may have been accepted. Please check with the company before resubmitting.\";\n\nfunction FieldError({ name, errors }: { name: string; errors: Record<string, string> }) {\n  return errors[name] ? <span className=\"field-error\" id={`contact-${name}-error`}>{errors[name]}</span> : null;\n}\n\nexport function SupportForm() {\n  const submitting = useRef(false);\n  const attempts = useRef<number[]>([]);\n  const formRef = useRef<HTMLFormElement>(null);\n  const [pending,setPending]=useState(false);\n  const [errors, setErrors] = useState<Record<string, string>>({});\n  const [result,setResult]=useState<{ok:boolean;message:string;reference?:string}|null>(null);\n  async function submit(event: React.FormEvent<HTMLFormElement>) {\n    event.preventDefault();\n    if (submitting.current) return;\n    const form = event.currentTarget;\n    const parsed = contactFormSchema.safeParse(Object.fromEntries(new FormData(form)));\n    if (!parsed.success) {\n      const fields = zodErrors(parsed.error);\n      setErrors(fields);\n      setResult({ ok: false, message: fields.website || \"Please check the highlighted fields.\" });\n      const firstInvalid = Array.from(form.elements).find(element =>\n        (element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement || element instanceof HTMLSelectElement)\n        && element.name !== \"website\" && fields[element.name]);\n      if (firstInvalid instanceof HTMLElement) firstInvalid.focus();\n      return;\n    }\n    setErrors({});\n    const now = Date.now();\n    attempts.current = attempts.current.filter(time => time > now - 15 * 60_000);\n    if (attempts.current.length >= 6) {\n      setResult({ ok: false, message: \"Too many attempts. Please wait 15 minutes before trying again.\" });\n      return;\n    }\n    const value = parsed.data;\n    // Whitelist fields: never forward customer-supplied FormSubmit settings.\n    const payload = {\n      name: value.name, email: value.email || \"\", phone: value.phone || \"\", message: value.message,\n      subject: value.subject, shipmentReference: value.shipmentReference || \"\",\n      _subject: CONTACT_SUBJECT, _honey: value.website,\n      ...(value.email ? { _replyto: value.email } : {}),\n    };\n    submitting.current = true;\n    attempts.current.push(now);\n    setPending(true); setResult(null);\n    const controller = new AbortController();\n    const timeout = setTimeout(() => controller.abort(), 20_000);\n    try {\n      const response = await fetch(CONTACT_ENDPOINT, {\n        method: \"POST\", headers: { \"Content-Type\": \"application/json\", Accept: \"application/json\" },\n        body: JSON.stringify(payload), signal: controller.signal,\n      });\n      const body: unknown = await response.json();\n      const success = typeof body === \"object\" && body !== null && \"success\" in body\n        && (body.success === true || body.success === \"true\");\n      if (!response.ok || !success) {\n        setResult({ ok: false, message: UNCONFIRMED });\n        return;\n      }\n      setResult({ ok: true, message: \"FormSubmit accepted your enquiry for processing. This does not confirm inbox delivery.\" });\n      formRef.current?.reset();\n    } catch {\n      setResult({ ok: false, message: UNCONFIRMED });\n    } finally {\n      clearTimeout(timeout);\n      submitting.current = false; setPending(false);\n    }\n  }\n  const fieldProps = (name: string) => ({\n    \"aria-invalid\": Boolean(errors[name]),\n    \"aria-describedby\": [name === \"email\" ? \"contact-details-hint\" : \"\", errors[name] ? `contact-${name}-error` : \"\"].filter(Boolean).join(\" \") || undefined,\n  });\n  return <form className=\"form-panel\" ref={formRef} onSubmit={submit} noValidate>\n    <div className=\"honeypot\" aria-hidden=\"true\"><label>Website<input name=\"website\" tabIndex={-1}/></label></div>\n    <div className=\"form-grid\">\n      <div className=\"field\"><label htmlFor=\"name\">Name</label><input id=\"name\" name=\"name\" required minLength={2} maxLength={120} {...fieldProps(\"name\")}/><FieldError name=\"name\" errors={errors}/></div>\n      <div className=\"field\"><label htmlFor=\"phone\">Phone</label><input id=\"phone\" name=\"phone\" type=\"tel\" minLength={7} maxLength={32} {...fieldProps(\"phone\")}/><FieldError name=\"phone\" errors={errors}/></div>\n      <div className=\"field field-full\"><label htmlFor=\"email\">Email</label><input id=\"email\" name=\"email\" type=\"email\" maxLength={254} {...fieldProps(\"email\")}/><small id=\"contact-details-hint\">Provide an email or phone number so the team can respond.</small><FieldError name=\"email\" errors={errors}/></div>\n      <div className=\"field field-full\"><label htmlFor=\"subject\">Subject</label><select id=\"subject\" name=\"subject\" required defaultValue=\"General Enquiry\" {...fieldProps(\"subject\")}><option>General Enquiry</option><option>Quote Request</option><option>Shipment Support</option><option>Partnerships &amp; Other</option></select><FieldError name=\"subject\" errors={errors}/></div>\n      <div className=\"field field-full\"><label htmlFor=\"message\">Message</label><textarea id=\"message\" name=\"message\" placeholder=\"Tell us how we can help…\" required minLength={10} maxLength={3000} {...fieldProps(\"message\")}/><FieldError name=\"message\" errors={errors}/></div>\n    </div>\n    {result&&<div className={`form-status ${result.ok?\"\":\"error\"}`} role=\"status\">{result.message}{result.reference&&<><br/><strong>Reference: {result.reference}</strong></>}</div>}\n    <button className=\"button\" disabled={pending}>{pending?\"Sending…\":\"Send message\"}<ArrowRight size={18} aria-hidden=\"true\"/></button>\n  </form>;\n}\n",
    "components/image-feedback.tsx": "\"use client\";\n\nimport { useEffect } from \"react\";\nimport { MEDIA_INTERACTION, type MediaInteraction } from \"@/lib/media-interaction\";\n\nconst photos = '[data-image-feedback=\"photo\"]';\nconst fields = \"input, textarea, select, label, button, summary, [contenteditable]:not([contenteditable='false'])\";\n\n// One passive recognizer owns photo hover and tap. Native activation/scroll/zoom\n// are never cancelled; the bounded Quote scene subscribes to its local events.\nexport function ImageFeedback() {\n  useEffect(() => {\n    const reduced = matchMedia(\"(prefers-reduced-motion: reduce)\");\n    const pointers = new Set<number>();\n    let gesture: { target: Element; id: number; x: number; y: number; at: number; valid: boolean } | null = null;\n    let hovered: HTMLElement | null = null;\n    let cleanup: (() => void) | undefined;\n    let raf = 0;\n    let pending: { frame: HTMLElement; x: number; y: number } | null = null;\n    const publish = (frame: HTMLElement, detail: MediaInteraction) => frame.dispatchEvent(new CustomEvent(MEDIA_INTERACTION, { bubbles: true, detail }));\n    function cancel() { if (gesture) gesture.valid = false; }\n    function leave() {\n      cancelAnimationFrame(raf); pending = null;\n      if (hovered) {\n        hovered.style.removeProperty(\"transform\");\n        hovered.removeAttribute(\"data-photo-hover\");\n        publish(hovered, { kind: \"leave\", x: 0, y: 0 });\n        hovered = null;\n      }\n    }\n    function down(event: PointerEvent) {\n      pointers.add(event.pointerId);\n      if (!event.isPrimary || pointers.size > 1) { cancel(); leave(); return; }\n      gesture = event.button === 0 && event.target instanceof Element\n        ? { target: event.target, id: event.pointerId, x: event.clientX, y: event.clientY, at: performance.now(), valid: true } : null;\n    }\n    function move(event: PointerEvent) {\n      if (gesture?.id === event.pointerId && Math.hypot(event.clientX - gesture.x, event.clientY - gesture.y) > 8) cancel();\n      if (event.pointerType === \"touch\" || reduced.matches || event.buttons || !(event.target instanceof Element)) return;\n      const frame = !event.target.closest(fields) ? event.target.closest<HTMLElement>(photos) : null;\n      if (frame !== hovered) leave();\n      if (!frame) return;\n      hovered = frame;\n      const b = frame.getBoundingClientRect();\n      pending = { frame, x: Math.max(-1, Math.min(1, (event.clientX - b.left) / b.width * 2 - 1)), y: Math.max(-1, Math.min(1, (event.clientY - b.top) / b.height * 2 - 1)) };\n      cancelAnimationFrame(raf);\n      raf = requestAnimationFrame(() => {\n        if (!pending) return;\n        const { frame, x, y } = pending;\n        frame.style.transform = `perspective(1000px) rotateX(${-y * 3.5}deg) rotateY(${x * 3.5}deg)`;\n        frame.style.setProperty(\"--photo-x\", `${(x + 1) * 50}%`);\n        frame.style.setProperty(\"--photo-y\", `${(y + 1) * 50}%`);\n        frame.dataset.photoHover = \"\";\n        publish(frame, { kind: \"move\", x, y });\n        pending = null;\n      });\n    }\n    function out(event: PointerEvent) {\n      if (hovered && (!(event.relatedTarget instanceof Node) || !hovered.contains(event.relatedTarget))) leave();\n    }\n    function up(event: PointerEvent) { pointers.delete(event.pointerId); }\n    function pointerCancel(event: PointerEvent) { up(event); cancel(); leave(); }\n    function clear() { cleanup?.(); }\n    function click(event: MouseEvent) {\n      const previous = gesture; gesture = null;\n      if (!(event.target instanceof Element) || getSelection()?.toString() || event.target.closest(fields)) return;\n      const frame = event.target.closest<HTMLElement>(photos) ?? (event.detail === 0 ? event.target.closest(\"a[href]\")?.querySelector<HTMLElement>(photos) : null);\n      if (!frame) return;\n      if (event.detail !== 0 && (!previous?.valid || performance.now() - previous.at > 750 ||\n        Math.hypot(event.clientX - previous.x, event.clientY - previous.y) > 8 ||\n        !(event.target.contains(previous.target) || previous.target.contains(event.target)))) return;\n      clear(); leave();\n      // Resolve the resting box before locating the ripple, even mid-hover.\n      frame.style.transition = \"none\";\n      const b = frame.getBoundingClientRect();\n      frame.style.removeProperty(\"transition\");\n      const x = event.detail === 0 ? b.width / 2 : event.clientX - b.left - frame.clientLeft;\n      const y = event.detail === 0 ? b.height / 2 : event.clientY - b.top - frame.clientTop;\n      const layer = document.createElement(\"i\");\n      layer.className = \"image-feedback-layer image-feedback-ripple\";\n      layer.setAttribute(\"aria-hidden\", \"true\");\n      Object.assign(layer.style, { left: `${x}px`, top: `${y}px` });\n      frame.append(layer);\n      const animations: Animation[] = [];\n      if (!reduced.matches) {\n        // The whole clipped frame moves; the inner photograph stays edge-to-edge.\n        animations.push(frame.animate([{ transform: \"perspective(1000px) translateZ(0) scale(1)\" },\n          { transform: \"perspective(1000px) translateZ(-24px) scale(.985)\", offset: .22 },\n          { transform: \"perspective(1000px) translateZ(5px) scale(1.005)\", offset: .57 },\n          { transform: \"perspective(1000px) translateZ(0) scale(1)\" }], { duration: 640, easing: \"cubic-bezier(.2,.7,.25,1)\" }));\n      }\n      animations.push(layer.animate(reduced.matches ? [{ opacity: .95 }, { opacity: .95, offset: .7 }, { opacity: 0 }] : [\n        { transform: \"translate(-50%,-50%) scale(.2)\", opacity: 1 },\n        { transform: \"translate(-50%,-50%) scale(1.2)\", opacity: .9, offset: .5 },\n        { transform: \"translate(-50%,-50%) scale(1.8)\", opacity: 0 },\n      ], { duration: 640, easing: \"ease-out\" }));\n      publish(frame, { kind: \"tap\", x: x / b.width * 2 - 1, y: y / b.height * 2 - 1 });\n      const timer = window.setTimeout(clear, 680);\n      cleanup = () => { cleanup = undefined; clearTimeout(timer); animations.forEach(a => a.cancel()); layer.remove(); };\n    }\n    function scroll() { cancel(); clear(); leave(); }\n    function blur() { scroll(); pointers.clear(); }\n    const passive = { capture: true, passive: true };\n    document.addEventListener(\"pointerdown\", down, passive);\n    document.addEventListener(\"pointermove\", move, passive);\n    document.addEventListener(\"pointerout\", out, passive);\n    document.addEventListener(\"pointerup\", up, passive);\n    document.addEventListener(\"pointercancel\", pointerCancel, passive);\n    document.addEventListener(\"click\", click, passive);\n    document.addEventListener(\"dragstart\", cancel, passive);\n    document.addEventListener(\"scroll\", scroll, passive);\n    window.addEventListener(\"blur\", blur);\n    reduced.addEventListener(\"change\", blur);\n    return () => {\n      document.removeEventListener(\"pointerdown\", down, true);\n      document.removeEventListener(\"pointermove\", move, true);\n      document.removeEventListener(\"pointerout\", out, true);\n      document.removeEventListener(\"pointerup\", up, true);\n      document.removeEventListener(\"pointercancel\", pointerCancel, true);\n      document.removeEventListener(\"click\", click, true);\n      document.removeEventListener(\"dragstart\", cancel, true);\n      document.removeEventListener(\"scroll\", scroll, true);\n      window.removeEventListener(\"blur\", blur);\n      reduced.removeEventListener(\"change\", blur);\n      blur();\n    };\n  }, []);\n  return null;\n}\n",
    "components/motion-control.tsx": "\"use client\";\n\nimport { Pause, Play } from \"lucide-react\";\nimport { useEffect, useState } from \"react\";\n\nexport const MOTION_KEY = \"vk-motion-paused\";\nexport const MOTION_EVENT = \"vk:motion-preference\";\n\nexport function MotionControl() {\n  const [paused, setPaused] = useState(false);\n  const [systemReduced, setSystemReduced] = useState(false);\n\n  useEffect(() => {\n    const query = window.matchMedia(\"(prefers-reduced-motion: reduce)\");\n    const updateSystem = () => setSystemReduced(query.matches);\n    const frame = requestAnimationFrame(() => {\n      updateSystem();\n      setPaused(window.localStorage.getItem(MOTION_KEY) === \"true\");\n    });\n    query.addEventListener(\"change\", updateSystem);\n    return () => { cancelAnimationFrame(frame); query.removeEventListener(\"change\", updateSystem); };\n  }, []);\n\n  const reduced = paused || systemReduced;\n  function toggle() {\n    const next = !paused;\n    setPaused(next);\n    window.localStorage.setItem(MOTION_KEY, String(next));\n    window.dispatchEvent(new CustomEvent(MOTION_EVENT, { detail: { paused: next } }));\n  }\n\n  return (\n    <button type=\"button\" className=\"motion-toggle\" onClick={toggle} aria-pressed={reduced} aria-label={reduced ? \"Enable motion\" : \"Reduce motion\"}>\n      {reduced ? <Play size={14} /> : <Pause size={14} />}\n      <span>{reduced ? \"Motion off\" : \"Motion on\"}</span>\n    </button>\n  );\n}\n",
    "components/page-hero.tsx": "import { Photograph, type PhotoName } from \"./photograph\";\nimport { QuoteMedia } from \"./quote-media\";\nimport type { SceneVariant } from \"@/components/three/scene-types\";\n\nconst imagery: Partial<Record<SceneVariant, { name: PhotoName; alt: string }>> = {\n  domestic: { name: \"selected-domestic\", alt: \"Illustrative delivery truck travelling on an intercity road\" },\n  international: { name: \"selected-international\", alt: \"Illustrative cargo aircraft at an international logistics apron\" },\n  about: { name: \"workspace\", alt: \"Illustrative parcel dispatch workspace\" },\n};\n\nexport function PageHero({ eyebrow, title, description, variant = \"legal\" }: { eyebrow: string; title: string; description: string; variant?: SceneVariant }) {\n  const image = imagery[variant];\n  return <section className={`page-hero page-hero-${variant}`}><div className=\"shell page-hero-grid\"><div className=\"page-hero-copy\"><p className=\"eyebrow\">{eyebrow}</p><h1>{title}</h1><p className=\"lede\">{description}</p></div>{variant === \"quote\" ? <QuoteMedia/> : image ? <div className=\"page-hero-image\" data-image-feedback=\"photo\" data-photo-frame=\"\"><Photograph name={image.name} alt={image.alt}  sizes=\"(max-width: 900px) 100vw, 50vw\" eager/><span>Illustrative courier environment</span></div> : <div className=\"page-hero-marker\" aria-hidden=\"true\"><span>VKC</span><i aria-hidden=\"true\"/></div>}</div></section>;\n}\n",
    "components/photograph.tsx": "import type { CSSProperties } from \"react\";\nimport manifest from \"@/lib/photographs.json\";\n\nexport type PhotoName = keyof typeof manifest;\n\n// Browser-selected local files work on Pages without a runtime image optimizer.\nexport function Photograph({ name, alt, sizes, className, style, eager = false, loading }: {\n  name: PhotoName; alt: string; sizes: string; className?: string;\n  style?: CSSProperties; eager?: boolean; loading?: \"eager\" | \"lazy\";\n}) {\n  const photo = manifest[name];\n  // Static srcSet variants are compressed at build time by prepare-photographs.mjs.\n  // eslint-disable-next-line @next/next/no-img-element\n  return <img src={`/media/photos/${name}-${photo.width}.webp`}\n    srcSet={photo.widths.map(width => `/media/photos/${name}-${width}.webp ${width}w`).join(\", \")}\n    sizes={sizes} width={photo.width} height={photo.height} alt={alt}\n    className={className} style={style} loading={loading ?? (eager ? \"eager\" : \"lazy\")}\n    fetchPriority={eager ? \"high\" : undefined} decoding=\"async\" data-illustrative=\"true\"/>;\n}\n",
    "components/process-photo.tsx": "import { Photograph } from \"./photograph\";\n\nconst photographs = {\n  details: { name: \"details\", alt: \"Illustrative parcel being weighed and measured\" },\n  review: { name: \"process-review\", alt: \"A courier and customer reviewing delivery paperwork together on a clipboard\" },\n  dispatch: { name: \"process-dispatch\", alt: \"Two delivery workers loading cardboard parcels into the back of a van\" },\n  scan: { name: \"process-scan\", alt: \"A handheld barcode scanner reading the label on a cardboard parcel\" },\n} as const;\n\nexport function ProcessPhoto({ action, sizes }: {\n  action: keyof typeof photographs; sizes: string;\n}) {\n  return <div className={`process-photo process-photo-${action}`} data-image-feedback=\"photo\" data-photo-frame=\"\">\n    <Photograph {...photographs[action]} sizes={sizes} loading=\"eager\"/>\n  </div>;\n}\n",
    "components/quote-band.tsx": "import Link from \"next/link\";\nimport { ArrowUpRight } from \"lucide-react\";\n\nexport function QuoteBand() {\n  return <section className=\"section\"><div className=\"shell quote-band\"><div><p className=\"eyebrow\" style={{ color: \"#76c4d0\" }}>Start with the shipment details</p><h2>Let’s work out the right next step for your parcel.</h2><p>No instant estimates without an approved rate card. Our team reviews each request before making an offer.</p></div><div className=\"band-action\"><Link href=\"/get-a-quote\" className=\"button\">Request a quote <ArrowUpRight size={18} /></Link></div></div></section>;\n}\n",
    "components/quote-media.tsx": "\"use client\";\n\nimport { useEffect, useRef } from \"react\";\nimport { Photograph } from \"./photograph\";\n\nexport function QuoteMedia() {\n  const host = useRef<HTMLDivElement>(null);\n  useEffect(() => {\n    const element = host.current!;\n    const reduced = matchMedia(\"(prefers-reduced-motion: reduce)\");\n    let disposed = false, visible = false, loading = false, failed = false;\n    let scene: ReturnType<typeof import(\"./three/quote-bubbles\").createQuoteBubbles> | undefined;\n    async function update() {\n      scene?.setActive(visible && !reduced.matches && !document.hidden);\n      if (disposed || failed || loading || scene || !visible || reduced.matches) return;\n      loading = true;\n      try {\n        const { createQuoteBubbles } = await import(\"./three/quote-bubbles\");\n        if (!disposed && !reduced.matches) {\n          scene = createQuoteBubbles(element, () => { failed = true; element.dataset.bubbles = \"fallback\"; });\n          scene.setActive(visible && !document.hidden);\n        }\n      } catch { failed = true; element.dataset.bubbles = \"fallback\"; }\n      finally { loading = false; }\n    }\n    const observer = new IntersectionObserver(([entry]) => { visible = entry.isIntersecting; void update(); });\n    observer.observe(element);\n    reduced.addEventListener(\"change\", update);\n    document.addEventListener(\"visibilitychange\", update);\n    return () => { disposed = true; observer.disconnect(); reduced.removeEventListener(\"change\", update); document.removeEventListener(\"visibilitychange\", update); scene?.dispose(); };\n  }, []);\n  return <div ref={host} className=\"quote-media\" data-bubbles=\"fallback\">\n    <div className=\"quote-photo\" data-image-feedback=\"photo\" data-photo-frame=\"\">\n      <Photograph name=\"details\" alt=\"Illustrative Indian courier measuring a parcel on a weighing scale beside shipping paperwork; not actual company staff or premises\" sizes=\"(max-width: 900px) 243px, 423px\" eager/>\n    </div>\n    <div className=\"quote-bubble-fallback\" aria-hidden=\"true\"><i/><i/><i/><i/></div>\n  </div>;\n}\n",
    "components/reference-artwork.module.css": ".frame { position: relative; width: 100%; overflow: hidden; border-radius: inherit; }\n.frame > img { position: absolute; display: block; max-width: none; height: auto; margin: 0; }\n",
    "components/reference-artwork.tsx": "import Image, { type StaticImageData } from \"next/image\";\nimport styles from \"./reference-artwork.module.css\";\n\n// Display only the artwork region of the supplied reference, never its page UI.\n// Coordinates are in source pixels; the original image is kept unmodified.\nexport function ReferenceArtwork({ source, region, alt, priority = false }: {\n  source: StaticImageData;\n  region: readonly [number, number, number, number];\n  alt: string;\n  priority?: boolean;\n}) {\n  const [left, top, width, height] = region;\n  return <div className={styles.frame} style={{ aspectRatio: `${width} / ${height}` }} data-image-feedback=\"background\">\n    <Image src={source} alt={alt} unoptimized preload={priority} draggable={false}\n      style={{ width: `${source.width / width * 100}%`, left: `${-left / width * 100}%`, top: `${-top / height * 100}%` }}/>\n  </div>;\n}\n",
    "components/route-transition.tsx": "\"use client\";\n\nimport { usePathname } from \"next/navigation\";\n\nexport function RouteTransition() {\n  const pathname = usePathname();\n  return <div className=\"route-transition\" key={pathname} aria-hidden=\"true\"><span /></div>;\n}\n",
    "components/service-process.module.css": ".section { padding: clamp(44px,6vw,88px) 0; background: #fff; }\n.inner { width: min(1180px,calc(100% - 56px)); margin-inline: auto; }\n.inner > h2 { margin-bottom: 30px; }\n.rows { display: grid; gap: 30px; }\n.row { display: grid; grid-template-columns: minmax(0,1.1fr) minmax(0,.9fr); gap: clamp(24px,3vw,44px); align-items: start; }\n.row + .row { border-top: 1px solid var(--line); padding-top: 30px; }\n.image { border-radius: 12px; min-width: 0; }\n.copy { min-width: 0; padding-top: 4px; }\n.copy h3 { color: #102c48; font: 400 clamp(1.85rem,3vw,2.9rem)/1.16 Georgia,serif; letter-spacing: -.025em; margin: 0 0 24px; }\n.copy p { color: #53687e; line-height: 1.7; margin: 0; overflow-wrap: anywhere; }\n@media (max-width: 640px) {\n  .inner { width: calc(100% - 32px); }\n  .row { grid-template-columns: minmax(0,1fr); gap: 22px; }\n  .copy h3 { margin-bottom: 16px; }\n}\n",
    "components/service-process.tsx": "import { Photograph } from \"./photograph\";\nimport styles from \"./service-process.module.css\";\n\nconst processes = {\n  domestic: [\n    { title: \"Begin with the real shipment details.\", text: \"Provide the origin and destination, package count, approximate weight, contents and preferred dispatch date. We use those details to assess the available next step.\", photo: \"selected-domestic-1\", alt: \"Illustration of a domestic shipment quotation form on a laptop beside a parcel\" },\n    { title: \"Review before commitment.\", text: \"A submitted enquiry is not a booking. The team will prepare a quote with relevant service details, estimates, inclusions, exclusions, currency and validity date. Your booking is created only after acceptance.\", photo: \"selected-domestic-2\", alt: \"Illustration of a courier and customer reviewing paperwork at a doorstep\" },\n    { title: \"We move it with care.\", text: \"Once confirmed, your shipment is handed over to our operational team and moves through our domestic network. You can reach out for updates whenever required.\", photo: \"selected-domestic-3\", alt: \"Illustration of a VK AND COMPANY delivery truck travelling through a city\" },\n  ],\n  international: [\n    { title: \"Route and contents review.\", text: \"Share accurate origin, destination, contents, package count, weight and dimensions where known. This supports an initial acceptance and availability review.\", photo: \"selected-international-1\", alt: \"Illustration of aircraft cargo loading with a world map and the words From India to the World\" },\n    { title: \"Documentation is shipment-specific.\", text: \"Required documentation and restrictions depend on the route and parcel. The team will explain confirmed requirements for your shipment; this website does not substitute generic claims for that review.\", photo: \"selected-international-2\", alt: \"Illustrative export-document checklist beside a passport and globe; actual requirements depend on the shipment\" },\n    { title: \"Clear quotation boundaries.\", text: \"Charges, estimates, inclusions and exclusions appear in the quote for the reviewed route. Times, routes and partner handling are subject to change based on operational factors and destination requirements.\", photo: \"selected-international-3\", alt: \"Illustration of a cargo ship, aircraft and delivery truck at an international port\" },\n  ],\n} as const;\n\nexport function ServiceProcess({ kind }: { kind: keyof typeof processes }) {\n  return <section className={styles.section} aria-labelledby={`${kind}-process`}>\n    <div className={styles.inner}>\n      <h2 className=\"eyebrow\" id={`${kind}-process`}>{kind} process</h2>\n      <div className={styles.rows}>\n        {processes[kind].map(row => <article key={row.title} className={styles.row}>\n          <div className={styles.image}><div className=\"service-photo\" data-image-feedback=\"photo\" data-photo-frame=\"\"><Photograph name={row.photo} alt={row.alt} sizes=\"(max-width: 640px) calc(100vw - 32px), (max-width: 1236px) 52vw, 625px\"/></div></div>\n          <div className={styles.copy}><h3>{row.title}</h3><p>{row.text}</p></div>\n        </article>)}\n      </div>\n    </div>\n  </section>;\n}\n",
    "components/site-footer.tsx": "import Link from \"next/link\";\nimport { CompanyLogo } from \"@/components/company-logo\";\nimport { getPublicBusinessSettings } from \"@/lib/business-settings\";\n\nexport async function SiteFooter() {\n  const settings=await getPublicBusinessSettings();\n  return (\n    <footer className=\"site-footer\">\n      <div className=\"shell\">\n        <div className=\"footer-grid\">\n          <div className=\"footer-brand\">\n            <div className=\"brand footer-logo\"><CompanyLogo alt=\"VK AND COMPANY\"/> <span>VK AND COMPANY</span></div>\n            <p>Domestic and international courier services, arranged around the details of each shipment.</p>\n          </div>\n          <div className=\"footer-col\"><h3>Services</h3><Link href=\"/services/domestic\">Domestic courier</Link><Link href=\"/services/international\">International courier</Link><Link href=\"/get-a-quote\">Request a quote</Link></div>\n          <div className=\"footer-col\"><h3>Company</h3><Link href=\"/about\">About</Link><Link href=\"/contact\">Contact</Link><Link href=\"/faq\">FAQs</Link><Link href=\"/privacy\">Privacy</Link><Link href=\"/terms\">Terms</Link>{settings.email && <a href={`mailto:${settings.email}`}>Email us</a>}</div>\n        </div>\n        <div className=\"footer-bottom\"><span>© {new Date().getFullYear()} VK AND COMPANY</span><span>Courier information is confirmed for each shipment.</span></div>\n      </div>\n    </footer>\n  );\n}\n",
    "components/site-header.tsx": "\"use client\";\n\nimport { CompanyLogo } from \"@/components/company-logo\";\nimport Link from \"next/link\";\nimport { Menu, X } from \"lucide-react\";\nimport { usePathname } from \"next/navigation\";\nimport { useEffect, useRef, useState } from \"react\";\n\nexport function SiteHeader({ hasLogo }: { hasLogo: boolean }) {\n  const pathname = usePathname();\n  const [openPath, setOpenPath] = useState<string | null>(null);\n  const open = openPath === pathname;\n  const header = useRef<HTMLElement>(null);\n  const menuButton = useRef<HTMLButtonElement>(null);\n  const firstLink = useRef<HTMLAnchorElement>(null);\n\n  function closeMenu(restoreFocus = false) {\n    setOpenPath(null);\n    if (restoreFocus) menuButton.current?.focus();\n  }\n\n  useEffect(() => {\n    const element = header.current;\n    if (!element) return;\n    const observer = new ResizeObserver(() => {\n      element.style.setProperty(\"--header-height\", `${element.getBoundingClientRect().height}px`);\n      if (menuButton.current?.getClientRects().length === 0) setOpenPath(null);\n    });\n    observer.observe(element);\n    return () => observer.disconnect();\n  }, []);\n\n  useEffect(() => {\n    if (!open) return;\n    firstLink.current?.focus();\n    const close = (event: KeyboardEvent) => {\n      if (event.key === \"Escape\") {\n        setOpenPath(null);\n        menuButton.current?.focus();\n      }\n    };\n    const outside = (event: PointerEvent) => {\n      if (!header.current?.contains(event.target as Node)) setOpenPath(null);\n    };\n    window.addEventListener(\"keydown\", close);\n    window.addEventListener(\"pointerdown\", outside);\n    return () => {\n      window.removeEventListener(\"keydown\", close);\n      window.removeEventListener(\"pointerdown\", outside);\n    };\n  }, [open]);\n  return (\n    <header ref={header} className={`site-header ${pathname === \"/\" ? \"home-header\" : \"\"}`} onBlur={(event) => {\n      if (!event.currentTarget.contains(event.relatedTarget)) closeMenu();\n    }}>\n      <div className=\"shell header-inner\">\n        <Link href=\"/\" className=\"brand\" aria-label=\"VK AND COMPANY home\" onClick={() => closeMenu()}>\n          {hasLogo && <CompanyLogo alt=\"VK AND COMPANY\" priority />}\n          <span>VK AND COMPANY</span>\n        </Link>\n        <button ref={menuButton} type=\"button\" className=\"menu-button\" aria-label={open ? \"Close menu\" : \"Open menu\"} aria-expanded={open} aria-controls=\"main-navigation\" onClick={() => setOpenPath(open ? null : pathname)}>\n          {open ? <X aria-hidden=\"true\" /> : <Menu aria-hidden=\"true\" />}\n        </button>\n        <nav id=\"main-navigation\" className={`nav ${open ? \"open\" : \"\"}`} aria-label=\"Main navigation\">\n          <Link ref={firstLink} href=\"/services/domestic\" onClick={() => closeMenu(open)}>Domestic</Link>\n          <Link href=\"/services/international\" onClick={() => closeMenu(open)}>International</Link>\n          <Link href=\"/about\" onClick={() => closeMenu(open)}>About</Link>\n          <Link href=\"/contact\" onClick={() => closeMenu(open)}>Contact</Link>\n          <Link href=\"/get-a-quote\" className=\"button button-small\" onClick={() => closeMenu(open)}>Get a quote</Link>\n        </nav>\n      </div>\n    </header>\n  );\n}\n",
    "components/three/courier-canvas.tsx": "\"use client\";\n\nimport { Canvas, useFrame, useThree } from \"@react-three/fiber\";\nimport { ContactShadows, Float, RoundedBox, useTexture } from \"@react-three/drei\";\nimport { Suspense, useEffect, useMemo, useRef, useState } from \"react\";\nimport * as THREE from \"three\";\nimport type { SceneVariant } from \"./scene-types\";\n\nconst colors = {\n  navy: \"#16344f\",\n  navyDeep: \"#0a2033\",\n  teal: \"#14839a\",\n  tealBright: \"#44bfd0\",\n  paper: \"#f7f4ec\",\n  silver: \"#a9bbc2\",\n  road: \"#4d6069\",\n  rubber: \"#152128\",\n  parcel: \"#b8895d\",\n};\n\nexport function BrandPlaque({ position = [0, 0, 0], rotation = [0, 0, 0], scale = 1 }: { position?: [number, number, number]; rotation?: [number, number, number]; scale?: number }) {\n  const texture = useTexture(\"/brand/vk-and-company-logo-transparent.png\");\n  const brandTexture = useMemo(() => {\n    const clone = texture.clone();\n    clone.colorSpace = THREE.SRGBColorSpace;\n    clone.anisotropy = 4;\n    clone.needsUpdate = true;\n    return clone;\n  }, [texture]);\n  useEffect(() => () => brandTexture.dispose(), [brandTexture]);\n  return (\n    <group position={position} rotation={rotation} scale={scale}>\n      <RoundedBox args={[1.18, 1.18, 0.07]} radius={0.06} smoothness={3} castShadow>\n        <meshStandardMaterial color=\"#d9d7d0\" metalness={0.18} roughness={0.42} />\n      </RoundedBox>\n      <mesh position={[0, 0, 0.039]}>\n        <planeGeometry args={[1.08, 1.08]} />\n        <meshBasicMaterial map={brandTexture} toneMapped={false} transparent />\n      </mesh>\n    </group>\n  );\n}\n\nfunction Wheel({ position, spin = 0 }: { position: [number, number, number]; spin?: number }) {\n  return (\n    <group name=\"truck-wheel\" position={position} rotation={[Math.PI / 2, spin, 0]}>\n      <mesh castShadow>\n        <cylinderGeometry args={[0.45, 0.45, 0.3, 32]} />\n        <meshStandardMaterial color={colors.rubber} roughness={0.78} />\n      </mesh>\n      <mesh position={[0, 0.16, 0]}>\n        <cylinderGeometry args={[0.23, 0.23, 0.32, 20]} />\n        <meshStandardMaterial color={colors.silver} metalness={0.72} roughness={0.25} />\n      </mesh>\n      <mesh position={[0, 0.33, 0]}>\n        <torusGeometry args={[0.31, 0.025, 8, 24]} />\n        <meshStandardMaterial color=\"#5c7079\" metalness={0.55} roughness={0.3} />\n      </mesh>\n    </group>\n  );\n}\n\nexport function Truck({ scale = 1, position = [0, 0, 0], rotation = [0, 0, 0], progress = 0, rootRef, doorOpen, wheelSpin }: { scale?: number; position?: [number, number, number]; rotation?: [number, number, number]; progress?: number; rootRef?: React.RefObject<THREE.Group | null>; doorOpen?: number; wheelSpin?: number }) {\n  const doorAngle = (doorOpen ?? Math.max(0, 1 - progress * 5)) * 0.82;\n  const spin = wheelSpin ?? progress * Math.PI * 12;\n  return (\n    <group ref={rootRef} scale={scale} position={position} rotation={rotation}>\n      <RoundedBox args={[4.05, 2.25, 2.55]} radius={0.13} smoothness={4} position={[0.42, 1.48, 0]} castShadow>\n        <meshStandardMaterial color={colors.navy} metalness={0.17} roughness={0.36} />\n      </RoundedBox>\n      {[[-0.75, 1.48], [0.55, 1.48], [1.8, 1.48]].map(([x, y]) => <mesh key={x} position={[x, y, 1.281]}><boxGeometry args={[0.022, 1.95, 0.025]} /><meshStandardMaterial color=\"#31536b\" metalness={0.4} /></mesh>)}\n      <RoundedBox args={[1.35, 1.8, 2.36]} radius={0.23} smoothness={4} position={[-2.18, 1.12, 0]} castShadow>\n        <meshStandardMaterial color={colors.teal} metalness={0.13} roughness={0.32} />\n      </RoundedBox>\n      <mesh position={[-2.76, 1.72, 0]} rotation={[0, 0, -0.12]}>\n        <boxGeometry args={[0.06, 0.72, 1.74]} />\n        <meshPhysicalMaterial color=\"#9ed2dd\" transparent opacity={0.76} metalness={0.28} roughness={0.1} transmission={0.12} />\n      </mesh>\n      {[-1.14, 1.14].map((z) => <mesh key={z} position={[-2.37, 1.48, z]}><planeGeometry args={[0.55, 0.72]} /><meshPhysicalMaterial color=\"#87beca\" transparent opacity={0.72} roughness={0.12} metalness={0.2} /></mesh>)}\n      {[-1, 1].map((z) => <group key={z} position={[-2.74, 1.48, z * 1.27]}><mesh><boxGeometry args={[0.32, 0.08, 0.08]} /><meshStandardMaterial color=\"#263942\" metalness={0.7} /></mesh><mesh position={[-0.17, 0, z * 0.05]}><boxGeometry args={[0.18, 0.3, 0.05]} /><meshStandardMaterial color=\"#1c303b\" metalness={0.45} /></mesh></group>)}\n      <mesh position={[-2.88, 0.67, 0]}><boxGeometry args={[0.12, 0.52, 1.15]} /><meshStandardMaterial color=\"#203742\" metalness={0.68} roughness={0.3} /></mesh>\n      {[-0.36, -0.14, 0.08, 0.3].map((y) => <mesh key={y} position={[-2.951, 0.67 + y, 0]}><boxGeometry args={[0.02, 0.035, 0.88]} /><meshStandardMaterial color=\"#8799a0\" metalness={0.8} /></mesh>)}\n      {[-0.92, 0.92].map((z) => <mesh key={z} position={[-2.96, 0.82, z]}><boxGeometry args={[0.07, 0.24, 0.34]} /><meshStandardMaterial color=\"#f8e4a8\" emissive=\"#e4b64a\" emissiveIntensity={0.7} /></mesh>)}\n      <mesh position={[-2.93, 0.33, 0]}><boxGeometry args={[0.18, 0.22, 2.5]} /><meshStandardMaterial color=\"#b5c3c7\" metalness={0.78} roughness={0.25} /></mesh>\n      <BrandPlaque position={[0.1, 1.48, 1.323]} scale={0.82} />\n      {[[-2.15, 0.45, 1.28], [-2.15, 0.45, -1.28], [1.42, 0.45, 1.28], [1.42, 0.45, -1.28]].map((p, index) => <Wheel key={index} position={p as [number, number, number]} spin={spin} />)}\n      {[1, -1].map((side) => <mesh name=\"rear-door\" userData={{ side }} key={side} position={[2.48, 1.5, side * 0.65]} rotation={[0, side * doorAngle, 0]} castShadow><boxGeometry args={[0.09, 2.06, 1.2]} /><meshStandardMaterial color=\"#28536d\" metalness={0.22} roughness={0.4} />{[0.36, -0.36].map((z) => <mesh key={z} position={[0.065, 0, z]}><boxGeometry args={[0.04, 1.65, 0.04]} /><meshStandardMaterial color={colors.silver} metalness={0.7} /></mesh>)}</mesh>)}\n    </group>\n  );\n}\n\nexport function Parcel({ position = [0, 0, 0], rotation = [0, 0, 0], scale = 1, branded = false }: { position?: [number, number, number]; rotation?: [number, number, number]; scale?: number | [number, number, number]; branded?: boolean }) {\n  return (\n    <group position={position} rotation={rotation} scale={scale}>\n      <RoundedBox args={[1, 0.8, 0.86]} radius={0.055} smoothness={3} castShadow>\n        <meshStandardMaterial color={colors.parcel} roughness={0.78} />\n      </RoundedBox>\n      <mesh position={[0, 0.405, 0]} rotation={[-Math.PI / 2, 0, 0]}><planeGeometry args={[0.19, 0.86]} /><meshStandardMaterial color=\"#ead4aa\" roughness={0.82} /></mesh>\n      {branded && <BrandPlaque position={[0, 0, 0.435]} scale={0.27} />}\n    </group>\n  );\n}\n\nfunction Conveyor({ position = [0, 0, 0], length = 5 }: { position?: [number, number, number]; length?: number }) {\n  return (\n    <group position={position}>\n      <RoundedBox args={[length, 0.18, 1.2]} radius={0.08} smoothness={3} position={[0, 0.72, 0]} castShadow><meshStandardMaterial color=\"#748790\" metalness={0.5} roughness={0.35} /></RoundedBox>\n      {Array.from({ length: Math.floor(length * 2) }).map((_, index) => <mesh key={index} position={[-length / 2 + 0.3 + index * 0.5, 0.83, 0]} rotation={[Math.PI / 2, 0, 0]}><cylinderGeometry args={[0.1, 0.1, 1.05, 12]} /><meshStandardMaterial color=\"#c0cbd0\" metalness={0.7} roughness={0.28} /></mesh>)}\n      {[-length / 2 + 0.35, length / 2 - 0.35].flatMap((x) => [-0.45, 0.45].map((z) => <mesh key={`${x}-${z}`} position={[x, 0.32, z]}><boxGeometry args={[0.11, 0.72, 0.11]} /><meshStandardMaterial color=\"#596c75\" metalness={0.55} /></mesh>))}\n    </group>\n  );\n}\n\nfunction Warehouse({ position = [0, 0, 0], scale = 1 }: { position?: [number, number, number]; scale?: number }) {\n  return (\n    <group position={position} scale={scale}>\n      <RoundedBox args={[5.5, 4.4, 3.6]} radius={0.16} smoothness={3} position={[0, 2.2, 0]} castShadow><meshStandardMaterial color=\"#dfe6e7\" roughness={0.77} /></RoundedBox>\n      <mesh position={[-2.755, 1.45, 0]}><boxGeometry args={[0.06, 2.9, 2.45]} /><meshStandardMaterial color=\"#244b63\" metalness={0.22} /></mesh>\n      {[-0.78, 0, 0.78].map((z) => <mesh key={z} position={[-2.79, 1.45, z]}><boxGeometry args={[0.06, 2.55, 0.045]} /><meshStandardMaterial color=\"#8ea1aa\" metalness={0.58} /></mesh>)}\n      <BrandPlaque position={[-2.82, 3.42, 0]} rotation={[0, -Math.PI / 2, 0]} scale={0.76} />\n      <mesh position={[0, 4.43, 0]} rotation={[0, 0, Math.PI / 4]}><boxGeometry args={[3.95, 3.95, 3.55]} /><meshStandardMaterial color=\"#bed0d4\" roughness={0.62} /></mesh>\n    </group>\n  );\n}\n\nfunction Road({ position = [0, 0, 0], rotation = [0, 0, 0], length = 16 }: { position?: [number, number, number]; rotation?: [number, number, number]; length?: number }) {\n  return (\n    <group position={position} rotation={rotation}>\n      <RoundedBox args={[length, 0.14, 3.3]} radius={0.34} smoothness={5} receiveShadow><meshStandardMaterial color={colors.road} roughness={0.92} /></RoundedBox>\n      {Array.from({ length: Math.ceil(length / 2) }).map((_, index) => <mesh key={index} position={[-length / 2 + 1 + index * 2.2, 0.076, 0]} rotation={[-Math.PI / 2, 0, 0]}><planeGeometry args={[1.05, 0.075]} /><meshBasicMaterial color=\"#e8eeee\" /></mesh>)}\n      {[-1.5, 1.5].map((z) => <mesh key={z} position={[0, 0.078, z]} rotation={[-Math.PI / 2, 0, 0]}><planeGeometry args={[length - 0.7, 0.045]} /><meshBasicMaterial color={colors.tealBright} /></mesh>)}\n    </group>\n  );\n}\n\nfunction CurvedRoad() {\n  return (\n    <group>\n      {Array.from({ length: 11 }).map((_, index) => {\n        const angle = -0.56 + index * 0.112;\n        return <group key={index} position={[Math.sin(angle) * 8, 0, Math.cos(angle) * 8 - 7.45]} rotation={[0, angle, 0]}><RoundedBox args={[1.72, 0.14, 3.3]} radius={0.2} smoothness={4} receiveShadow><meshStandardMaterial color={colors.road} roughness={0.92} /></RoundedBox><mesh position={[0, 0.076, 0]} rotation={[-Math.PI / 2, 0, 0]}><planeGeometry args={[0.82, 0.075]} /><meshBasicMaterial color=\"#e8eeee\" /></mesh>{[-1.5, 1.5].map((z) => <mesh key={z} position={[0, 0.078, z]} rotation={[-Math.PI / 2, 0, 0]}><planeGeometry args={[1.62, 0.045]} /><meshBasicMaterial color={colors.tealBright} /></mesh>)}</group>;\n      })}\n    </group>\n  );\n}\n\nfunction CityBlock({ position, height = 2.4, color = \"#c7d6da\" }: { position: [number, number, number]; height?: number; color?: string }) {\n  return (\n    <group position={position}>\n      <RoundedBox args={[1.35, height, 1.25]} radius={0.09} smoothness={3} position={[0, height / 2, 0]} castShadow><meshStandardMaterial color={color} roughness={0.72} /></RoundedBox>\n      {Array.from({ length: Math.max(2, Math.floor(height)) }).map((_, row) => [-0.36, 0.36].map((x) => <mesh key={`${row}-${x}`} position={[x, 0.65 + row * 0.65, 0.631]}><planeGeometry args={[0.28, 0.25]} /><meshStandardMaterial color=\"#67acb9\" emissive=\"#227d91\" emissiveIntensity={0.14} /></mesh>))}\n    </group>\n  );\n}\n\nfunction Globe({ rotation = [0, 0, 0], scale = 1 }: { rotation?: [number, number, number]; scale?: number }) {\n  const land = [[0.75, 0.42, 1.02], [-0.62, 0.7, 1.02], [-0.92, -0.25, 1.02], [0.24, -0.64, 1.04], [0.98, -0.22, 0.4]];\n  return (\n    <group rotation={rotation} scale={scale}>\n      <mesh castShadow><sphereGeometry args={[1.75, 48, 32]} /><meshPhysicalMaterial color=\"#0d4564\" metalness={0.16} roughness={0.3} clearcoat={0.4} /></mesh>\n      <mesh><sphereGeometry args={[1.77, 24, 16]} /><meshBasicMaterial color=\"#42b8c9\" wireframe transparent opacity={0.17} /></mesh>\n      {land.map(([x, y, z], index) => <mesh key={index} position={[x, y, z]} rotation={[y * 0.42, x * 0.38, index * 0.3]} scale={[0.72, 0.38, 0.12]}><sphereGeometry args={[0.62, 12, 8]} /><meshStandardMaterial color=\"#58b8a4\" roughness={0.68} /></mesh>)}\n      {[0.26, -0.42].map((tilt) => <mesh key={tilt} rotation={[Math.PI / 2 + tilt, tilt, 0]}><torusGeometry args={[2.08, 0.018, 8, 96, Math.PI * 1.45]} /><meshBasicMaterial color={colors.tealBright} /></mesh>)}\n    </group>\n  );\n}\n\nfunction CargoPlane({ position = [0, 0, 0], rotation = [0, 0, 0], scale = 1 }: { position?: [number, number, number]; rotation?: [number, number, number]; scale?: number }) {\n  return (\n    <group position={position} rotation={rotation} scale={scale}>\n      <mesh rotation={[0, 0, Math.PI / 2]} castShadow><capsuleGeometry args={[0.28, 2.6, 8, 20]} /><meshStandardMaterial color={colors.paper} metalness={0.28} roughness={0.27} /></mesh>\n      <mesh position={[0, -0.05, 0]}><boxGeometry args={[0.72, 0.12, 3.8]} /><meshStandardMaterial color={colors.teal} metalness={0.25} roughness={0.3} /></mesh>\n      <mesh position={[1.02, 0.34, 0]}><boxGeometry args={[0.7, 0.75, 0.1]} /><meshStandardMaterial color={colors.navy} /></mesh>\n      <mesh position={[1.12, 0.1, 0]}><boxGeometry args={[0.7, 0.08, 1.42]} /><meshStandardMaterial color={colors.teal} /></mesh>\n      {[-0.92, 0.92].map((z) => <group key={z} position={[-0.15, -0.17, z]}><mesh rotation={[Math.PI / 2, 0, 0]}><cylinderGeometry args={[0.2, 0.23, 0.55, 18]} /><meshStandardMaterial color=\"#263b45\" metalness={0.35} /></mesh><mesh position={[-0.18, 0, 0]} rotation={[0, 0, Math.PI / 2]}><cylinderGeometry args={[0.11, 0.11, 0.65, 16]} /><meshStandardMaterial color=\"#b7c3c8\" metalness={0.6} /></mesh></group>)}\n      <mesh position={[-1.42, 0, 0]} rotation={[0, -Math.PI / 2, 0]}><coneGeometry args={[0.29, 0.6, 20]} /><meshStandardMaterial color=\"#d9e4e7\" metalness={0.2} roughness={0.3} /></mesh>\n    </group>\n  );\n}\n\nfunction LocationPin({ position = [0, 0, 0], scale = 1 }: { position?: [number, number, number]; scale?: number }) {\n  return (\n    <group position={position} scale={scale}>\n      <mesh position={[0, 0.72, 0]} castShadow><sphereGeometry args={[0.54, 28, 20]} /><meshStandardMaterial color={colors.tealBright} metalness={0.22} roughness={0.3} /></mesh>\n      <mesh position={[0, 0.18, 0]} rotation={[0, 0, Math.PI]}><coneGeometry args={[0.42, 1.1, 28]} /><meshStandardMaterial color={colors.tealBright} metalness={0.22} roughness={0.3} /></mesh>\n      <mesh position={[0, 0.75, 0.5]}><circleGeometry args={[0.19, 24]} /><meshBasicMaterial color={colors.paper} /></mesh>\n    </group>\n  );\n}\n\nfunction RouteArc({ radius = 2.2, color = colors.tealBright, rotation = [0, 0, 0] }: { radius?: number; color?: string; rotation?: [number, number, number] }) {\n  return <mesh rotation={rotation}><torusGeometry args={[radius, 0.027, 8, 90, Math.PI * 1.4]} /><meshBasicMaterial color={color} /></mesh>;\n}\n\nfunction Studio({ dark = false, children }: { dark?: boolean; children: React.ReactNode }) {\n  return (\n    <>\n      <ambientLight intensity={dark ? 0.7 : 1.05} />\n      <hemisphereLight args={[dark ? \"#4ebfd1\" : \"#eaf7f8\", dark ? \"#081723\" : \"#7b898c\", dark ? 0.75 : 1.1]} />\n      <directionalLight castShadow position={[-7, 10, 7]} intensity={dark ? 2.5 : 2.15} color={dark ? \"#9edbea\" : \"#fff9e8\"} shadow-mapSize={[1024, 1024]} />\n      <pointLight position={[7, 3, -4]} intensity={dark ? 18 : 6} color={colors.tealBright} distance={16} />\n      {children}\n      <ContactShadows opacity={dark ? 0.5 : 0.28} scale={26} blur={2.8} far={12} color={dark ? \"#020a10\" : \"#334c57\"} />\n    </>\n  );\n}\n\nfunction Ground({ dark = false }: { dark?: boolean }) {\n  return <mesh receiveShadow rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.05, 0]}><planeGeometry args={[44, 34]} /><meshStandardMaterial color={dark ? colors.navyDeep : \"#e6eeed\"} roughness={0.92} /></mesh>;\n}\n\nfunction SceneContent({ variant, reduced, progress, quoteScale }: { variant: SceneVariant; reduced: boolean; progress: number; quoteScale: [number, number, number] }) {\n  const moving = useRef<THREE.Group>(null);\n  const secondary = useRef<THREE.Group>(null);\n  const baseProgress = reduced ? 0.42 : progress;\n  useFrame((state, delta) => {\n    if (moving.current && !reduced) {\n      moving.current.rotation.y += delta * (variant === \"international\" ? 0.11 : 0.04);\n      moving.current.position.y += Math.sin(state.clock.elapsedTime * 1.25) * 0.0008;\n    }\n    if (secondary.current && !reduced) secondary.current.rotation.z = Math.sin(state.clock.elapsedTime * 0.75) * 0.025;\n  });\n\n  if (variant === \"journey\") {\n    const loading = Math.min(1, baseProgress * 3.1);\n    const closing = Math.max(0, Math.min(1, (baseProgress - 0.3) * 4.4));\n    const travel = Math.max(0, Math.min(1, (baseProgress - 0.54) * 2.2));\n    return <Studio><Ground /><Warehouse position={[5, 0, -2.2]} scale={0.92} /><Conveyor position={[1.8, 0, 1.8]} length={4.8} />{[-0.9, 0.35, 1.5].map((x, i) => <Parcel key={x} position={[x + loading * 1.9, 1.15, 1.8]} scale={0.55} branded={i === 1} />)}<group ref={moving} position={[-0.8 + travel * 6.2, 0, 0]}><Truck scale={0.88} progress={closing + travel * 0.8} /></group><Road position={[-5, 0, 0]} length={12} /></Studio>;\n  }\n  if (variant === \"services\") return <Studio><Ground /><group position={[-3.5, 0, 0.4]}><Road length={7} /><Truck scale={0.48} position={[-1 + baseProgress * 2.2, 0, 0]} progress={baseProgress} /><LocationPin position={[2.2, 0.1, -0.7]} scale={0.65} /></group><group ref={moving} position={[3.8, 2.2, 0]}><Globe scale={0.9} /><CargoPlane position={[-1.2, 1.5, 1.3]} rotation={[0.1, -0.2, -0.2]} scale={0.5} /></group></Studio>;\n  if (variant === \"process\") return <Studio><Ground />{[-4.2, -1.4, 1.4, 4.2].map((x, i) => <group key={x} position={[x, 0, 0]}><RoundedBox args={[1.9, 0.3, 1.9]} radius={0.14} smoothness={4} position={[0, 0.12, 0]}><meshStandardMaterial color={i <= Math.round(baseProgress * 3) ? colors.teal : colors.silver} metalness={0.35} roughness={0.4} /></RoundedBox><mesh position={[0, 0.35, 0]}><torusGeometry args={[0.48, 0.025, 8, 32]} /><meshBasicMaterial color={colors.tealBright} /></mesh></group>)}<group ref={moving} position={[-4.2 + baseProgress * 8.4, 1.12, 0]} rotation={[0, baseProgress * Math.PI * 2, 0]}><Parcel branded scale={0.75} /></group><RouteArc radius={4.3} rotation={[Math.PI / 2, 0, 0]} /></Studio>;\n  if (variant === \"domestic\") {\n    const angle = -0.5 + baseProgress;\n    const position: [number, number, number] = [Math.sin(angle) * 8, 0, Math.cos(angle) * 8 - 7.45];\n    return <Studio><Ground /><CurvedRoad /><group ref={moving} position={position} rotation={[0, angle + Math.PI, 0]}><Truck scale={0.68} progress={baseProgress} /></group><CityBlock position={[-4.5, 0, -3.2]} height={2.5} /><CityBlock position={[-2.7, 0, -3.4]} height={3.8} color=\"#aec5ca\" /><CityBlock position={[2.9, 0, -3.3]} height={2.9} /><CityBlock position={[4.8, 0, -3.2]} height={4.1} color=\"#abc2c8\" /><Warehouse position={[7.6, 0, -2.8]} scale={0.55} /><LocationPin position={[5.5, 0.1, 1.45]} scale={0.58} /></Studio>;\n  }\n  if (variant === \"international\") return <Studio dark><Ground dark /><group ref={moving} position={[-1.4, 2.25, 0]}><Globe scale={1.42} /></group><group ref={secondary} position={[2.6 + Math.cos(baseProgress * Math.PI) * 1.4, 3.6 + Math.sin(baseProgress * Math.PI) * 0.9, 1.2]}><CargoPlane scale={0.8} rotation={[0.08, -0.35, -0.16]} /></group><RouteArc radius={3.2} rotation={[1.2, 0.3, -0.6]} /><Parcel position={[4.8, 0.55, 0]} scale={0.8} branded /></Studio>;\n  if (variant === \"quote\") return <Studio><Ground /><group ref={moving} position={[0, 1.35, 0]} rotation={[0.06, baseProgress * 0.45, 0]}><Parcel branded scale={quoteScale} /></group><RouteArc radius={2.8} rotation={[Math.PI / 2, 0, 0.15]} /><LocationPin position={[-3, 0.15, 0.4]} scale={0.8} /><LocationPin position={[3, 0.15, -0.4]} scale={0.8} /></Studio>;\n  if (variant === \"about\") return <Studio><Ground /><Warehouse position={[2.8, 0, -1.4]} scale={0.78} /><group ref={moving} position={[-3.2, 2.1, 0]}><Globe scale={0.85} /></group>{[[-2.2, 0.5, 1.4], [-0.8, 0.65, 1.1], [0.6, 0.5, 1.3]].map((p, i) => <Parcel key={i} position={p as [number, number, number]} scale={0.62} branded={i === 1} />)}<RouteArc radius={3.6} rotation={[Math.PI / 2, 0, -0.2]} /></Studio>;\n  if (variant === \"contact\") return <Studio><Ground /><Float speed={reduced ? 0 : 1.2} floatIntensity={0.18}><LocationPin position={[0, 1.6, 0]} scale={1.25} /></Float><Parcel position={[-2.2, 0.6, 0.5]} scale={0.8} branded /><Parcel position={[2.1, 0.52, -0.4]} scale={0.68} /><RouteArc radius={2.9} rotation={[Math.PI / 2, 0, 0.35]} /></Studio>;\n  if (variant === \"faq\") return <Studio><Ground />{[-1.35, 0, 1.35].map((y, i) => <group key={y} position={[i * 0.48 - 0.48, y * 0.58 + 1, -i * 0.12]} rotation={[0, -0.18 + i * 0.12, -0.05 + i * 0.03]}><Parcel branded={i === 1} scale={[2.4, 0.55, 1.25]} /></group>)}</Studio>;\n  if (variant === \"legal\") return <Studio><Ground /><Parcel position={[-1.2, 0.8, 0]} scale={[1.35, 1.2, 1.35]} branded /><group position={[1.25, 1.28, 0]} rotation={[0, -0.2, -0.08]}><RoundedBox args={[2.2, 2.8, 0.12]} radius={0.09} smoothness={4}><meshStandardMaterial color={colors.paper} roughness={0.7} /></RoundedBox>{[-0.65, -0.2, 0.25, 0.7].map((y) => <mesh key={y} position={[0, y, 0.07]}><planeGeometry args={[1.5, 0.05]} /><meshBasicMaterial color={colors.teal} /></mesh>)}</group></Studio>;\n  if (variant === \"footer\") return <Studio dark><Ground dark /><Warehouse position={[4.1, 0, -1.8]} scale={0.52} /><Road position={[-2.5, 0, 0]} length={11} /><group ref={moving} position={[-1.5 + baseProgress * 1.7, 0, 0]}><Truck scale={0.49} progress={1} /></group></Studio>;\n  return <Studio dark><Ground dark /><Warehouse position={[2.65, 0, -2.2]} scale={0.9} /><Parcel position={[-1.9, 0.82, 1.15]} scale={1.12} branded /><Conveyor position={[-0.2, 0, 1.75]} length={4.8} /><Truck position={[-2.3, 0, -1.25]} scale={0.46} progress={0.8} /></Studio>;\n}\n\nfunction CameraRig({ variant, reduced, progress }: { variant: SceneVariant; reduced: boolean; progress: number }) {\n  const { camera, pointer } = useThree();\n  useFrame(() => {\n    const mobile = window.innerWidth < 700;\n    const darkScene = variant === \"international\" || variant === \"footer\" || variant === \"admin\";\n    const targetX = mobile ? 0 : (darkScene ? 0.5 : -0.5) + (reduced ? 0 : pointer.x * 0.28);\n    const targetY = mobile ? 4.8 : 4.5 + (reduced ? 0 : pointer.y * 0.16);\n    const closeScene = [\"quote\", \"contact\", \"faq\", \"legal\", \"admin\"].includes(variant);\n    const targetZ = mobile ? (closeScene ? 11.8 : 14.4) : variant === \"footer\" ? 14 : closeScene ? 10.2 : 13.2 - progress * (reduced ? 0 : 0.35);\n    camera.position.lerp(new THREE.Vector3(targetX, targetY, targetZ), reduced ? 1 : 0.045);\n    camera.lookAt(variant === \"journey\" ? 1.15 : 0, 1.1, 0);\n  });\n  return null;\n}\n\nfunction World({ variant, reduced, progress }: { variant: SceneVariant; reduced: boolean; progress: number }) {\n  const [quoteScale, setQuoteScale] = useState<[number, number, number]>([1.4, 1.2, 1.25]);\n  useEffect(() => {\n    const onQuote = (event: Event) => {\n      const detail = (event as CustomEvent<{ dimensions?: [number, number, number]; success?: boolean }>).detail;\n      if (detail?.dimensions) setQuoteScale(detail.dimensions);\n      if (detail?.success) setQuoteScale([1.15, 1.15, 1.15]);\n    };\n    window.addEventListener(\"vk:quote-visual\", onQuote);\n    return () => {\n      window.removeEventListener(\"vk:quote-visual\", onQuote);\n    };\n  }, []);\n  return <><CameraRig variant={variant} reduced={reduced} progress={progress} /><SceneContent variant={variant} reduced={reduced} progress={progress} quoteScale={quoteScale} /></>;\n}\n\nexport default function CourierCanvas({ variant, reduced, active, progress }: { variant: SceneVariant; reduced: boolean; active: boolean; progress: number }) {\n  return (\n    <Canvas\n      shadows\n      frameloop={active && !reduced ? \"always\" : \"demand\"}\n      dpr={[1, 1.5]}\n      camera={{ position: [0, 4.5, 13.2], fov: 39, near: 0.1, far: 80 }}\n      gl={{ antialias: true, alpha: true, powerPreference: \"high-performance\" }}\n      fallback={<div className={`scene-fallback scene-fallback-${variant}`} role=\"img\" aria-label={`${variant} courier illustration`} />}\n      onCreated={({ gl }) => {\n        gl.outputColorSpace = THREE.SRGBColorSpace;\n        gl.toneMapping = THREE.ACESFilmicToneMapping;\n        gl.toneMappingExposure = 1.08;\n        const canvas = gl.domElement;\n        const lost = (event: Event) => { event.preventDefault(); window.dispatchEvent(new Event(\"vk:webgl-failed\")); };\n        const restored = () => window.dispatchEvent(new Event(\"vk:webgl-restored\"));\n        canvas.addEventListener(\"webglcontextlost\", lost, false);\n        canvas.addEventListener(\"webglcontextrestored\", restored, false);\n      }}\n    >\n      <Suspense fallback={null}><World variant={variant} reduced={reduced} progress={progress} /></Suspense>\n    </Canvas>\n  );\n}\n",
    "components/three/delivery-canvas.tsx": "\"use client\";\n\nimport { Canvas, useFrame, useThree } from \"@react-three/fiber\";\nimport { ContactShadows, RoundedBox } from \"@react-three/drei\";\nimport { Suspense, useEffect, useRef } from \"react\";\nimport * as THREE from \"three\";\nimport { BrandPlaque, Parcel, Truck } from \"./courier-canvas\";\n\nconst clamp = (value: number) => Math.max(0, Math.min(1, value));\nconst smooth = (value: number) => { const x = clamp(value); return x * x * (3 - 2 * x); };\nconst mix = (from: number, to: number, amount: number) => from + (to - from) * amount;\n\nfunction FixedCamera() {\n  const { camera } = useThree();\n  useEffect(() => {\n    const mobile = window.innerWidth < 700;\n    camera.position.set(mobile ? 7.7 : 8.4, mobile ? 4.2 : 4.7, mobile ? 13.8 : 13);\n    camera.lookAt(mobile ? -0.6 : 0, 1, 0);\n  }, [camera]);\n  return null;\n}\n\nfunction DeliveryPoint() {\n  return <group position={[-3.6, 0, -2.1]}>\n    <RoundedBox args={[3.1, 3.4, 2.5]} radius={0.12} smoothness={4} position={[0, 1.7, 0]} castShadow><meshStandardMaterial color=\"#d9e0df\" roughness={0.72}/></RoundedBox>\n    <RoundedBox args={[1.3, 2.2, 0.13]} radius={0.05} smoothness={3} position={[0, 1.1, 1.27]}><meshStandardMaterial color=\"#173952\" metalness={0.22} roughness={0.42}/></RoundedBox>\n    <mesh position={[0, 2.55, 1.38]}><boxGeometry args={[1.8, 0.18, 0.55]}/><meshStandardMaterial color=\"#13839a\" metalness={0.3}/></mesh>\n    <BrandPlaque position={[0, 2.85, 1.31]} scale={0.42}/>\n    <mesh position={[1.1, 0.12, 1.7]} receiveShadow><boxGeometry args={[1.8, 0.22, 1.45]}/><meshStandardMaterial color=\"#92a1a5\" roughness={0.8}/></mesh>\n  </group>;\n}\n\nfunction DeliveryWorld({ playing, reduced, runId, onComplete }: { playing: boolean; reduced: boolean; runId: number; onComplete: () => void }) {\n  const truck = useRef<THREE.Group>(null);\n  const parcel = useRef<THREE.Group>(null);\n  const elapsed = useRef(reduced ? 7 : 0);\n  const completed = useRef(false);\n\n  const renderPose = (time: number) => {\n    if (!truck.current || !parcel.current) return;\n    const arrival = smooth(time / 1.8);\n    const departure = smooth((time - 4.9) / 1.7);\n    const truckX = time < 4.9 ? mix(-8.3, 1.2, arrival) : mix(1.2, 9.4, departure);\n    truck.current.position.x = truckX;\n    const wheelSpin = -(arrival * 9.5 + departure * 8.2) * 2.35;\n    truck.current.getObjectsByProperty(\"name\", \"truck-wheel\").forEach((wheel) => { wheel.rotation.y = wheelSpin; });\n    const open = smooth((time - 2.15) / 0.65) * (1 - smooth((time - 4.2) / 0.65));\n    truck.current.getObjectsByProperty(\"name\", \"rear-door\").forEach((door) => { door.rotation.y = Number(door.userData.side) * open * 1.05; });\n    const unloading = smooth((time - 2.9) / 1.25);\n    parcel.current.visible = time >= 2.7;\n    parcel.current.position.set(mix(-1.25, -2.95, unloading), mix(1.32, 0.62, unloading) + Math.sin(unloading * Math.PI) * 0.42, mix(0.45, 1.15, unloading));\n    parcel.current.rotation.y = unloading * Math.PI * 0.22;\n  };\n\n  useEffect(() => {\n    elapsed.current = reduced ? 7 : 0;\n    completed.current = false;\n    renderPose(elapsed.current);\n    // runId is the explicit replay reset signal.\n  }, [runId, reduced]);\n\n  useFrame((_, delta) => {\n    if (playing && !reduced && elapsed.current < 7) elapsed.current = Math.min(7, elapsed.current + Math.min(delta, 0.05));\n    renderPose(elapsed.current);\n    if (elapsed.current >= 7 && !completed.current) { completed.current = true; onComplete(); }\n  });\n\n  return <>\n    <FixedCamera/>\n    <fog attach=\"fog\" args={[\"#102b3e\", 15, 30]}/>\n    <ambientLight intensity={0.42}/>\n    <hemisphereLight args={[\"#9cc8d0\", \"#071722\", 0.75]}/>\n    <directionalLight castShadow position={[-5, 9, 7]} intensity={2.5} color=\"#f2f3ed\" shadow-mapSize={[1024,1024]}/>\n    <pointLight position={[5, 3, 3]} intensity={14} distance={15} color=\"#3da7b9\"/>\n    <mesh receiveShadow rotation={[-Math.PI/2,0,0]}><planeGeometry args={[45,25]}/><meshStandardMaterial color=\"#263c47\" roughness={0.94}/></mesh>\n    <mesh receiveShadow rotation={[-Math.PI/2,0,0]} position={[0,0.025,0]}><planeGeometry args={[40,5.4]}/><meshStandardMaterial color=\"#354a54\" roughness={0.9}/></mesh>\n    {[-9,-4,1,6,11].map((x)=><mesh key={x} rotation={[-Math.PI/2,0,0]} position={[x,0.04,0]}><planeGeometry args={[2.2,0.08]}/><meshBasicMaterial color=\"#d8dfdd\"/></mesh>)}\n    <DeliveryPoint/>\n    <mesh position={[-1.65,0.34,0.85]} rotation={[0,0,-0.23]} castShadow><boxGeometry args={[2.5,0.13,1.15]}/><meshStandardMaterial color=\"#819299\" metalness={0.55} roughness={0.36}/></mesh>\n    <group ref={truck} position={[-8.3,0,0.1]} rotation={[0,Math.PI,0]}><Truck scale={0.83} progress={1}/></group>\n    <group ref={parcel}><Parcel branded scale={0.64}/></group>\n    <ContactShadows position={[0,0.05,0]} opacity={0.55} scale={25} blur={2.7} far={10} color=\"#020b11\"/>\n  </>;\n}\n\nexport default function DeliveryCanvas({ playing, reduced, runId, onComplete }: { playing: boolean; reduced: boolean; runId: number; onComplete: () => void }) {\n  return <Canvas shadows frameloop={playing && !reduced ? \"always\" : \"demand\"} dpr={[1,1.5]} camera={{position:[8.4,4.7,13],fov:38,near:.1,far:60}} gl={{antialias:true,alpha:true,powerPreference:\"high-performance\"}}>\n    <Suspense fallback={null}><DeliveryWorld playing={playing} reduced={reduced} runId={runId} onComplete={onComplete}/></Suspense>\n  </Canvas>;\n}\n",
    "components/three/dispatch-canvas.tsx": "\"use client\";\n\nimport { Canvas, useFrame, useThree } from \"@react-three/fiber\";\nimport { ContactShadows } from \"@react-three/drei\";\nimport { gsap } from \"gsap\";\nimport { ScrollTrigger } from \"gsap/ScrollTrigger\";\nimport { useEffect, useMemo, useRef } from \"react\";\nimport * as THREE from \"three\";\n\nfunction BrandPanel() {\n  const texture = useMemo(() => {\n    const canvas = document.createElement(\"canvas\");\n    canvas.width = 768; canvas.height = 180;\n    const context = canvas.getContext(\"2d\")!;\n    context.fillStyle = \"#f6f5f1\"; context.fillRect(0, 0, canvas.width, canvas.height);\n    context.fillStyle = \"#203a55\"; context.font = \"800 52px Arial\"; context.textAlign = \"center\"; context.textBaseline = \"middle\";\n    context.fillText(\"VK AND COMPANY\", canvas.width / 2, canvas.height / 2);\n    const created = new THREE.CanvasTexture(canvas);\n    created.colorSpace = THREE.SRGBColorSpace;\n    return created;\n  }, []);\n  useEffect(() => () => texture.dispose(), [texture]);\n  return <mesh position={[0, 1.15, 1.511]}><planeGeometry args={[3.7, .86]} /><meshBasicMaterial map={texture} /></mesh>;\n}\n\nfunction Wheel({ position }: { position: [number, number, number] }) {\n  return <group position={position} rotation={[Math.PI / 2, 0, 0]} name=\"wheel\"><mesh castShadow><cylinderGeometry args={[.44, .44, .28, 24]} /><meshStandardMaterial color=\"#17232a\" roughness={.7} /></mesh><mesh position={[0,.15,0]}><cylinderGeometry args={[.18,.18,.3,16]} /><meshStandardMaterial color=\"#8aa0a9\" metalness={.6} /></mesh></group>;\n}\n\nfunction Truck({ truckRef, leftDoorRef, rightDoorRef }: { truckRef: React.RefObject<THREE.Group | null>; leftDoorRef: React.RefObject<THREE.Group | null>; rightDoorRef: React.RefObject<THREE.Group | null> }) {\n  return <group ref={truckRef} position={[1.2, .45, 0]}>\n    <mesh castShadow position={[.4,1.2,0]}><boxGeometry args={[4.2,2.45,3]} /><meshStandardMaterial color=\"#203a55\" roughness={.42} /></mesh>\n    <BrandPanel />\n    <mesh castShadow position={[-2.15,.95,0]}><boxGeometry args={[1.25,1.95,2.82]} /><meshStandardMaterial color=\"#227d91\" roughness={.38} /></mesh>\n    <mesh castShadow position={[-2.34,1.68,0]} rotation={[0,0,-.08]}><boxGeometry args={[.82,.75,2.84]} /><meshStandardMaterial color=\"#227d91\" /></mesh>\n    <mesh position={[-2.77,1.72,.83]} rotation={[0,-Math.PI/2,0]}><planeGeometry args={[.9,.52]} /><meshStandardMaterial color=\"#9cc8d2\" metalness={.25} roughness={.2} /></mesh>\n    <mesh position={[-2.18,1.73,1.421]}><planeGeometry args={[.62,.52]} /><meshStandardMaterial color=\"#acd4dc\" metalness={.2} /></mesh>\n    <mesh position={[-2.79,.92,1.1]}><boxGeometry args={[.05,.22,.42]} /><meshStandardMaterial color=\"#f5dd9e\" emissive=\"#d6aa45\" emissiveIntensity={.4} /></mesh>\n    <mesh position={[-2.79,.72,-1.1]}><boxGeometry args={[.05,.18,.38]} /><meshStandardMaterial color=\"#d95c52\" /></mesh>\n    <Wheel position={[-2.05,.1,1.48]} /><Wheel position={[-2.05,.1,-1.48]} /><Wheel position={[1.45,.1,1.48]} /><Wheel position={[1.45,.1,-1.48]} />\n    <group position={[2.51,1.2,0]}>\n      <group ref={leftDoorRef} position={[0,0,1.48]}><mesh castShadow position={[0,0,-.72]}><boxGeometry args={[.09,2.3,1.42]} /><meshStandardMaterial color=\"#2f5f78\" /></mesh></group>\n      <group ref={rightDoorRef} position={[0,0,-1.48]}><mesh castShadow position={[0,0,.72]}><boxGeometry args={[.09,2.3,1.42]} /><meshStandardMaterial color=\"#2f5f78\" /></mesh></group>\n    </group>\n  </group>;\n}\n\nfunction Parcel({ position, parcelRef }: { position: [number,number,number]; parcelRef: (node: THREE.Mesh | null) => void }) {\n  return <mesh ref={parcelRef} castShadow position={position}><boxGeometry args={[.55,.5,.55]} /><meshStandardMaterial color=\"#b88a58\" roughness={.78} /><mesh position={[0,.251,0]} rotation={[-Math.PI/2,0,0]}><planeGeometry args={[.13,.55]} /><meshBasicMaterial color=\"#e8cf9c\" /></mesh></mesh>;\n}\n\nfunction Warehouse() {\n  return <group position={[4.8,0,-1.2]}>\n    <mesh castShadow position={[1,2.2,-1.6]}><boxGeometry args={[4.8,4.4,3.2]} /><meshStandardMaterial color=\"#d6e0e3\" roughness={.82} /></mesh>\n    <mesh position={[-1.41,1.45,-.2]}><boxGeometry args={[.1,2.9,2.35]} /><meshStandardMaterial color=\"#35576a\" /></mesh>\n    <mesh position={[-1.48,.35,0]}><boxGeometry args={[1.8,.45,2.2]} /><meshStandardMaterial color=\"#8fa1aa\" /></mesh>\n    <mesh position={[-2.4,.63,0]}><boxGeometry args={[2.3,.12,1.05]} /><meshStandardMaterial color=\"#6f858e\" metalness={.3} /></mesh>\n    {[-3.15,-2.65,-2.15,-1.65].map((x) => <mesh key={x} position={[x,.56,0]} rotation={[0,0,Math.PI/2]}><cylinderGeometry args={[.11,.11,1,12]} /><meshStandardMaterial color=\"#b9c6ca\" metalness={.5} /></mesh>)}\n  </group>;\n}\n\nfunction World({ reduced }: { reduced: boolean }) {\n  const truck = useRef<THREE.Group>(null);\n  const leftDoor = useRef<THREE.Group>(null);\n  const rightDoor = useRef<THREE.Group>(null);\n  const domestic = useRef<THREE.Group>(null);\n  const international = useRef<THREE.Group>(null);\n  const parcels = useRef<THREE.Mesh[]>([]);\n  const { invalidate } = useThree();\n\n  useEffect(() => {\n    gsap.registerPlugin(ScrollTrigger);\n    if (!truck.current || !leftDoor.current || !rightDoor.current || reduced) {\n      invalidate(); return;\n    }\n    const wheels = truck.current.getObjectsByProperty(\"name\", \"wheel\") as THREE.Object3D[];\n    const context = gsap.context(() => {\n      const timeline = gsap.timeline({\n        defaults: { ease: \"none\" },\n        scrollTrigger: { trigger: \"#dispatch-hero\", start: \"top top\", end: \"bottom top\", scrub: .35, invalidateOnRefresh: true },\n        onUpdate: invalidate,\n      });\n      parcels.current.forEach((parcel, index) => timeline.to(parcel.position, { x: 2.5, y: 1.2, z: (index - 1) * .6, duration: .16 }, index * .055));\n      timeline.to(leftDoor.current!.rotation, { y: -Math.PI / 2, duration: .12 }, .24)\n        .to(rightDoor.current!.rotation, { y: Math.PI / 2, duration: .12 }, .24)\n        .to(truck.current!.position, { x: -9.5, duration: .45 }, .4)\n        .to(wheels.map((wheel) => wheel.rotation), { z: -Math.PI * 8, duration: .45 }, .4)\n        .fromTo(domestic.current!.position, { x: 8 }, { x: -3, duration: .28 }, .48)\n        .fromTo(international.current!.position, { y: 8, x: 7 }, { y: 3.8, x: -1, duration: .25 }, .72);\n    });\n    return () => context.revert();\n  }, [invalidate, reduced]);\n\n  useFrame(() => undefined);\n  return <>\n    <color attach=\"background\" args={[\"#e8f1f2\"]} />\n    <fog attach=\"fog\" args={[\"#e8f1f2\", 17, 36]} />\n    <ambientLight intensity={1.25} /><hemisphereLight args={[\"#e7f4f5\", \"#6d7f83\", 1.1]} /><directionalLight castShadow position={[-5,10,8]} intensity={2.2} shadow-mapSize={[1024,1024]} />\n    <mesh receiveShadow rotation={[-Math.PI/2,0,0]} position={[0,0,0]}><planeGeometry args={[60,40]} /><meshStandardMaterial color=\"#dbe4e5\" /></mesh>\n    <mesh receiveShadow rotation={[-Math.PI/2,0,0]} position={[-4,.02,0]}><planeGeometry args={[35,7]} /><meshStandardMaterial color=\"#657781\" roughness={.9} /></mesh>\n    {[...Array(10)].map((_,index)=><mesh key={index} rotation={[-Math.PI/2,0,0]} position={[-16+index*4,.031,0]}><planeGeometry args={[1.6,.08]} /><meshBasicMaterial color=\"#e6ecee\" /></mesh>)}\n    <Warehouse />\n    {[[-3,.45,.1],[-2.4,.45,.1],[-1.8,.45,.1]].map((position,index)=><Parcel key={index} position={position as [number,number,number]} parcelRef={(node) => { if(node) parcels.current[index]=node; }} />)}\n    <Truck truckRef={truck} leftDoorRef={leftDoor} rightDoorRef={rightDoor} />\n    <group ref={domestic} position={[8,0,-4]}>{[-2,0,2].map((x,index)=><group key={x} position={[x,0,0]}><mesh castShadow position={[0,.7,0]}><boxGeometry args={[1.45,1.4,1.4]} /><meshStandardMaterial color={index===1?\"#eef1ee\":\"#c9d8d8\"} /></mesh><mesh castShadow position={[0,1.65,0]} rotation={[0,Math.PI/4,0]}><coneGeometry args={[1.25,.9,4]} /><meshStandardMaterial color=\"#45677a\" /></mesh></group>)}</group>\n    <group ref={international} position={[7,8,-7]} rotation={[0,-.25,.08]}><mesh><boxGeometry args={[3.3,.5,.55]} /><meshStandardMaterial color=\"#f4f2ea\" /></mesh><mesh position={[.1,.1,0]}><boxGeometry args={[.8,.8,.7]} /><meshStandardMaterial color=\"#f4f2ea\" /></mesh><mesh position={[0,0,0]}><boxGeometry args={[.65,.12,4.5]} /><meshStandardMaterial color=\"#227d91\" /></mesh></group>\n    <ContactShadows opacity={.3} scale={35} blur={2.8} far={10} />\n  </>;\n}\n\nexport default function DispatchCanvas({ reduced }: { reduced: boolean }) {\n  return <Canvas shadows frameloop=\"demand\" dpr={[1,1.5]} camera={{ position: [-7,6,11], fov: 39 }} gl={{ antialias: true, powerPreference: \"high-performance\" }} fallback={<div className=\"scene-fallback\"><StaticDispatchArt /></div>}>\n    <World reduced={reduced} />\n  </Canvas>;\n}\n\nexport function StaticDispatchArt() { return <div className=\"fallback-art\" role=\"img\" aria-label=\"Illustration of a delivery truck leaving a parcel dispatch centre\"><div className=\"fallback-truck\" /></div>; }\n",
    "components/three/dispatch-experience.tsx": "\"use client\";\n\nimport dynamic from \"next/dynamic\";\nimport { Pause, Play } from \"lucide-react\";\nimport { Component, type ReactNode, useEffect, useRef, useState } from \"react\";\nimport { StaticDispatchArt } from \"./dispatch-canvas\";\n\nconst DispatchCanvas = dynamic(() => import(\"./dispatch-canvas\"), { ssr: false, loading: () => <div className=\"scene-fallback\"><StaticDispatchArt /></div> });\n\nclass SceneErrorBoundary extends Component<{ children: ReactNode }, { failed: boolean }> {\n  state = { failed: false };\n  static getDerivedStateFromError() { return { failed: true }; }\n  render() { return this.state.failed ? <div className=\"scene-fallback\"><StaticDispatchArt /></div> : this.props.children; }\n}\n\nexport function DispatchExperience() {\n  const host = useRef<HTMLDivElement>(null);\n  const [visible, setVisible] = useState(false);\n  const [systemReduced, setSystemReduced] = useState(false);\n  const [paused, setPaused] = useState(false);\n  useEffect(() => {\n    const query = matchMedia(\"(prefers-reduced-motion: reduce)\");\n    const update = () => setSystemReduced(query.matches);\n    update(); query.addEventListener(\"change\", update);\n    const observer = new IntersectionObserver(([entry]) => setVisible(entry.isIntersecting), { rootMargin: \"150px\" });\n    if (host.current) observer.observe(host.current);\n    return () => { query.removeEventListener(\"change\", update); observer.disconnect(); };\n  }, []);\n  const reduced = systemReduced || paused;\n  return <div ref={host} className=\"scene-wrap\" aria-label=\"Animated parcel dispatch illustration\">\n    <div className=\"scene-controls\"><button type=\"button\" className=\"motion-toggle\" onClick={() => setPaused((value) => !value)} aria-pressed={reduced} aria-label={reduced ? \"Enable motion\" : \"Reduce motion\"}>{reduced ? <Play size={15}/> : <Pause size={15}/>}<span aria-hidden=\"true\">{reduced ? \"Enable motion\" : \"Reduce motion\"}</span></button></div>\n    <SceneErrorBoundary>{visible ? <DispatchCanvas reduced={reduced} /> : <div className=\"scene-fallback\"><StaticDispatchArt /></div>}</SceneErrorBoundary>\n  </div>;\n}\n",
    "components/three/quote-bubbles.ts": "import * as THREE from \"three\";\nimport { MEDIA_INTERACTION, type MediaInteraction } from \"@/lib/media-interaction\";\n\n// One lazy, bounded perspective scene. No perpetual render loop or global input.\nexport function createQuoteBubbles(host: HTMLElement, onFailure: () => void) {\n  const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true, powerPreference: \"low-power\" });\n  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));\n  renderer.setClearColor(0x000000, 0);\n  renderer.domElement.className = \"quote-bubble-canvas\";\n  renderer.domElement.setAttribute(\"aria-hidden\", \"true\");\n  host.append(renderer.domElement);\n  const scene = new THREE.Scene();\n  const camera = new THREE.PerspectiveCamera(36, 1, .1, 30);\n  camera.position.z = 7;\n  scene.add(new THREE.AmbientLight(0xd6f6f4, 2));\n  const key = new THREE.DirectionalLight(0xffffff, 5); key.position.set(-3, 4, 5); scene.add(key);\n  const fill = new THREE.PointLight(0x71ded8, 35); fill.position.set(3, -2, 4); scene.add(fill);\n  const rim = new THREE.PointLight(0xffffff, 45); rim.position.set(-2, 3, 2); scene.add(rim);\n  const geometry = new THREE.SphereGeometry(1, 40, 28);\n  const materials = [0x62b8b4, 0xd4e3e6].map(color => new THREE.MeshPhysicalMaterial({ color, transparent: true, opacity: .63, metalness: .38, roughness: .17, clearcoat: 1, clearcoatRoughness: .08, depthWrite: false }));\n  const anchors = [[-.84,.53,.18,.29],[.84,.62,-.1,.22],[-.82,-.66,-.15,.17],[.83,-.57,.24,.32]];\n  const spheres = anchors.map(([, , , radius], i) => { const mesh = new THREE.Mesh(geometry, materials[i % 2]); mesh.scale.setScalar(radius); scene.add(mesh); return mesh; });\n  let active = false, disposed = false, broken = false, raf = 0, last = 0, tap = -Infinity, frames = 0;\n  let width = 1, height = 1;\n  const pointer = new THREE.Vector2(), current = new THREE.Vector2();\n  function request() { if (active && !disposed && !broken && !raf) raf = requestAnimationFrame(render); }\n  function render(now: number) {\n    raf = 0;\n    if (!active || disposed || broken) return;\n    const dt = Math.min((now - last) / 1000 || .016, .04); last = now;\n    current.lerp(pointer, 1 - Math.exp(-dt * 13));\n    const elapsed = now - tap;\n    const burst = elapsed < 640 ? Math.sin(elapsed / 640 * Math.PI) * Math.exp(-elapsed / 500) : 0;\n    const viewHeight = 2 * Math.tan(THREE.MathUtils.degToRad(18)) * 7;\n    spheres.forEach((mesh, i) => {\n      const [x,y,z] = anchors[i];\n      mesh.position.set(x * viewHeight * width / height / 2 + current.x * .10 + Math.sign(x) * burst * .18,\n        y * viewHeight / 2 - current.y * .10 + Math.sign(y) * burst * .18, z + burst * .1);\n    });\n    try { renderer.render(scene, camera); host.dataset.bubbles = \"webgl\"; renderer.domElement.dataset.frames = String(++frames); }\n    catch { fail(); return; }\n    if (current.distanceTo(pointer) > .001 || elapsed < 640) request();\n  }\n  function resize() {\n    width = host.clientWidth; height = host.clientHeight;\n    if (!width || !height) return;\n    renderer.setSize(width, height, false); camera.aspect = width / height; camera.updateProjectionMatrix(); request();\n  }\n  function interaction(event: Event) {\n    if (!active) return;\n    const { kind, x, y } = (event as CustomEvent<MediaInteraction>).detail;\n    if (kind === \"tap\") { tap = performance.now(); pointer.set(0,0); }\n    else pointer.set(kind === \"leave\" ? 0 : x, kind === \"leave\" ? 0 : y);\n    request();\n  }\n  function fail() { broken = true; cancelAnimationFrame(raf); raf = 0; renderer.domElement.style.display = \"none\"; onFailure(); }\n  const observer = new ResizeObserver(resize); observer.observe(host);\n  host.addEventListener(MEDIA_INTERACTION, interaction);\n  renderer.domElement.addEventListener(\"webglcontextlost\", fail);\n  resize();\n  return {\n    setActive(value: boolean) {\n      active = value;\n      if (active) { last = performance.now(); request(); }\n      else { cancelAnimationFrame(raf); raf = 0; pointer.set(0,0); current.set(0,0); tap = -Infinity; }\n    },\n    dispose() {\n      disposed = true; cancelAnimationFrame(raf); observer.disconnect();\n      host.removeEventListener(MEDIA_INTERACTION, interaction); renderer.domElement.removeEventListener(\"webglcontextlost\", fail);\n      geometry.dispose(); materials.forEach(material => material.dispose()); renderer.dispose(); renderer.domElement.remove();\n    },\n  };\n}\n",
    "components/three/scene-stage.tsx": "\"use client\";\n\nimport dynamic from \"next/dynamic\";\nimport { Component, type ReactNode, useEffect, useRef, useState } from \"react\";\nimport { MOTION_EVENT, MOTION_KEY } from \"@/components/motion-control\";\nimport type { SceneVariant } from \"./scene-types\";\n\nconst CourierCanvas = dynamic(() => import(\"./courier-canvas\"), {\n  ssr: false,\n  loading: () => <SceneFallback variant=\"journey\" />,\n});\n\nclass SceneErrorBoundary extends Component<{ children: ReactNode; fallback: ReactNode }, { failed: boolean }> {\n  state = { failed: false };\n  static getDerivedStateFromError() { return { failed: true }; }\n  render() { return this.state.failed ? this.props.fallback : this.props.children; }\n}\n\nexport function SceneFallback({ variant }: { variant: SceneVariant }) {\n  return (\n    <div className={`scene-fallback scene-fallback-${variant}`} role=\"img\" aria-label={`${variant} courier illustration`}>\n      <span className=\"fallback-route\" />\n      <span className=\"fallback-box\" />\n      <span className=\"fallback-vehicle\" />\n    </div>\n  );\n}\n\nexport function SceneStage({ variant, className = \"\", label, compact = false }: { variant: SceneVariant; className?: string; label?: string; compact?: boolean }) {\n  const host = useRef<HTMLDivElement>(null);\n  const [visible, setVisible] = useState(false);\n  const [reduced, setReduced] = useState(false);\n  const [progress, setProgress] = useState(0);\n  const [failed, setFailed] = useState(false);\n\n  useEffect(() => {\n    const query = window.matchMedia(\"(prefers-reduced-motion: reduce)\");\n    let userPaused = window.localStorage.getItem(MOTION_KEY) === \"true\";\n    const update = () => setReduced(query.matches || userPaused);\n    const onPreference = (event: Event) => {\n      userPaused = Boolean((event as CustomEvent<{ paused: boolean }>).detail?.paused);\n      update();\n    };\n    let recoveryTimer = 0;\n    const onFailure = () => {\n      setFailed(true);\n      window.clearTimeout(recoveryTimer);\n      recoveryTimer = window.setTimeout(() => setFailed(false), 1400);\n    };\n    update();\n    query.addEventListener(\"change\", update);\n    window.addEventListener(MOTION_EVENT, onPreference);\n    window.addEventListener(\"vk:webgl-failed\", onFailure);\n    return () => {\n      query.removeEventListener(\"change\", update);\n      window.removeEventListener(MOTION_EVENT, onPreference);\n      window.removeEventListener(\"vk:webgl-failed\", onFailure);\n      window.clearTimeout(recoveryTimer);\n    };\n  }, []);\n\n  useEffect(() => {\n    const element = host.current;\n    if (!element) return;\n    const observer = new IntersectionObserver(([entry]) => setVisible(entry.isIntersecting), { rootMargin: \"180px\" });\n    observer.observe(element);\n    let raf = 0;\n    const updateProgress = () => {\n      cancelAnimationFrame(raf);\n      raf = requestAnimationFrame(() => {\n        const rect = element.getBoundingClientRect();\n        const travel = rect.height + window.innerHeight * 0.3;\n        setProgress(Math.max(0, Math.min(1, (-rect.top + 100) / travel)));\n      });\n    };\n    updateProgress();\n    window.addEventListener(\"scroll\", updateProgress, { passive: true });\n    window.addEventListener(\"resize\", updateProgress);\n    return () => {\n      observer.disconnect();\n      cancelAnimationFrame(raf);\n      window.removeEventListener(\"scroll\", updateProgress);\n      window.removeEventListener(\"resize\", updateProgress);\n    };\n  }, []);\n\n  const fallback = <SceneFallback variant={variant} />;\n  return (\n    <div ref={host} className={`scene-stage ${compact ? \"scene-stage-compact\" : \"\"} ${className}`} aria-label={label || `${variant} logistics scene`}>\n      <div className=\"scene-horizon\" aria-hidden=\"true\" />\n      <SceneErrorBoundary fallback={fallback}>\n        {visible && !failed ? <CourierCanvas variant={variant} reduced={reduced} active={visible} progress={progress} /> : fallback}\n      </SceneErrorBoundary>\n      <div className=\"scene-caption\" aria-hidden=\"true\">Illustrative logistics environment</div>\n    </div>\n  );\n}\n",
    "components/three/scene-types.ts": "export type SceneVariant =\n  | \"journey\"\n  | \"services\"\n  | \"process\"\n  | \"domestic\"\n  | \"international\"\n  | \"quote\"\n  | \"about\"\n  | \"contact\"\n  | \"faq\"\n  | \"legal\"\n  | \"footer\"\n  | \"admin\";\n",
