"use client";

import { useRef, useState } from "react";
import { ArrowRight } from "lucide-react";
import { contactFormSchema, zodErrors } from "@/lib/schemas";

const CONTACT_ENDPOINT = "https://formsubmit.co/ajax/vkandcompanymohali@gmail.com";
const CONTACT_SUBJECT = "VK AND COMPANY — New Contact Enquiry";
const UNCONFIRMED = "We could not confirm your submission. It may have been accepted. Please check with the company before resubmitting.";

function FieldError({ name, errors }: { name: string; errors: Record<string, string> }) {
  return errors[name] ? <span className="field-error" id={`contact-${name}-error`}>{errors[name]}</span> : null;
}

export function SupportForm() {
  const submitting = useRef(false);
  const attempts = useRef<number[]>([]);
  const formRef = useRef<HTMLFormElement>(null);
  const [pending,setPending]=useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [result,setResult]=useState<{ok:boolean;message:string;reference?:string}|null>(null);
  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (submitting.current) return;
    const form = event.currentTarget;
    const parsed = contactFormSchema.safeParse(Object.fromEntries(new FormData(form)));
    if (!parsed.success) {
      const fields = zodErrors(parsed.error);
      setErrors(fields);
      setResult({ ok: false, message: fields.website || "Please check the highlighted fields." });
      const firstInvalid = Array.from(form.elements).find(element =>
        (element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement || element instanceof HTMLSelectElement)
        && element.name !== "website" && fields[element.name]);
      if (firstInvalid instanceof HTMLElement) firstInvalid.focus();
      return;
    }
    setErrors({});
    const now = Date.now();
    attempts.current = attempts.current.filter(time => time > now - 15 * 60_000);
    if (attempts.current.length >= 6) {
      setResult({ ok: false, message: "Too many attempts. Please wait 15 minutes before trying again." });
      return;
    }
    const value = parsed.data;
    // Whitelist fields: never forward customer-supplied FormSubmit settings.
    const payload = {
      name: value.name, email: value.email || "", phone: value.phone || "", message: value.message,
      subject: value.subject, shipmentReference: value.shipmentReference || "",
      _subject: CONTACT_SUBJECT, _honey: value.website,
      ...(value.email ? { _replyto: value.email } : {}),
    };
    submitting.current = true;
    attempts.current.push(now);
    setPending(true); setResult(null);
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 20_000);
    try {
      const response = await fetch(CONTACT_ENDPOINT, {
        method: "POST", headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify(payload), signal: controller.signal,
      });
      const body: unknown = await response.json();
      const success = typeof body === "object" && body !== null && "success" in body
        && (body.success === true || body.success === "true");
      if (!response.ok || !success) {
        setResult({ ok: false, message: UNCONFIRMED });
        return;
      }
      setResult({ ok: true, message: "FormSubmit accepted your enquiry for processing. This does not confirm inbox delivery." });
      formRef.current?.reset();
    } catch {
      setResult({ ok: false, message: UNCONFIRMED });
    } finally {
      clearTimeout(timeout);
      submitting.current = false; setPending(false);
    }
  }
  const fieldProps = (name: string) => ({
    "aria-invalid": Boolean(errors[name]),
    "aria-describedby": [name === "email" ? "contact-details-hint" : "", errors[name] ? `contact-${name}-error` : ""].filter(Boolean).join(" ") || undefined,
  });
  return <form className="form-panel" ref={formRef} onSubmit={submit} noValidate>
    <div className="honeypot" aria-hidden="true"><label>Website<input name="website" tabIndex={-1}/></label></div>
    <div className="form-grid">
      <div className="field"><label htmlFor="name">Name</label><input id="name" name="name" required minLength={2} maxLength={120} {...fieldProps("name")}/><FieldError name="name" errors={errors}/></div>
      <div className="field"><label htmlFor="phone">Phone</label><input id="phone" name="phone" type="tel" minLength={7} maxLength={32} {...fieldProps("phone")}/><FieldError name="phone" errors={errors}/></div>
      <div className="field field-full"><label htmlFor="email">Email</label><input id="email" name="email" type="email" maxLength={254} {...fieldProps("email")}/><small id="contact-details-hint">Provide an email or phone number so the team can respond.</small><FieldError name="email" errors={errors}/></div>
      <div className="field field-full"><label htmlFor="subject">Subject</label><select id="subject" name="subject" required defaultValue="General Enquiry" {...fieldProps("subject")}><option>General Enquiry</option><option>Quote Request</option><option>Shipment Support</option><option>Partnerships &amp; Other</option></select><FieldError name="subject" errors={errors}/></div>
      <div className="field field-full"><label htmlFor="message">Message</label><textarea id="message" name="message" placeholder="Tell us how we can help…" required minLength={10} maxLength={3000} {...fieldProps("message")}/><FieldError name="message" errors={errors}/></div>
    </div>
    {result&&<div className={`form-status ${result.ok?"":"error"}`} role="status">{result.message}{result.reference&&<><br/><strong>Reference: {result.reference}</strong></>}</div>}
    <button className="button" disabled={pending}>{pending?"Sending…":"Send message"}<ArrowRight size={18} aria-hidden="true"/></button>
  </form>;
}

components/image-feedback.tsx:
"use client";

import { useEffect } from "react";
import { queueSharedPointer } from "@/lib/motion/shared-pointer";
import { cancelFrame, frame as motionFrame } from "framer-motion";
import { usePointerEffects } from "@/components/motion/use-reduced-motion";
import { usePathname } from "next/navigation";
import { pointerRouteAllowed } from "@/lib/motion/policy";
import { MEDIA_INTERACTION, type MediaInteraction } from "@/lib/media-interaction";

const photos = '[data-image-feedback="photo"]';
const fields = "input, textarea, select, label, button, summary, [contenteditable]:not([contenteditable='false'])";

// One passive recognizer owns photo hover and tap. Native activation/scroll/zoom
// are never cancelled; the bounded Quote scene subscribes to its local events.
export function ImageFeedback() {
  const pointerEnabled = usePointerEffects();
  const pathname = usePathname();
  useEffect(() => {
    const reduced = matchMedia("(prefers-reduced-motion: reduce)");
    const pointers = new Set<number>();
    let gesture: { target: Element; id: number; x: number; y: number; at: number; valid: boolean } | null = null;
    let hovered: HTMLElement | null = null;
    let cleanup: (() => void) | undefined;
    let pending: { frame: HTMLElement; x: number; y: number } | null = null;
    const publish = (frame: HTMLElement, detail: MediaInteraction) => frame.dispatchEvent(new CustomEvent(MEDIA_INTERACTION, { bubbles: true, detail }));
    function cancel() { if (gesture) gesture.valid = false; }
    function leave() {
      cancelFrame(renderPointer); pending = null;
      if (hovered) {
        hovered.style.removeProperty("transform");
        hovered.removeAttribute("data-photo-hover");
        publish(hovered, { kind: "leave", x: 0, y: 0 });
        hovered = null;
      }
    }
    function down(event: PointerEvent) {
      pointers.add(event.pointerId);
      if (!event.isPrimary || pointers.size > 1) { cancel(); leave(); return; }
      gesture = event.button === 0 && event.target instanceof Element
        ? { target: event.target, id: event.pointerId, x: event.clientX, y: event.clientY, at: performance.now(), valid: true } : null;
    }
    function move(event: PointerEvent) {
      if (gesture?.id === event.pointerId && Math.hypot(event.clientX - gesture.x, event.clientY - gesture.y) > 8) cancel();
      if (!pointerEnabled || event.pointerType === "touch" || reduced.matches || event.buttons || !(event.target instanceof Element)) return;
      queueSharedPointer({ x: event.clientX, y: event.clientY, target: event.target });
      const frame = !event.target.closest(fields) ? event.target.closest<HTMLElement>(photos) : null;
      if (frame !== hovered) leave();
      if (!frame) return;
      hovered = frame;
      const b = frame.getBoundingClientRect();
      pending = { frame, x: Math.max(-1, Math.min(1, (event.clientX - b.left) / b.width * 2 - 1)), y: Math.max(-1, Math.min(1, (event.clientY - b.top) / b.height * 2 - 1)) };
      motionFrame.render(renderPointer);
    }
    function renderPointer() {
      if (!pending) return;
      const { frame, x, y } = pending;
      if (frame.dataset.photoMotion !== "scroll") frame.style.transform = `perspective(1000px) rotateX(${-y * 3.5}deg) rotateY(${x * 3.5}deg)`;
      frame.style.setProperty("--photo-x", `${(x + 1) * 50}%`);
      frame.style.setProperty("--photo-y", `${(y + 1) * 50}%`);
      frame.dataset.photoHover = "";
      publish(frame, { kind: "move", x, y });
      pending = null;
    }
    function out(event: PointerEvent) {
      if (!event.relatedTarget) queueSharedPointer(null);
      if (hovered && (!(event.relatedTarget instanceof Node) || !hovered.contains(event.relatedTarget))) leave();
    }
    function up(event: PointerEvent) { pointers.delete(event.pointerId); }
    function pointerCancel(event: PointerEvent) { up(event); cancel(); leave(); }
    function clear() { cleanup?.(); }
    function click(event: MouseEvent) {
      const previous = gesture; gesture = null;
      if (!pointerRouteAllowed(pathname)) return;
      if (!(event.target instanceof Element) || getSelection()?.toString() || event.target.closest(fields)) return;
      const frame = event.target.closest<HTMLElement>(photos) ?? (event.detail === 0 ? event.target.closest("a[href]")?.querySelector<HTMLElement>(photos) : null);
      if (!frame) return;
      if (event.detail !== 0 && (!previous?.valid || performance.now() - previous.at > 750 ||
        Math.hypot(event.clientX - previous.x, event.clientY - previous.y) > 8 ||
        !(event.target.contains(previous.target) || previous.target.contains(event.target)))) return;
      clear(); leave();
      // Resolve the resting box before locating the ripple, even mid-hover.
      frame.style.transition = "none";
      const b = frame.getBoundingClientRect();
      frame.style.removeProperty("transition");
      // Parallax can scale an ancestor. Map the visible point back into the
      // frame's local CSS pixels so its existing ripple remains under the tap.
      const x = event.detail === 0 ? frame.clientWidth / 2 : (event.clientX - b.left) * frame.offsetWidth / b.width - frame.clientLeft;
      const y = event.detail === 0 ? frame.clientHeight / 2 : (event.clientY - b.top) * frame.offsetHeight / b.height - frame.clientTop;
      const layer = document.createElement("i");
      layer.className = "image-feedback-layer image-feedback-ripple";
      layer.setAttribute("aria-hidden", "true");
      Object.assign(layer.style, { left: `${x}px`, top: `${y}px` });
      frame.append(layer);
      const animations: Animation[] = [];
      if (!reduced.matches) {
        // The whole clipped frame moves; the inner photograph stays edge-to-edge.
        animations.push(frame.animate([{ transform: "perspective(1000px) translateZ(0) scale(1)" },
          { transform: "perspective(1000px) translateZ(-24px) scale(.985)", offset: .22 },
          { transform: "perspective(1000px) translateZ(5px) scale(1.005)", offset: .57 },
          { transform: "perspective(1000px) translateZ(0) scale(1)" }], { duration: 640, easing: "cubic-bezier(.2,.7,.25,1)" }));
      }
      animations.push(layer.animate(reduced.matches ? [{ opacity: .95 }, { opacity: .95, offset: .7 }, { opacity: 0 }] : [
        { transform: "translate(-50%,-50%) scale(.2)", opacity: 1 },
        { transform: "translate(-50%,-50%) scale(1.2)", opacity: .9, offset: .5 },
        { transform: "translate(-50%,-50%) scale(1.8)", opacity: 0 },
      ], { duration: 640, easing: "ease-out" }));
      publish(frame, { kind: "tap", x: x / frame.clientWidth * 2 - 1, y: y / frame.clientHeight * 2 - 1 });
      const timer = window.setTimeout(clear, 680);
      cleanup = () => { cleanup = undefined; clearTimeout(timer); animations.forEach(a => a.cancel()); layer.remove(); };
    }
    function scroll() { cancel(); clear(); leave(); }
    function blur() { scroll(); pointers.clear(); queueSharedPointer(null); }
    const passive = { capture: true, passive: true };
    document.addEventListener("pointerdown", down, passive);
    document.addEventListener("pointermove", move, passive);
    document.addEventListener("pointerout", out, passive);
    document.addEventListener("pointerup", up, passive);
    document.addEventListener("pointercancel", pointerCancel, passive);
    document.addEventListener("click", click, passive);
    document.addEventListener("dragstart", cancel, passive);
    document.addEventListener("scroll", scroll, passive);
    window.addEventListener("blur", blur);
    reduced.addEventListener("change", blur);
    return () => {
      document.removeEventListener("pointerdown", down, true);
      document.removeEventListener("pointermove", move, true);
      document.removeEventListener("pointerout", out, true);
      document.removeEventListener("pointerup", up, true);
      document.removeEventListener("pointercancel", pointerCancel, true);
      document.removeEventListener("click", click, true);
      document.removeEventListener("dragstart", cancel, true);
      document.removeEventListener("scroll", scroll, true);
      window.removeEventListener("blur", blur);
      reduced.removeEventListener("change", blur);
      blur();
    };
  }, [pointerEnabled, pathname]);
  return null;
}

components/motion-control.tsx:
"use client";

import { Pause, Play } from "lucide-react";
import { useEffect, useState } from "react";

export const MOTION_KEY = "vk-motion-paused";
export const MOTION_EVENT = "vk:motion-preference";

export function MotionControl() {
  const [paused, setPaused] = useState(false);
  const [systemReduced, setSystemReduced] = useState(false);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const updateSystem = () => setSystemReduced(query.matches);
    const frame = requestAnimationFrame(() => {
      updateSystem();
      setPaused(window.localStorage.getItem(MOTION_KEY) === "true");
    });
    query.addEventListener("change", updateSystem);
    return () => { cancelAnimationFrame(frame); query.removeEventListener("change", updateSystem); };
  }, []);

  const reduced = paused || systemReduced;
  function toggle() {
    const next = !paused;
    setPaused(next);
    window.localStorage.setItem(MOTION_KEY, String(next));
    window.dispatchEvent(new CustomEvent(MOTION_EVENT, { detail: { paused: next } }));
  }

  return (
    <button type="button" className="motion-toggle" onClick={toggle} aria-pressed={reduced} aria-label={reduced ? "Enable motion" : "Reduce motion"}>
      {reduced ? <Play size={14} /> : <Pause size={14} />}
      <span>{reduced ? "Motion off" : "Motion on"}</span>
    </button>
  );
}

components/motion/editorial-heading.tsx:
"use client";

import { useEffect, useRef, useState } from "react";
import { HERO_TUNING } from "@/lib/motion/hero-tuning";
import { RiseIn } from "./primitives";
import { useReducedMotion } from "./use-reduced-motion";

// Find the existing visual lines without inserting hard breaks or changing a byte
// of the heading. No duplicate measuring copy or character spans are rendered.
function renderedLines(element: HTMLHeadingElement, text: string) {
  const node = element.firstChild;
  if (!node || node.nodeType !== Node.TEXT_NODE) return [text];
  const range = document.createRange();
  const starts = [0];
  let top: number | undefined;
  for (const word of text.matchAll(/\S+/gu)) {
    range.setStart(node, word.index);
    range.setEnd(node, word.index + word[0].length);
    const bounds = range.getBoundingClientRect();
    if (top !== undefined && Math.abs(bounds.top - top) > 1) starts.push(word.index);
    top = bounds.top;
  }
  return starts.map((start, index) => text.slice(start, starts[index + 1]));
}

export function EditorialHeading({ children, delay = 0 }: { children: string; delay?: number }) {
  const heading = useRef<HTMLHeadingElement>(null);
  const entered = useRef(false);
  const reduced = useReducedMotion();
  const [reveal, setReveal] = useState<{ lines: string[]; clock: number } | null>(null);
  useEffect(() => {
    const element = heading.current;
    if (!element || reduced || entered.current) return;
    let firstObservation = true;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const observer = new IntersectionObserver(([entry]) => {
      const initial = firstObservation;
      firstObservation = false;
      if (!entry.isIntersecting) return;
      entered.current = true;
      observer.disconnect();
      if (initial) return;
      const lines = renderedLines(element, children);
      setReveal({ lines, clock: Number(document.timeline.currentTime ?? performance.now()) });
      timer = setTimeout(() => setReveal(null), delay + HERO_TUNING.headline.duration + (lines.length - 1) * HERO_TUNING.headline.stagger + 100);
    });
    observer.observe(element);
    return () => { observer.disconnect(); clearTimeout(timer); };
  }, [children, delay, reduced]);

  useEffect(() => {
    const element = heading.current;
    if (!element) return;
    let width = element.clientWidth;
    const resize = new ResizeObserver(() => {
      if (element.clientWidth === width) return;
      width = element.clientWidth;
      // Cancel a running reveal on reflow; normal text wrapping takes over at once.
      setReveal(null);
    });
    resize.observe(element);
    return () => resize.disconnect();
  }, []);

  return <h2 ref={heading}>{reveal ? reveal.lines.map((line, index) =>
    <RiseIn key={index} as="span" className="editorial-heading-line" rise={HERO_TUNING.headline.rise * .6}
      rotate={HERO_TUNING.headline.rotation} duration={HERO_TUNING.headline.duration}
      delay={delay} stagger={HERO_TUNING.headline.stagger} index={index} timelineStart={reveal.clock}>{line}</RiseIn>
  ) : children}</h2>;
}

