import { clamp } from "./tokens";

// Never divide by sectionHeight - viewportHeight: a fully visible section must
// have a stable, reversible position, including when those dimensions are equal.
export function processProgress(top: number, height: number, viewport: number) {
  return clamp((viewport * .75 - top) / Math.max(1, height + viewport * .5), 0, 1);
}
export function processStepWeight(progress: number, index: number, count: number) {
  return clamp(1 - Math.abs(clamp(progress, 0, 1) * Math.max(0, count - 1) - index), 0, 1);
}

lib/motion/scroll-lock.ts:
// Menu locks share the existing Lenis owner, including before its lazy runtime loads.
const locks = new Set<symbol>();
const listeners = new Set<() => void>();
const notify = () => listeners.forEach(listener => listener());

export const isScrollLocked = () => locks.size > 0;
export function subscribeScrollLock(listener: () => void) {
  listeners.add(listener);
  return () => { listeners.delete(listener); };
}
export function acquireScrollLock() {
  const key = Symbol("navigation");
  locks.add(key);
  notify();
  return () => { if (locks.delete(key)) notify(); };
}

lib/motion/shared-pointer.ts:
import { cancelFrame, frame } from "framer-motion";

export type SharedPointer = { x: number; y: number; target: Element } | null;
const subscribers = new Set<(point: SharedPointer) => void>();
let pending: SharedPointer = null;
function flush() { subscribers.forEach(subscriber => subscriber(pending)); }
// The existing ImageFeedback recognizer is the sole DOM pointer-event owner.
export function queueSharedPointer(point: SharedPointer) {
  if (!subscribers.size) return;
  pending = point;
  frame.read(flush);
}
export function subscribeSharedPointer(subscriber: (point: SharedPointer) => void) {
  subscribers.add(subscriber);
  return () => { subscribers.delete(subscriber); if (!subscribers.size) { cancelFrame(flush); pending = null; } };
}

lib/motion/tokens.ts:
import { cubicBezier } from "framer-motion";

// Safety bounds remain enforced even if a consumer supplies invalid props/tokens.
export const MAX_TRANSLATION = 40;
export const MAX_ROTATION = 12;
export const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, Number.isFinite(value) ? value : min));
export function readDepthTokens(element: HTMLElement) {
  const css = getComputedStyle(element);
  const number = (name: string) => parseFloat(css.getPropertyValue(name));
  const easing = css.getPropertyValue("--ease-out-expo").trim();
  const points = easing.slice(easing.indexOf("(") + 1, -1).split(",").map(Number);
  return {
    easing,
    ease: cubicBezier(points[0], points[1], points[2], points[3]),
    duration: number("--d-base"),
    rest: number("--d-fast"),
    rise: clamp(number("--depth-rise"), 0, MAX_TRANSLATION),
    rotation: clamp(number("--depth-rotate"), 0, MAX_ROTATION),
    from: clamp(number("--depth-parallax-from"), -MAX_TRANSLATION, MAX_TRANSLATION),
    to: clamp(number("--depth-parallax-to"), -MAX_TRANSLATION, MAX_TRANSLATION),
    scaleFrom: number("--depth-scale-from"),
    scaleTo: number("--depth-scale-to"),
  };
}

