  --z-pop: 90px;
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --d-fast: 240ms;
  --d-base: 600ms;
  --d-slow: 900ms;
  --d-reduced: 150ms;
  --depth-rise: 40px;
  --depth-rotate: 12deg;
  --depth-parallax-from: -40px;
  --depth-parallax-to: 20px;
  --depth-scale-from: 1.04;
  --depth-scale-to: 1;
}

@media (width < 768px) {
  :root {
    --z-back: -40px;
    --z-mid: 0;
    --z-front: 20px;
    --z-pop: 45px;
    --depth-parallax-from: -20px;
    --depth-parallax-to: 10px;
  }
}

/* Only the provider enables this. Native behavior returns when Lenis is destroyed. */
html[data-depth-scroll="smooth"] { scroll-behavior: auto !important; }
.depth-section, .parallax-media {
  perspective: var(--perspective);
  transform-style: preserve-3d;
}
[data-depth-motion] {
  transform: none;
  opacity: 1;
  transform-style: preserve-3d;
  animation-timing-function: var(--ease-out-expo);
  transition-timing-function: var(--ease-out-expo);
}

/* Touch never opts into pointer transforms. Scroll depth is a separate layer. */
@media (hover: none), (width < 768px) {
  [data-depth-pointer] { transform: none !important; will-change: auto !important; }
}

/* Final state wins even before hydration or while an animation is being cancelled. */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto !important; }
  .depth-section, .parallax-media { perspective: none !important; transform-style: flat !important; }
  [data-depth-motion], [data-depth-pointer] {
    transform: none !important;
    translate: none !important;
    rotate: none !important;
    scale: none !important;
    opacity: 1 !important;
    animation: none !important;
    transition-property: opacity !important;
    transition-duration: var(--d-reduced) !important;
    transition-delay: 0ms !important;
    will-change: auto !important;
  }
}

styles/editorial-depth.css:
/* Existing editorial columns, spacing, image frames and responsive order remain. */
.editorial-motion { --editorial-text-z: 12px; }
.editorial-motion .editorial-media { min-width: 0; transform-style: flat; }
.editorial-motion .editorial-grid-reverse > .editorial-media { order: 2; }
.editorial-motion .editorial-text-plane {
  transform: translateZ(var(--editorial-text-z));
  transform-style: preserve-3d;
}
.editorial-motion .editorial-text-enter,
.editorial-motion .editorial-prose { display: flow-root; }
.editorial-motion .editorial-prose > p { color: var(--muted); font-size: 1rem; }
.international-feature.editorial-motion .editorial-prose > p { color: #b7cbd3; }
.editorial-motion .editorial-heading-line { display: block; }
.editorial-motion h2 { perspective: var(--perspective); }
.editorial-motion .editorial-text-enter:focus-within { transform: none !important; opacity: 1 !important; }
@media (max-width: 900px) {
  .editorial-motion .editorial-grid-reverse > .editorial-media { order: initial; }
}
@media (width < 768px) {
  .editorial-motion { --editorial-text-z: 6px; }
}
@media (prefers-reduced-motion: reduce) {
  .editorial-motion .editorial-text-plane { transform: none !important; transform-style: flat; }
  .editorial-motion h2 { perspective: none; }
}

styles/hero.css:
/* Homepage hero only. The original section remains the layout/scroll anchor. */
.cinematic-hero.hero-motion { overflow: clip; }
.cinematic-hero.hero-motion::before { content: none; }
.hero-motion .hero-depth { position: relative; margin-top: -92px; --hero-depth-factor: 1; --hero-emphasis-z: calc(var(--hero-emphasis-base) * var(--hero-depth-factor)); }
.hero-motion .hero-stage {
  position: relative;
  padding-top: 92px;
  perspective: var(--perspective);
  /* Project the inner planes once before the whole group recedes/fades. */
  transform-style: flat;
}
.hero-motion .hero-back, .hero-motion .hero-mid { position: absolute; inset: 0; pointer-events: none; }
.hero-motion .hero-back {
  background: #0b2639;
  transform: translate3d(var(--hero-pointer-x, 0px), var(--hero-pointer-y, 0px), var(--z-back)) scale(var(--hero-back-scale));
}
.hero-motion .hero-mid {
  inset: calc(-1 * var(--hero-mid-overscan));
  transform: translate3d(var(--hero-pointer-x, 0px), var(--hero-pointer-y, 0px), 0px);
}
/* Preserve the exact intentional hero contrast, now on the image's own plane. */
.hero-motion .hero-mid::after {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(90deg, rgba(6,24,37,.94) 0%, rgba(9,36,53,.85) 32%, rgba(9,36,53,.48) 53%, rgba(8,31,46,.12) 78%, rgba(8,31,46,.2) 100%);
}
.hero-motion .cinematic-hero-content { z-index: auto; transform-style: preserve-3d; }
.hero-motion .cinematic-copy {
  transform-style: preserve-3d;
  transform: translate3d(var(--hero-pointer-x, 0px), var(--hero-pointer-y, 0px), var(--z-front));
}
.hero-motion h1 { transform-style: preserve-3d; }
.hero-motion .hero-line { display: inline-block; transform-style: preserve-3d; }
.hero-motion .hero-line-borders { transform: translateZ(var(--hero-emphasis-z)); }
/* Margins remain on the original paragraphs/action row, not on new motion wrappers. */
.hero-motion .hero-follow { display: flow-root; }

@media (max-width: 900px) {
  .hero-motion .hero-mid::after { background: linear-gradient(180deg, rgba(6,24,37,.9) 0%, rgba(9,36,53,.84) 40%, rgba(9,36,53,.64) 70%, rgba(8,31,46,.3) 100%); }
}
@media (width < 768px) {
  .hero-motion .hero-depth { --hero-depth-factor: 0.5; --hero-mid-overscan: 0px !important; }
}
@media (hover: none), (width < 768px) {
  .hero-motion [data-hero-plane] { --hero-pointer-x: 0px !important; --hero-pointer-y: 0px !important; }
}
@media (prefers-reduced-motion: reduce) {
  .hero-motion .hero-stage { perspective: none !important; }
  .hero-motion .hero-mid { inset: 0; }
  .hero-motion [data-depth-motion] { transform: none !important; opacity: 1 !important; will-change: auto !important; }
}

/* A keyboard user never waits for an entrance before seeing the focused CTA. */
.hero-motion .hero-follow:focus-within { opacity: 1 !important; transform: none !important; }
.hero-motion .cinematic-copy:focus-within { --hero-pointer-x: 0px !important; --hero-pointer-y: 0px !important; }

styles/navigation.css:
/* Stage 4 is confined to the existing navigation and its presentation wrapper. */
.site-header.nav-depth-shell {
  --nav-z: 60px;
  --nav-plane-scale: .95; /* Compensate perspective magnification; retain the existing layout. */
  --nav-label-z: 8px;
  --nav-scroll-duration: 200ms;
  --nav-door-duration: 380ms;
  --nav-door-angle: -12deg;
  --nav-background: rgba(247,246,241,.85);
  --nav-border: rgba(255,255,255,.7);
  --nav-shadow: 0 16px 50px rgba(14,42,60,.1);
  --nav-scroll-shadow: 0 22px 55px rgba(14,42,60,.24);
  perspective: var(--perspective);
  perspective-origin: center top;
  transform-style: preserve-3d;
  overflow: visible;
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  backdrop-filter: none;
}
.site-header.nav-depth-shell.home-header {
  --nav-background: rgba(7,27,41,.82);
  --nav-border: rgba(255,255,255,.11);
  --nav-shadow: 0 16px 45px rgba(0,0,0,.18);
  --nav-scroll-shadow: 0 24px 55px rgba(0,0,0,.32);
}
.nav-depth-shell .nav-surface {
  position: relative;
  border-radius: inherit;
  transform-origin: center top;
  transform: translateZ(var(--nav-z)) scale(var(--nav-plane-scale));
  transform-style: preserve-3d;
}
.nav-depth-shell .nav-surface::before,
.nav-depth-shell .nav-surface::after {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  pointer-events: none;
}
.nav-depth-shell .nav-surface::before {
  z-index: -1;
  background: var(--nav-background);
  border: 1px solid var(--nav-border);
  box-shadow: var(--nav-shadow);
  backdrop-filter: blur(0px);
  transition: backdrop-filter var(--nav-scroll-duration) var(--ease-out-expo);
}
.nav-depth-shell .nav-surface::after {
  z-index: -2;
  box-shadow: var(--nav-scroll-shadow);
  opacity: 0;
  transition: opacity var(--nav-scroll-duration) var(--ease-out-expo);
}
.nav-depth-shell[data-nav-scrolled="true"] .nav-surface::before { backdrop-filter: blur(16px); }
.nav-depth-shell[data-nav-scrolled="true"] .nav-surface::after { opacity: 1; }
.nav-depth-shell .header-inner {
  /* Project link/button depth locally, then group it above the bar's backplate.
     A tilted button must never intersect that sibling background plane. */
  perspective: var(--perspective);
  perspective-origin: center top;
  transform-style: flat;
}
.nav-depth-shell .nav { transform-style: preserve-3d; }
.nav-depth-shell .brand,
.nav-depth-shell .menu-button,
.nav-depth-shell .nav > a { position: relative; }
.nav-depth-shell :is(a, button):focus-visible { z-index: 100; }
/* A real keyboard event clears this flag before focus moves, restoring the
   global :focus-visible ring. Mouse/touch focus stays in place without a box. */
.nav-depth-shell[data-nav-pointer-focus] :is(a, button):focus-visible { outline: none; }
.nav-depth-shell .nav > a {
  transform: none;
  transition: transform var(--d-fast) var(--ease-out-expo);
}
.nav-depth-shell .nav > a:not(.button)::after {
  right: 0;
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform var(--d-fast) var(--ease-out-expo);
}
.nav-depth-shell .nav > a:not(.button):focus-visible::after { transform: scaleX(1); }
.nav-depth-shell .nav > .button { color: white; transform-style: preserve-3d; }
.nav-depth-shell .nav > .button::before {
  content: "";
  position: absolute;
  inset: -9px;
  z-index: -1;
  border-radius: inherit;
  background: radial-gradient(ellipse, rgba(39,140,160,.45), rgba(39,140,160,0) 72%);
  pointer-events: none;
  opacity: 0;
  transition: opacity var(--d-fast) var(--ease-out-expo);
}
@media (hover: hover) and (min-width: 768px) {
  .nav-depth-shell[data-nav-pointer="true"] .nav > a:not(.button):hover { transform: translateY(-1px) translateZ(var(--nav-label-z)); }
  .nav-depth-shell .nav > a:not(.button):hover::after { transform: scaleX(1); }
  .nav-depth-shell[data-nav-pointer="true"] .nav > .button:hover { transform: rotateX(-8deg); }
  .nav-depth-shell .nav > .button:hover::before { opacity: 1; }
}
.site-header.nav-depth-shell .nav > .button:active { transform: translateZ(0) scale(.97); }

@container (max-width: 64rem) {
  .nav-depth-shell .nav {
    transform-origin: right top;
    transform-style: flat;
  }
  .nav-depth-shell .nav.open { animation: nav-door-in var(--nav-door-duration) var(--ease-out-expo) both; }
}
@keyframes nav-door-in {
  from { transform: rotateY(var(--nav-door-angle)); opacity: 0; }
  to { transform: rotateY(0deg); opacity: 1; }
}
@keyframes nav-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
@media (width < 768px) {
  .site-header.nav-depth-shell { --nav-z: 30px; --nav-plane-scale: .975; --nav-label-z: 4px; }
}
@media (prefers-reduced-motion: reduce) {
  .site-header.nav-depth-shell { perspective: none; transform-style: flat; }
  .nav-depth-shell .nav-surface,
  .nav-depth-shell .nav,
  .nav-depth-shell .header-inner { transform: none !important; transform-style: flat; perspective: none; }
  .nav-depth-shell .nav > a,
  .nav-depth-shell .nav > a::after { transform: none !important; transition: none; }
  .nav-depth-shell .nav > a:not(.button)::after { opacity: 0; }
  .nav-depth-shell .nav > a:not(.button):is(:hover, :focus-visible)::after { opacity: 1; }
  .nav-depth-shell .nav-surface::before { transition: none; }
  .nav-depth-shell .nav-surface::after,
  .nav-depth-shell .nav > .button::before { transition-duration: var(--d-reduced); }
  .nav-depth-shell .nav.open {
    animation: nav-fade-in var(--d-reduced) var(--ease-out-expo) both;
    animation-duration: var(--d-reduced) !important;
  }
}

styles/process-depth.css:
.process-depth {
  --process-active-z: 60px;
  --process-inactive-z: -30px;
  --process-inactive-opacity: .55;
  position: relative;
  margin-top: 58px;
}
.process-depth .process-list {
  margin-top: 0;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  /* Each step has a local vanishing point: Z must not push end columns outside
     the shell, or send a long mobile sequence toward a distant shared origin. */
  transform-style: flat;
}
.process-depth .process-list > li {
  transform-origin: center;
  /* Local CSS perspective preserves the requested Z without lateral drift. */
  transform: none;
  opacity: 1;
  --process-emphasis: 0;
}
.process-depth .process-list > li > span { position: relative; isolation: isolate; }
.process-depth .process-list > li > span::before {
  content: "";
  position: absolute;
  width: 44px;
  height: 32px;
  left: -14px;
  top: 50%;
  transform: translateY(-50%);
  z-index: -1;
  pointer-events: none;
  background: radial-gradient(ellipse, rgb(36 158 169 / .32), transparent 70%);
  opacity: var(--process-emphasis);
}
.process-connector {
  position: absolute;
  inset: 0 0 auto;
  width: 100%;
  height: 2px;
  overflow: visible;
  pointer-events: none;
}
.process-connector line {
  fill: none;
  stroke: var(--teal);
  stroke-width: 2;
  stroke-dasharray: 1;
  stroke-dashoffset: 0;
}
.process-line-vertical { display: none; }
@media (width >= 768px) {
  .process-depth .process-list > li { border-top: 0; }
  .process-depth .process-list > li + li { border-left-color: #d0d9db; }
}
@media (width < 768px) {
  .process-depth .process-list { grid-template-columns: 1fr; }
  .process-depth .process-list > li { border-left: 0; padding: 27px 0; min-height: 0; }
  .process-depth .process-list > li + li { border-top: 1px solid #d0d9db; }
  .process-depth .process-connector { inset: 0 auto 0 -8px; width: 2px; height: 100%; }
  .process-depth .process-line-horizontal { display: none; }
  .process-depth .process-line-vertical { display: initial; }
}
@media (width < 768px) {
  .process-depth { --process-active-z: 30px; --process-inactive-z: -15px; }
}
@media (prefers-reduced-motion: reduce) {
  .process-depth .process-list { perspective: none !important; }
  .process-depth .process-list > li { transform: none !important; opacity: 1 !important; will-change: auto !important; }
  .process-depth .process-list > li > span::before { opacity: 0 !important; }
  .process-depth .process-connector line { stroke-dashoffset: 0 !important; }
}

styles/utility-depth.css:
.faq-depth, .form-depth, .footer-depth {
  --faq-hinge: -6deg;
  --form-plane-z: 30px;
  --form-plane-compensation: .975;
  --field-z: 12px;
  --footer-z: -20px;
  --utility-label-rise: -2px;
  --utility-link-rise: -1px;
  --utility-press-angle: -8deg;
  --utility-press-scale: .97;
}
/* Replace the legacy whole-card sideways jump and shadow transition. */
.faq-depth .faq-item,
.faq-depth .faq-item[open] { transform: none; transition: none; box-shadow: 0 12px 34px rgba(20,49,67,.07); }
.faq-depth .faq-item > p { transform-origin: center top; }
.faq-depth .faq-item > summary { position: relative; }
.faq-depth .faq-item:focus-within { z-index: 1; }
.faq-depth[data-utility-ready] summary::after { transition: transform var(--d-fast) var(--ease-out-expo); }
.faq-depth[data-utility-ready] details[open] summary::after { transform: rotate(180deg); }

.form-depth { min-width: 0; }
.form-depth[data-utility-ready] > .form-panel {
  /* Compensate the static plane's projection to preserve the existing form
     width, field alignment and notice position. The original soft shadow stays. */
  transform: perspective(var(--perspective)) translateZ(var(--form-plane-z)) scale(var(--form-plane-compensation));
}
.form-depth[data-utility-ready] .field { position: relative; }
.form-depth[data-utility-ready] .field:focus-within { z-index: 2; }
.form-depth[data-utility-ready] .field > :is(input, select, textarea),
.form-depth[data-utility-ready] .field > label,
.form-depth[data-utility-ready] .button {
  transition: transform var(--d-fast) var(--ease-out-expo);
}
.form-depth[data-utility-ready] .field > :is(input, select, textarea):focus-visible {
  transform: perspective(var(--perspective)) translateZ(var(--field-z));
}
.form-depth[data-utility-ready] .field:focus-within > label { transform: translateY(var(--utility-label-rise)); }
.form-depth[data-utility-ready] .button { position: relative; isolation: isolate; transform: none; }
.form-depth .button::before {
  content: "";
  position: absolute;
  inset: -9px;
  z-index: -1;
  border-radius: inherit;
  pointer-events: none;
  background: radial-gradient(ellipse, rgb(39 140 160 / .45), transparent 72%);
  opacity: 0;
  transition: opacity var(--d-fast) var(--ease-out-expo);
}
/* The enquiry notice has no reveal, delay or opacity treatment. */
.footer-depth[data-utility-ready] { transform: perspective(var(--perspective)) translateZ(var(--footer-z)); }
.footer-depth[data-utility-ready] .footer-col a { transition: transform var(--d-fast) var(--ease-out-expo); }
.footer-depth .footer-col a:focus-visible { position: relative; z-index: 1; }
@media (hover: hover) and (width >= 768px) {
  .form-depth[data-utility-ready][data-utility-pointer="true"] .button:hover:not(:disabled) { transform: perspective(var(--perspective)) rotateX(var(--utility-press-angle)); }
  .form-depth[data-utility-ready] .button:hover:not(:disabled)::before { opacity: 1; }
  .footer-depth[data-utility-ready][data-utility-pointer="true"] .footer-col a:hover { transform: translateY(var(--utility-link-rise)); }
}
/* Active wins over hover, including when both apply. */
.form-depth[data-utility-ready][data-utility-pointer] .button:active:not(:disabled) { transform: perspective(var(--perspective)) translateZ(0) scale(var(--utility-press-scale)); }
@media (width < 768px) {
  .form-depth, .footer-depth { --form-plane-z: 15px; --form-plane-compensation: .9875; --field-z: 6px; --footer-z: -10px; }
}
@media (prefers-reduced-motion: reduce) {
  .faq-depth { perspective: none; }
  .faq-depth .faq-item, .faq-depth .faq-item > p, .faq-depth summary, .faq-depth summary::after,
  .form-depth > .form-panel, .form-depth .field > :is(input, select, textarea, label),
  .form-depth .button, .footer-depth, .footer-depth .footer-col a {
    transform: none !important;
    animation: none !important;
    opacity: 1 !important;
    will-change: auto !important;
    transition-property: opacity !important;
    transition-duration: var(--d-reduced) !important;
  }
  .form-depth .button::before { transition-duration: var(--d-reduced); }
}
